/**
 * ביאור פשט מודרני מקיף לספר תהילים (כל 150 הפרקים, 2,527 פסוקים)
 * ביאור בהיר, מדויק ועכשווי המנגיש את ספר תהילים לכל קורא בן זמננו.
 * נוצר במסגרת פרויקט תנ"ך פשט לכתובים.
 */
window.PeshatTehillim = {
  "1_1": "כמה מאושר ומבורך האדם שלא הלך בעצת הרשעים, לא עמד והתחבר בדרכם של החוטאים, ולא ישב בחברתם של אנשים לגלגנים וציניים.",
  "1_2": "אלא כל רצונו ותשוקתו הם בתורת ה', ובתורתו הוא מעמיק ומהרהר יום ולילה.",
  "1_3": "הוא יהיה מוצלח וחיוני כמו עץ הנטוע על פלגי מים, שנותן את פירותיו בעיתם ועליו אינם נובלים, ובכל מעשיו הוא יצליח.",
  "1_4": "לא כך הם הרשעים; הם חסרי יציבות וחסרי ערך כמו מוץ שרוח קלה מעיפה אותו ומפזרת אותו לכל עבר.",
  "1_5": "לכן הרשעים לא יוכלו לעמוד ולהצדיק את עצמם ביום המשפט, והחוטאים לא יהיה להם מקום בעדת הצדיקים.",
  "1_6": "כי ה' מכיר, משגיח ושומר על דרכם של הצדיקים, אך דרכם של הרשעים מובילה לאבדון ולכישלון מוחלט.",
  "2_1": "מדוע עמי העולם רוגשים וסוערים, והאומות הוגות מזימות שווא חסרות סיכוי?",
  "2_2": "מלכי הארץ מתייצבים במרד ושליטים מתייעצים יחד נגד ה' ונגד המלך המשיח שמשח למלוך.",
  "2_3": "הם אומרים: ננתק את הכבלים והאיסורים שהם שמים עלינו, ונשליך מעלינו את עולם ומרותם.",
  "2_4": "אך ה' היושב בשמיים צוחק עליהם; ה' מלגלג על תוכניותיהם ומזימותיהם.",
  "2_5": "אז הוא ידבר אליהם בכעסו הגדול, ובחרון אפו יבהיל וישתק אותם.",
  "2_6": "ואומר להם: הרי אני הוא שהכתרתי ומשחתי את מלכי על הר ציון, ההר הקדוש שלי.",
  "2_7": "המלך אומר: אספר את גזרת ה' וחוקו – ה' אמר לי: אתה לי כבן, אני ביום הזה הכתרתי והולדת אותך להנהגה.",
  "2_8": "בקש ממני ואתן לך את כל העמים כנחלתך, ואת קצוות תבל כאחוזת שליטתך.",
  "2_9": "תשבור ותכניע את אויביך בשרביט ברזל תקיף, ותרסק אותם בקלות כמו כלי חרס שנשבר לרסיסים.",
  "2_10": "ועתה, מלכים ושליטים, גלו חוכמה ותבונה; קבלו מוסר ולקח, שופטי ומנהיגי הארץ.",
  "2_11": "עבדו את ה' ביראת כבוד, ושמחו בחסדו בחרדה וביראת רוממות.",
  "2_12": "הצטיידו בכניעה ובנאמנות כדי שלא יכעס עליכם ותאבדו בדרככם ברגע שיבער כעסו הקל; אשרי כל הבוטחים בו ומוצאים בו מחסה.",
  "3_1": "מזמור שחיבר דוד כאשר ברח מפני בנו אבשלום שמרד בו.",
  "3_2": "ה', כמה רבים הפכו להיות אויביי ומבקשי רעתי; רבים וגדולים קמים להילחם בי!",
  "3_3": "רבים אומרים עליי בייאוש: אין לו עוד שום סיכוי לתשועה ולהצלה מאת אלוהים.",
  "3_4": "אבל אתה, ה', מגן עליי ושומר על נפשי מכל עבר; אתה כבודי ואתה המרים את ראשי ומשיב לי את ביטחוני.",
  "3_5": "בקולי אקרא אל ה' בתפילה, והוא עונה לי מהר קודשו ומקבל את זעקתי.",
  "3_6": "שכבתי לישון ברוגע והתעוררתי בבטחה, משום שה' תומך בי ומגן עליי תמיד.",
  "3_7": "לא אפחד מרבבות אנשים ומצבאות עצומים שמקיפים אותי מכל עבר כדי לפגוע בי.",
  "3_8": "קום, ה', והושע אותי אלוהיי! הרי אתה הִכית את כל אויביי מכה משפילה בלחי ושברת את שיני הרשעים כדי שלא יוכלו להזיק.",
  "3_9": "הישועה האמיתית שייכת רק לה', וברכתך והשגחתך שרויות תמיד על עמך.",
  "4_1": "למנצח על כלי נגינה, מזמור שחיבר דוד.",
  "4_2": "כאשר אני קורא אליך – ענה לי, אלוהיי שמצדיק אותי! בעת צרה ומצוקה הרחבת לי והקלת עליי; חמול עליי עתה ושמע את תפילתי.",
  "4_3": "אנשים נכבדים, עד מתי תהפכו את כבודי לחרפה ולבושה? עד מתי תאהבו דברי הבל ותרדפו אחרי שקר וכזב?",
  "4_4": "דעו לכם כי ה' הבדיל וייחד לעצמו את מי שמתנהג בחסידות ובצדק; ה' ישמע ויענה כאשר אקרא אליו.",
  "4_5": "חרדו מיראת ה' ואל תחטאו; חשבו והתבוננו בלבבכם בשקט על מיטתכם, והירגעו.",
  "4_6": "הקריבו קורבנות של צדק ומעשים טובים, ובטחו בה' בלב שלם.",
  "4_7": "רבים אומרים בייאוש: מי יראה לנו ימים טובים וטוב אמיתי? האר והרעף עלינו את טוב פניך, ה'.",
  "4_8": "אתה נתת שמחה גדולה בלבי, שמחה עמוקה יותר משמחתם של האנשים בזמן שתבואתם ותירושם מתרבים בשפע.",
  "4_9": "בשלווה ובביטחון מוחלט אשכב לישון וארדם מיד, כי אתה, ה', לבדך מושיב אותי לבטח ושומר עליי מכל רע.",
  "5_1": "למנצח בליווי כלי נגינה, מזמור לדוד.",
  "5_2": "הקשב לדבריי, ה', והבן את רחשי לבי ואת תפילתי השקטה.",
  "5_3": "האזן לקול זעקתי ומצוקתי, מלכי ואלוהיי, כי אליך בלבד אני מתפלל.",
  "5_4": "ה', כבר בשעות הבוקר המוקדמות תשמע את קולי; עם שחר אערוך לפניך את תפילתי ואצפה למענך.",
  "5_5": "כי אינך אל החפץ ברשע ובשחיתות, והרע אינו יכול להתגורר במחיצתך.",
  "5_6": "אנשים חצופים והולכי רכיל לא יוכלו לעמוד לפניך; אתה שונא את כל עושי העוול והפשע.",
  "5_7": "אתה משמיד את דוברי השקר והכזב; ה' מתעב אנשים ששופכים דמים ומתנהלים במרמה.",
  "5_8": "ואילו אני, בזכות חסדך הגדול, אבוא לביתך ואשתחווה ביראת כבוד אל עבר היכל קודשך.",
  "5_9": "ה', הדרך והנחה אותי בדרך צדקתך כדי שלא אפול בידי אויביי האורבים לי; יישר לפניי את דרכך כדי שלא אסטה ממנה.",
  "5_10": "כי אין בפיהם של אויביי שום מילה של אמת ונאמנות, בקרבם יש רק כוונות הרס ורשע, גרונם פתוח כקבר לבלוע אנשים, ולשונם מדברת חנופה מטעה.",
  "5_11": "הטל עליהם אשמה, אלוהים, והפיל אותם במזימותיהם שלהם; גרש אותם בגלל פשעיהם הרבים, כי הם מרדו בך ובדרכך.",
  "5_12": "וישמחו כל אלה שמוצאים בך מחסה, לעולם ירננו וישירו משמחה כאשר תפרוש עליהם את הגנתך, ויעלצו בך כל אוהבי שמך.",
  "5_13": "כי אתה מברך את הצדיק, ה', ועוטף אותו ברצונך הטוב ובאהבתך כמו מגן רחב שמגן על כל גופו.",
  "6_1": "למנצח בנגינה על כלי בעל שמונה מיתרים, מזמור לדוד.",
  "6_2": "ה', אל תוכיח אותי מתוך כעס גדול, ואל תייסר אותי בחמת זעם.",
  "6_3": "חמול עליי, ה', כי אני חלש ותשוש; רפא אותי, ה', כי עצמותיי כואבות ורועדות מרוב פחד וחולשה.",
  "6_4": "נפשי מבוהלת ומיוסרת עד מאוד; ואתה ה', עד מתי תתעכב מלהושיע אותי?",
  "6_5": "שוב אליי, ה', וחלץ את נפשי מן הסבל; הושע והצל אותי בזכות חסדך ואהבתך.",
  "6_6": "כי לאחר המוות אין אפשרות לזכור אותך ולהזכיר את שמך, ובקבר – מי יוכל להודות לך ולשבח אותך?",
  "6_7": "התעייפתי ונלאיתי מאנחותיי הכבדות; בכל לילה מיטתי רטובה מבכי, ובדמעותיי הרבות אני מרטיב את יצועי.",
  "6_8": "עיניי נחלשו וכהו מרוב צער וכעס, והזדקנו ונשחקו בגלל כל אויביי המציקים לי.",
  "6_9": "התרחקו ממני, כל עושי העוול והפשע, כי ה' שמע את קול בכיי ומצוקתי.",
  "6_10": "ה' שמע את תחנוניי ובקשתי, ה' מקבל ורוצה את תפילתי.",
  "6_11": "כל אויביי יתביישו וייבהלו מאוד; הם ייסוגו אחורנית ויתביישו פתאום ברגע אחד.",
  "7_1": "שיר תפילה נרגש לדוד, אשר שר לה' בעקבות דברי השמצה והאשמות של כוש איש שבט בנימין.",
  "7_2": "ה' אלוהיי, בך שמתי את מבטחי ואת ביטחוני; הושע אותי מכל הרודפים אחריי והצל אותי.",
  "7_3": "פן יטרוף האויב את נפשי כאריה שקורע את טרפו לחתיכות ואין מי שיציל.",
  "7_4": "ה' אלוהיי, אם עשיתי את המעשה המיוחס לי, ואם יש עוול ואי-צדק במעשי ידיי:",
  "7_5": "אם גמלתי רע למי שהיה בשלום עמי, או אם נישלתי ופגעתי באויבי ללא סיבה מוצדקת:",
  "7_6": "שירדוף האויב אחריי וישיג אותי, שירמוס את חיי עד עפר, ויוריד את כבודי לאדמה!",
  "7_7": "קום, ה', בכעסך הצודק, התנשא כנגד זעמם של אויביי, והתעורר לעשות למעני את המשפט והצדק שציווית בעולם.",
  "7_8": "עדת עמים תקיף אותך לצפות בדינך, ומעליהם שוב לשבת במרומים כשופט כל הארץ.",
  "7_9": "ה' ישפוט ויכריע בין העמים; שפוט גם אותי, ה', לפי צדקתי ויושרת לבי הראויה.",
  "7_10": "הלוואי שיסתיים כבר ויאבד הרוע של הרשעים, ותחזק ותבסס את דרכם של הצדיקים, שהרי אתה, אלוהים צדיק, בוחן את מעמקי הלב ואת המחשבות הנסתרות ביותר.",
  "7_11": "מגיני והגנתי מוטלים על אלוהים, אשר מושיע את האנשים שישרים בלבבם.",
  "7_12": "אלוהים הוא שופט צדק והגון, ואל שכועס בכל יום על הרשע והעוול.",
  "7_13": "אם החוטא לא ישוב מדרכו הרעה, אלוהים ילטוש את חרבו וידרוך את קשתו לפגוע בו.",
  "7_14": "והוא הכין נגדו כלי מוות ועונש, ואת חיציו הפך לחיצים בוערים ופוגעים.",
  "7_15": "הנה הרשע מתכנן עוול, מתמלא ברוע ומוליד שקר ואכזבה.",
  "7_16": "הוא חפר בור עמוק כדי להפיל אחרים, אך בסופו של דבר הוא עצמו נופל לתוך הבור שחפר במו ידיו.",
  "7_17": "העוול שביקש לעשות יחזור וייפול על ראשו שלו, ומעשה החמס והאלימות שלו יירד על קודקודו.",
  "7_18": "אני אודה לה' על צדקתו הגדולה, ואשיר שיר תהילה לשמו של ה' העליון.",
  "8_1": "למנצח על כלי הנגינה הגיתית, מזמור לדוד.",
  "8_2": "ה' אדוננו ושליטנו, כמה אדיר ונהדר שמך בכל רחבי הארץ! אשר שמת את הודך ותפארתך גבוה מעל השמיים.",
  "8_3": "אפילו מפי תינוקות ויונקים קטנים ייסדת עדות לגבורתך ולעוצמתך כנגד אויביך, כדי להשתיק ולהכניע כל אויב ומבקש נקמה.",
  "8_4": "כאשר אני מביט בשמיים שלך, שהם מעשי אצבעותיך, ובירח ובכוכבים הרבים שכוננת וקבעת במקומם:",
  "8_5": "מהו האדם החלש והקטן שאתה זוכר אותו, ומהו בן האנוש שאתה משגיח עליו ודואג לו?",
  "8_6": "והנה החסרת אותו רק מעט ממלאכי השרת והיצורים העליונים, ועיטרת אותו בכבוד ובהדר מלכותי!",
  "8_7": "נתת לו שלטון ואחריות על כל מעשי ידיך בבריאה, ואת הכל שמת תחת סמכותו ורגליו:",
  "8_8": "את כל הצאן והבקר כולם, וגם את חיות הבר שפרוסות בשדות;",
  "8_9": "את עופות השמיים ואת דגי הים, וכל בעל חיים העובר בנתיבי המים של האוקיינוסים.",
  "8_10": "ה' אדוננו ושליטנו, כמה אדיר ונהדר שמך בכל רחבי הארץ!",
  "9_1": "למנצח, על נעימת 'מות לבן', מזמור תודה שחיבר דוד.",
  "9_2": "אודה לה' בכל לבי, ואספר בהתרגשות על כל מעשי הניסים והנפלאות שעשית.",
  "9_3": "אשמח ואצהל בך ובחסדך, ואנגן שיר הלל לשמך, ה' העליון.",
  "9_4": "כאשר אויביי נסוגו לאחור בבהלה, הם נכשלו ואבדו מפני נוכחותך וכוחך.",
  "9_5": "כי אתה עשית למעני צדק והכרעת בריבי; ישבת על כס המשפט כשופט צדק אמיתי.",
  "9_6": "נזפת בעמים העוינים והשמדת את הרשעים, ומחית את שמם וזכרם לעולם ולנצח.",
  "9_7": "האויב המאיים הגיע אל קיצו וחרבותיו נהרסו לעד, עריו נעקרו ונהרסו עד שאפילו זכרן נמחק כליל.",
  "9_8": "ואילו ה' יושב ומולך לעולם; הוא כונן ובנה את כסאו לצדק ולמשפט.",
  "9_9": "והוא ישפוט את כל תושבי העולם בצדק, וינהיג עמים ומשפטים ביושר ובהגינות.",
  "9_10": "וה' יהיה מבצר ומקלט לעשוק ולמדוכא, מקלט מגן בזמני צרה ומצוקה.",
  "9_11": "וכל מי שמכירים את שמך וחסדך יבטחו בך, כי מעולם לא עזבת את אלה שדורשים אותך ומחפשים את קרבתך, ה'.",
  "9_12": "זמרו ושבחו לה' השוכן בציון, ספרו בין כל העמים את מעשיו הגדולים.",
  "9_13": "כי האל שדורש דין על דם נקי שנשפך זוכר את הנרדפים, ולא שוכח את זעקתם של העניים והסובלים.",
  "9_14": "חמול עליי, ה'! ראה את הסבל והעינוי שאויביי ושונאיי גורמים לי, אתה שמעלה ומחלץ אותי משערי המוות,",
  "9_15": "כדי שאוכל לספר את כל תהילותיך ושבחך בשערי ירושלים, ואשמח בשמחה עצומה בישועה שהבאת לי.",
  "9_16": "העמים שקעו לתוך הבור שהם עצמם חפרו להפיל אחרים, ורגלם נתפסה ברשת שהם טמנו בסתר.",
  "9_17": "נודע והתגלה ה' במשפט הצדק שעשה: הרשע נלכד במעשי ידיו ובמלכודות של עצמו; דבר זה ראוי להתבוננות עמוקה לתמיד.",
  "9_18": "הרשעים ישובו ויירדו אל הקבר והשאול, וכן כל העמים ששכחו את אלוהים ואת חוקי המוסר.",
  "9_19": "כי האביון והחסר לא יישכח לנצח, ותקוותם של הענווים והחלשים לא תאבד לעולם.",
  "9_20": "קום, ה', ואל תיתן לאדם בשר ודם להתגאות ולהתעצם; יישפטו העמים כולם לפניך.",
  "9_21": "הטל בהם פחד ומורא, ה', כדי שיבינו ויידעו העמים שהם אינם אלא בני אנוש חלופיים ובני תמותה.",
  "10_1": "מדוע, ה', אתה נראה כעומד מרחוק, ומעלים את מבטך בזמנים שבהם שוררת צרה ומצוקה?",
  "10_2": "בגאוותו וביהירותו של הרשע הוא רודף ומציק לעני חסר האונים; הלוואי שהרשעים יילכדו במזימות שהם עצמם תכננו!",
  "10_3": "כי הרשע מתפאר ומחמיא לעצמו על תאוות נפשו הפסולה, ומי שגוזל ובוצע מברך את עצמו ומזלזל בה'.",
  "10_4": "הרשע ביהירותו ובגאוותו אומר לעצמו: ה' לא ידרוש ולא יחקור; כל מחשבותיו הן כאילו אין אלוהים שרואה ושופט.",
  "10_5": "דרכיו נראות כמצליחות בכל עת, משפטיך ועונשיך נראים לו רחוקים וגבוהים מדי מכדי שיחולו עליו, ועל כל יריביו הוא מזלזל ונושף בביטול.",
  "10_6": "הוא אמר בלבו: לעולם לא אפול, מדור לדור לא יקרה לי שום רע.",
  "10_7": "פיו מלא בקללות, בשקרים, במרמה ובפגיעה; תחת לשונו חבויים תמיד עמל, עיוות ועוול.",
  "10_8": "הוא יושב במארב במקומות נסתרים מחוץ לחצרות, בחשאי הוא הורג אדם חף מפשע, ועיניו עוקבות ומחפשות בסתר את האדם המסכן והחסר ישע.",
  "10_9": "הוא אורב במחבוא כמו אריה בסוכתו וביער, אורב כדי לחטוף עני חלש; הוא לוכד את העני וגורר אותו לתוך רשתו.",
  "10_10": "הוא מתכופף, משתופף ומסתתר, עד שהמסכנים נופלים ונלכדים בציפורניו החזקות.",
  "10_11": "הוא אמר בלבו: אלוהים שכח, הוא הסתיר את פניו ולעולם לא יראה את מעשיי.",
  "10_12": "קום, ה'! אלוהים, הרם את ידך לפעול, ואל תשכח את העניים והסובלים.",
  "10_13": "על מה ולמה מעז הרשע לזלזל באלוהים ולחשוב בלבו: אתה לא תחקור ולא תעניש?",
  "10_14": "הרי אתה כן ראית! כי אתה מביט בכל עמל, סבל ועוול כדי להשיב גמול בידך; עליך סומך ומשליך את יהבו המסכן, שכן אתה היית תמיד העוזר והתומך של היתום.",
  "10_15": "שבור את כוחו וזרועו של הרשע; חקור ודרוש את רשעותו של עושה הרע עד שלא יישאר ממנה שריד.",
  "10_16": "ה' הוא מלך שליט לעולם ועד, והעמים הרשעים שפעלו נגדו אבדו מן הארץ.",
  "10_17": "שמעת, ה', את משאלת לבם של הענווים; אתה תחזק ותנחם את לבבם ותטה את אוזנך להקשיב להם,",
  "10_18": "כדי לעשות משפט צדק ליתום ולמדוכא, כך שאדם בשר ודם מן הארץ לא יוסיף עוד להטיל אימה ולרדוף אותם.",
  "11_1": "למנצח, שיר לדוד: בה' שמתי את כל מבטחי; איך אתם אומרים לנפשי: ברח כמו ציפור אל ההרים שלך כדי להינצל?",
  "11_2": "בטענה כי הנה הרשעים כבר דורכים את קשתם ושמים את החץ על המיתר, כדי לירות בחסות החשכה בישרים ובהגונים.",
  "11_3": "ואומרים: אם יסודות המשפט והחברה נהרסים ונשברים – מה יכול הצדיק לפעול ולעשות?",
  "11_4": "אך ה' נמצא בהיכל קודשו, כסאו של ה' עומד איתן בשמיים; עיניו רואות הכל ועפעפיו בוחנים היטב את כל מעשי בני האדם.",
  "11_5": "ה' בוחן ומנסה את הצדיק לטובתו, אך את הרשע ואת מי שאוהב אלימות וחמס – נפשו שונאת ומתעבת.",
  "11_6": "הוא ימטיר על הרשעים מלכודות, אש, גופרית ורוח לוהטת וסוערת – זה יהיה חלקם והגמול המגיע להם.",
  "11_7": "כי ה' הוא צדיק ואוהב מעשי צדק, והאנשים הישרים יזכו לחזות בפניו וליהנות מאורו.",
  "12_1": "למנצח על כלי בעל שמונה מיתרים, מזמור לדוד.",
  "12_2": "הושיעה, ה', כי תמו ואבדו האנשים החסידים והטובים, ואנשי האמת והאמונה נעלמו מבין בני האדם!",
  "12_3": "שקר ודברי הבל מדבר כל איש עם חברו; הם מדברים בשפתיים חלקלקות ומחניפות, ובלב חצוי ולא כן הם מדברים (בפיהם אחד ובלבם אחר).",
  "12_4": "הלוואי שה' יכרית וישתיק את כל השפתיים המחניפות, ואת הלשון המתנשאת שמדברת דברי רהב וגאווה.",
  "12_5": "אותם אנשים שאמרו: בזכות לשוננו הערמומית נגבר וננצח, הרי שפתינו שייכות לנו – מי יכול להיות אדון ושליט עלינו?",
  "12_6": "בגלל גזל העניים ובשל אנחתם ומצוקתם של האביונים – כעת אקום לפעול, אומר ה'; אביא להם ישועה והצלה מפני מי שלועג להם ונושף עליהם בבוז.",
  "12_7": "דברי ה' והבטחותיו הם דברים טהורים ואמיתיים לחלוטין, כמו כסף מזוקק וצרוף בכור על הארץ, שטוהר ונצרף שבע פעמים.",
  "12_8": "אתה, ה', תשמור עליהם; תנצור ותגן על כל אדם חסיד מפני הדור המושחת הזה לעולם.",
  "12_9": "מסביב הרשעים מתהלכים בחופשיות ובביטחון, כאשר השפלות והרוע מתרוממים וזוכים לכבוד בקרב בני האדם.",
  "13_1": "למנצח, מזמור תפילה שחיבר דוד.",
  "13_2": "עד מתי, ה', תשכח אותי ותתרחק – האם לתמיד? עד מתי תסתיר את פניך והשגחתך ממני?",
  "13_3": "עד מתי אהיה שרוי בלבטים, בספקות ובדאגות בנפשי, ועצב וצער ימלאו את לבי יום יום? עד מתי אויבי יתנשא ויגבר עליי?",
  "13_4": "הבט אליי וענה לי, ה' אלוהיי! האר את עיניי והשב לי את כוחי, כדי שלא אישן את שנת המוות והייאוש.",
  "13_5": "פן יאמר אויבי: גברתי עליו וניצחתי אותו, וצרי ישמחו ויחגגו כאשר אמעד ואפול.",
  "13_6": "ואני – בחסדך הגדול שמתי את מבטחי; לבי ישמח ויצהל בישועתך, ואשיר שיר הודיה לה' על שגמל עליי בטוב וחסד.",
  "14_1": "למנצח, שיר לדוד: אמר האדם הנבל וחסר התבונה בלבו: אין אלוהים; הם השחיתו את דרכם, עשו מעשים מתועבים ופשעים, ואין ביניהם אף אחד שעושה טוב.",
  "14_2": "ה' השקיף מן השמיים על בני האדם, לראות האם יש ביניהם אדם משכיל וחכם שדורש את אלוהים ומבקש את דרכו.",
  "14_3": "כולם סטו מדרך הישר, כולם כאחד נשחתו והתקלקלו; אין עושה טוב, אין אפילו אחד.",
  "14_4": "האם לא יבינו וידעו כל עושי העוול, שבולעים וגוזלים את עמי כאילו אכלו לחם, ואל ה' אינם קוראים ואינם מתפללים?",
  "14_5": "שם ייתקפו פחד וחרדה גדולה, כי אלוהים שוכן ומגן על דור הצדיקים.",
  "14_6": "את עצתו ותקוותו של העני והעשוק אתם מנסים לבייש ולסכל, אבל ה' הוא מבצרו ומחסהו הבטוח.",
  "14_7": "מי ייתן ותצא מציון הישועה הגדולה של עם ישראל! כאשר ישיב ה' את שבות עמו ויגאל אותם מגלותם ומצוקתם – ישמח יעקב ויצהל כל ישראל!",
  "15_1": "מזמור שחיבר דוד: ה', מי ראוי להתארח ולהתגורר באוהלך? מי יזכה לשכון בהר קודשך?",
  "15_2": "מי שמתהלך בתמימות וביושר, פועל בצדק ומעשים טובים, ודובר אמת בכנות ובלב שלם.",
  "15_3": "מי שלא הוציא לשון הרע ורכילות בפיו, לא עשה רע לחברו, ולא הטיח חרפה ועלבון בקרובו ובשכנו.",
  "15_4": "אדם נבזה ושפל נמאס בעיניו והוא אינו מחמיא לו, ואילו את יראי ה' ואנשי האמת הוא מכבד ומעריך; גם אם נשבע שבועה שעלולה להסב לו הפסד ונזק – הוא עומד בדיבורו ואינו מפר אותה.",
  "15_5": "את כספו לא נתן בהלוואה בריבית קצוצה ועושקת, ושחד כנגד אדם נקי וחף מפשע לא לקח; מי שנוהג ועושה את כל אלה – לא ימעד ולא יתמוטט לעולם!",
  "16_1": "שיר יקר ומכתם לדוד: שמור והגן עליי, אלוהים, כי בך שמתי את כל מבטחי ומחסיי.",
  "16_2": "אמרת לנפשך אל ה': אתה אדוני ומנהיגי; כל הטוב שיש לי אינו מגיע לי בזכות עצמי אלא רק מחסדך.",
  "16_3": "למען הצדיקים והקדושים שחיים בארץ, האנשים הנכבדים והאדירים שכל חפצי ושמחתי להיות בחברתם.",
  "16_4": "ייסוריהם ומכאוביהם של הרודפים אחר אלילים זרים יתרבו; לא אשתתף בניסוכי הדם שלהם, ולא אשא את שמות אליליהם על שפתיי.",
  "16_5": "ה' הוא חלקי ונחלתי, וכוס הברכה שלי; אתה תומך ומבטיח את גורלי הטוב.",
  "16_6": "חבלי הנחלה שלי נפלו במקומות יפים ונעימים, ואכן זכיתי בנחלה מפוארת ומשמחת.",
  "16_7": "אברך ואשבח את ה' שיעץ והדריך אותי לטוב; אפילו בלילות מצפוני ומחשבותיי הפנימיות מלמדים ומעוררים אותי.",
  "16_8": "שמתי את ה' לנגד עיניי תמיד ללא הפסק; כיוון שהוא לימיני ומגן עליי – לעולם לא אמעד ולא אפול.",
  "16_9": "לכן לבי שמח, כבודי ונשמתי רוננים, וגם גופי ובשרי ישכנו בביטחון ובשלווה.",
  "16_10": "כי לא תפקיר ותעזוב את נפשי בשאול ובקבר, ולא תניח לאיש חסיד ונאמן שלך לראות אבדון ושחת.",
  "16_11": "תודיעני ותלמדני את נתיב החיים; במחיצתך יש שובע של שמחות, ונעימות נצחית מצויה לימינך.",
  "17_1": "תפילה שחיבר דוד: שמע, ה', את תחינתי הצודקת, הקשב לזעקתי והאזן לתפילתי הנובעת משפתיים שאין בהן מרמה.",
  "17_2": "מלפניך ייצא פסק הדין והמשפט שלי; עיניך יביטו ויראו את היושר והצדק.",
  "17_3": "בחנת ובדקת את לבי, פקדת אותי בלילה וצרפת אותי – ולא מצאת בי שום כוונה רעה; החלטתי שפי לא יעבור על האמת.",
  "17_4": "לגבי מעשי בני האדם, נשמרתי בדברי פיך מלהיגרר לנתיביהם של אנשים אלימים ופורצי חוק.",
  "17_5": "צעדיי נתמכו בנתיבותיך ובמצוותיך, וכך רגליי לא מעדו מדרך הישר.",
  "17_6": "אני קראתי אליך כי ידעתי שתענה לי, אלוהים; הטה את אוזנך אליי ושמע את דבריי.",
  "17_7": "הפלא והראה את חסדיך הנפלאים, אתה שמושיע בימינך החזקה את החוסים בך מפני הקמים עליהם.",
  "17_8": "שמור עליי בזהירות כאישון העין היקר והעדין, והסתר אותי להגנה בצל כנפיך הרחומות,",
  "17_9": "מפני הרשעים שרוצים להשמיד אותי, ומפני אויביי בנפש שמקיפים אותי מכל עבר.",
  "17_10": "הם סגרו ועיבו את לבם בשומן ובאטימות, ובפיהם הם מדברים ביהירות ובשחצנות רבה.",
  "17_11": "בכל צעדיי הם כבר הקיפו אותנו, ועיניהם תלויות להפיל אותנו לארץ.",
  "17_12": "האויב דומה לאריה המשתוקק לטרוף, וככפיר אריות שאורב במקומות מסתור.",
  "17_13": "קום, ה', הקדם ועמוד מולו והכרע אותו; הצל את נפשי מן הרשע בעזרת חרבך.",
  "17_14": "הצל אותי, ה', בעזרת ידך מאנשים שכל עולמם הוא החיים החומריים בעולם הזה, שכרסם מלאה בטובות חומריות, בניהם שבעים והם מותירים את ממונם לצאצאיהם.",
  "17_15": "ואילו אני – בצדק וביושר אחזה בפניך ובנוכחותך, ואשבע בהקיצי משנת המוות (או בבוא הגאולה) מזיו תבניתך וכבודך.",
  "18_1": "למנצח, לעבד ה' דוד, אשר שר לה' את מילות השירה הזאת ביום שבו הציל אותו ה' מכף כל אויביו ומיד שאול המלך.",
  "18_2": "ואמר: אני אוהב אותך בכל נפשי, ה', אתה מקור כוחי וחוזקי.",
  "18_3": "ה' הוא מבצרי, מצודתי והמציל שלי; אלוהיי הוא הצור החזק שלי שבו אמצא מחסה, הוא מגיני, קרן ישועתי ומעוזי הגבוה.",
  "18_4": "בשבחים ובתהילות אקרא אל ה', ומכל אויביי אינצל ואיוושע.",
  "18_5": "חבלי מוות אפפו והקיפו אותי, ושטף של אנשי רשע וסכנות הפחיד אותי עד מאוד.",
  "18_6": "קשרי השאול והקבר כרכו אותי מסביב, ומלכודות המוות הקדימו אותי.",
  "18_7": "במצוקתי ובצערי קראתי לה' ואל אלוהיי זעקתי; הוא שמע מהיכלו את קולי, וזעקתי הגיעה לפניו אל אוזניו.",
  "18_8": "אז רעדה וגעשה הארץ, ויסודות ההרים רעדו והתנועעו כי חרה כעסו של ה' על הרשעים.",
  "18_9": "עלה עשן מרוגזו ואש אוכלת יצאה מפיו; גחלים בוערות ניצתו והתלקחו מפניו.",
  "18_10": "הוא הטה את השמיים וירד להתגלות, וערפל כבד ושחור היה תחת רגליו.",
  "18_11": "הוא רכב על כרוב מלאכי והתעופף במהירות, וריחף על גבי כנפי הרוח הסוערת.",
  "18_12": "הוא עשה את החושך למחבואו ואת ענני המים הסמיכים לסוכתו המקיפה אותו.",
  "18_13": "מתוך הזוהר והנוגה שלפניו עברו ענניו, וירדו ברד וגחלי אש לוהטות.",
  "18_14": "ה' הרעים בקולו מן השמיים והעליון השמיע את קולו בברד ובגחלי אש.",
  "18_15": "הוא שלח את חיציו ופיזר את אויביי, ושלח ברקים רבים ובלבל והבהיל אותם.",
  "18_16": "אז נראו קרקעיות האפיקים של המים ונגלו יסודות תבל מגערתך, ה', ומנשיבת רוח אפך וכעסך.",
  "18_17": "הוא שלח את עזרתו ממרומים ולקח אותי, משה ומשך אותי מתוך מים רבים ומסוכנים.",
  "18_18": "הוא הציל אותי מאויבי החזק והתקיף, ומשונאיי שהיו חזקים ממני בהרבה.",
  "18_19": "הם הקדימו לתקוף אותי ביום אסוני ומפלתי, אך ה' היה לי למשענת ולתמיכה איתנה.",
  "18_20": "והוא הוציא אותי מן המצר אל המרחב הפתוח; הוא חילץ אותי כי רצה בי ואהב אותי.",
  "18_21": "ה' גמל לי כפי צדקתי ויושרי; הוא השיב לי שכר כפי ניקיון ידיי מכל חטא וגזל.",
  "18_22": "כי שמרתי והקפדתי על דרכי ה', ולא סרתי ברשע מאת אלוהיי.",
  "18_23": "כי כל משפטיו ומצוותיו עמדו לנגד עיניי תמיד, ומחוקותיו מעולם לא סרתי.",
  "18_24": "הייתי שלם ותמים עמו, ונשמרתי ונזהרתי מכל חטא ועוון.",
  "18_25": "לכן ה' השיב וגמל לי כפי צדקתי, כפי טוהר ידי לנגד עיניו.",
  "18_26": "עם אדם חסיד אתה נוהג בחסידות, ועם איש תמים וישר אתה מתנהל בתמימות.",
  "18_27": "עם אדם טהור ובר-לבב אתה נוהג בטהרה, ואילו עם אדם עקשן ונכלולי אתה מתנהג בערמומיות ובמידה כנגד מידה.",
  "18_28": "כי אתה מושיע ומחלץ עם עני ומושפל, אך עיניים גאוותניות ומתנשאות אתה משפיל ומוריד.",
  "18_29": "כי אתה מאיר את נרי ואת נשמתי; ה' אלוהיי מגרש ומאיר את החושך והצרה שלי.",
  "18_30": "כי בעזרתך אני יכול לפרוץ ולהביס גדוד אויבים שלם, ובעזרת אלוהיי אני מדלג ומטפס מעל חומת מבצר.",
  "18_31": "האל – דרכו מושלמת ותמימה לחלוטין; דברו והבטחתו של ה' צרופים ומזוקקים כאמת טהורה; הוא מגן לכל המוצאים בו מחסה.",
  "18_32": "כי מי הוא אלוהים אמיתי מלבדי ה'? ומי הוא צור ומעוז בלתי אם אלוהינו?",
  "18_33": "האל הוא זה שחוגר אותי בכוח ובגבורה, ועושה את דרכי ישרה ובטוחה.",
  "18_34": "הוא עושה את רגליי קלות ומהירות כאיילות, ומעמיד אותי בבטחה על המקומות הגבוהים.",
  "18_35": "הוא מאמן ומלמד את ידיי להילחם, כך שזרועותיי יכולות לדרוך אפילו קשת נחושת חזקה.",
  "18_36": "ונתת לי את ישועתך כמגן לשמירתי, ימינך תמכה בי, וענוותנותך וטוב לבך גידלו ורוממו אותי.",
  "18_37": "הרחבת את פסיעותיי תחתי כדי שלא אדחק, וקרסוליי ורגליי לא מעדו.",
  "18_38": "רדפתי אחרי אויביי והשגתי אותם, ולא שבתי ממסעי עד שהשמדתי אותם כליל.",
  "18_39": "מחצתי והכיתי אותם כך שלא יכלו לקום עוד, והם נפלו מובסים תחת רגליי.",
  "18_40": "חגרת אותי בגבורה למלחמה, והכרעת והורדת את הקמים עליי תחתי.",
  "18_41": "גרמת לאויביי לברוח ולהפנות לי את עורפם, ואת שונאיי הכרתי והשמדתי.",
  "18_42": "הם זעקו לעזרה אך איש לא הושיע אותם; הם אפילו זעקו אל ה' אך הוא לא ענה להם.",
  "18_43": "ריסקתי ושחקתי אותם כעפר שמתפזר ברוח, והשלכתי אותם בבוז כטיט ברחובות.",
  "18_44": "הצלת אותי ממריבות ומרידות העם, שמת אותי לראש ולשליט על עמים רבים; אפילו עמים שלא הכרתי בעבר באים לשרת אותי.",
  "18_45": "מיד כאשר אוזנם שומעת על שמעי הם נכנעים ונשמעים לי; עמי ניכר מתכחשים ומחניפים לי מרוב פחד.",
  "18_46": "בני עמים זרים נובלים ורועדים מאימה, ויוצאים בחרדה מתוך מבצריהם הסגורים.",
  "18_47": "חי ה' ומבורך צורי ומעוזי! יתרומם ויתהלל אלוהי ישועתי!",
  "18_48": "האל שמעניק לי נקמה צודקת באויביי, ומכניע עמים עוינים תחת מרותי;",
  "18_49": "הוא שמציל אותי מכל אויביי, מרומם אותי מעל הקמים נגדי, ומידי איש אכזר ואלים הוא מחלץ אותי.",
  "18_50": "לכן אודה לך ואשבח אותך בין כל העמים, ה', ולשמך הגדול אנגן שיר תהילה.",
  "18_51": "הוא המעניק ישועות גדולות למלכו, ועושה חסד ואהבה נצחית למשיחו – לדוד ולצאצאיו עד עולם.",
  "19_1": "למנצח, מזמור תהילה שחיבר דוד.",
  "19_2": "גרמי השמיים מספרים ומעידים על כבודו וגדולתו של האל, ומרחבי הרקיע מודיעים על מעשי ידיו הנפלאים.",
  "19_3": "יום אחד מעביר ליום הבא דברי שבח, ולילה ללילה מוסר חוכמה והתבוננות בבריאה.",
  "19_4": "אין זו שיחה רגילה ואין אלו מילים נשמעות באוזן – קולם אינו נשמע בקול ממשי,",
  "19_5": "ובכל זאת בשורתם והשפעתם יצאו אל כל רחבי הארץ, ומסריהם הגיעו עד קצה תבל; והוא קבע בשמיים משכן ומסלול לשמש.",
  "19_6": "והשמש זורחת ושמחה כמו חתן שיוצא בהדר מחופתו, ושמחה כגיבור נמרץ לרוץ במסלולה ברקיע.",
  "19_7": "מוצאה הוא מקצה אחד של השמיים, ומסלולה מקיף עד קצותיהם האחרים, ואין שום דבר בבריאה הנסתר מחום קרניה.",
  "19_8": "תורת ה' תמימה ומושלמת, משיבה את הנפש ומעניקה לה חיים; עדות ומצוות ה' נאמנות וברורות, ומחכימות אפילו אדם פשוט וחסר ניסיון.",
  "19_9": "הוראותיו וציווייו של ה' ישרים ונכונים, ומשמחים את לב האדם; מצוות ה' טהורה וזכה, ומאירה את עיני השכל והמוסר.",
  "19_10": "יראת ה' היא יראה טהורה ורוחנית המתקיימת לנצח; משפטי ה' והכרעותיו הם אמת מוחלטת וצודקים יחדיו.",
  "19_11": "הם נחשקים ויקרים יותר מזהב מובחר ומפז רב, ומתוקים יותר מדבש טהור הנוטף מחלות דבש.",
  "19_12": "גם עבדך נזהר ומדקדק בהם, כי בשמירתם ובקיומם יש שכר גדול וטוב רב.",
  "19_13": "שגיאות שנעשות בלי משים – מי יכול לדעת ולהבחין בכולן? נקה וסלח לי גם על חטאים שנעשו בהיסח הדעת.",
  "19_14": "גם מפני חטאים מתוך זדון וגאווה מנע את עבדך, ואל תיתן להם לשלוט בי; אז אהיה שלם ותמים, ואהיה נקי ונקי מפשע חמור.",
  "19_15": "יהיו לרצון ולנחת רוח לפניך דברי פי והרהורי לבי, ה' צורי החזק וגואלי הנאמן.",
  "20_1": "למנצח, מזמור תפילה לדוד.",
  "20_2": "יענה לך ה' בעת צרה ומצוקה; שמו וכוחו של אלוהי יעקב ישמרו עליך במקום מבצר גבוה ובטוח.",
  "20_3": "ישלח לך את עזרתו מבית המקדש וממקום הקודש, ומהר ציון יתמוך בך ויחזק אותך.",
  "20_4": "יזכור לטובה את כל מנחותיך וקרבנותיך, ואת עולותיך יקבל ברצון ובאהבה.",
  "20_5": "ייתן לך את משאלות לבך הראויות, ואת כל עצותיך ותוכניותיך הטובות יגשים וימלא.",
  "20_6": "נשיר ונריע בשמחה בישועתך והצלתך, ובשם אלוהינו נרים נס ודגל גאווה; ימלא ה' את כל בקשותיך.",
  "20_7": "עתה ידעתי והשתכנעתי בבירור כי ה' הושיע את המלך המשיח שלו; הוא יענה לו משמי קודשו בגבורה ובישועת ימינו.",
  "20_8": "אלה בוטחים ברכב מלחמה ואלה בוטחים בסוסים חזקים, ואילו אנחנו בוטחים בשמו של ה' אלוהינו ומזכירים אותו בתפילה.",
  "20_9": "הם כרעו ונפלו מובסים, ואילו אנחנו קמנו על רגלינו והתחזקנו בעוצמה.",
  "20_10": "ה', הושיעה והצל אותנו! המלך אלוהים יענה לנו ביום שבו נקרא ונתפלל אליו.",
  "21_1": "למנצח, מזמור תודה שחיבר דוד.",
  "21_2": "ה', בעוצמתך וכוחך ישמח המלך, ובישועתך הגדולה כמה יצהל וישמח!",
  "21_3": "את משאלת לבו העמוקה נתת לו, ואת מה שביקש בשפתיו לא מנעת ממנו לעולם.",
  "21_4": "כי הקדמת להעניק לו ברכות של טוב ושפע, והנחת על ראשו כתר מזהב טהור ונוצץ.",
  "21_5": "חיים ביקש ממך – ונתת לו אריכות ימים ושנות חיים לדור ודור עד עולם.",
  "21_6": "גדול כבודו ומעמדו בזכות ישועתך; הוד ותפארת שמת עליו.",
  "21_7": "כי שמת אותו למקור של ברכות נצחיות, ושימחת אותו בשמחה עמוקה ומתמדת לפני פניך.",
  "21_8": "כי המלך בוטח בה', ובזכות חסדו של האל העליון – לא ימעד ולא ייפול לעולם.",
  "21_9": "ידך תגיע אל כל אויביך, וימינך החזקה תמצא את כל שונאיך.",
  "21_10": "תעשה אותם ככור אש לוהט בעת התגלות כעסך; ה' יכלה אותם בזעמו, ואש תאכל אותם.",
  "21_11": "את פריים וצאצאיהם תשמיד מן הארץ, ואת זרעם מקרב בני האדם.",
  "21_12": "כי הם תכננו לעשות רע נגדך, והגו מזימות הרס – אך לא יוכלו להוציא אותן לפועל.",
  "21_13": "כי תגרום להם לסגת ולהפנות גב, ובמיתרי קשתך תכוון את החיצים כנגד פניהם.",
  "21_14": "התרומם והתנשא, ה', בעוזך ובכוחך! אנחנו נשיר וננגן לכבוד גבורתך האדירה.",
  "22_1": "למנצח, על נעימת שיר הבוקר (איילת השחר), מזמור שחיבר דוד בעת מצוקה גדולה.",
  "22_2": "אלוהיי, אלוהיי, מדוע עזבתני? מדוע אתה רחוק מישועתי ומקול זעקתי ומצוקתי?",
  "22_3": "אלוהיי, אני קורא אליך ביום ואינך עונה, וגם בלילה אינני מחריש ואינני מוצא מנוח.",
  "22_4": "אבל אתה קדוש, יושב ומולך לקול תהילותיו ושבחיו של עם ישראל.",
  "22_5": "בך בטחו אבותינו הקדמונים; הם בטחו בך, ואתה הצלת וחילצת אותם.",
  "22_6": "אליך הם זעקו ונושעו; בך הם שמו את מבטחם ולא התאכזבו ולא התביישו.",
  "22_7": "ואילו אני נרמס כמו תולעת חסרת אונים ולא כאדם חשוב, חרפה ובושה לבני אדם ובזוי בעיני העם.",
  "22_8": "כל הרואים אותי לועגים לי, מעקמים את שפתיהם בבוז ומניעים את ראשם בלעג ואומרים:",
  "22_9": "הרי הוא השליך את יהבו על ה' שיציל אותו – שיציל אותו עכשיו אם אכן חפץ בו!",
  "22_10": "הרי אתה הוא שהוצאת אותי מן הבטן, ונתת לי ביטחון ושלווה עוד על שדי אמי.",
  "22_11": "עליך הושלכתי ונמסרתי עוד מרגע לידתי; מבטן אמי אתה הוא אלוהיי ומגיני.",
  "22_12": "אל תתרחק ממני, כי הצרה קרובה ומאיימת ואין לי שום עוזר מלבדיך.",
  "22_13": "הקיפו אותי אויבים חזקים ותוקפניים כמו פרים רבים; שוורים חזקים מבשן סגרו עליי מכל עבר.",
  "22_14": "פערו עליי את פיהם לטרוף אותי כמו אריה טורף ושואג ברעב.",
  "22_15": "נשפכתי ונחלשתי כמו מים וכל עצמותיי התפרקו ונשמטו; לבי הפך לחלש ורך כמו דונג שנמס בתוך קרביי.",
  "22_16": "כוחי התייבש כמו חרס יבש, ולשוני נדבקה לחכי מרוב צמא וחולשה, ולעפר המוות הורדת אותי.",
  "22_17": "כי הקיפו אותי אנשים רעים הדומים לכלבים טורפים; חבורת מרעים הקיפה אותי, והם כבלו או פצעו את ידיי ואת רגליי.",
  "22_18": "יכול אני לספור את כל עצמותיי מרוב רזון וחולשה; הם מביטים בי וצופים במפלתי בהנאה מרושעת.",
  "22_19": "הם מחלקים ביניהם את בגדיי, ועל לבושי הם מטילים גורל כאילו כבר מתתי.",
  "22_20": "אבל אתה, ה', אל תתרחק ממני! מקור כוחי וחוזקי, מהר לעזרתי!",
  "22_21": "הצל מחרב האויב את נפשי, ומיד אנשים אכזריים ככלבים את חיי היחידים והיקרים.",
  "22_22": "הושע אותי מפי האריה, וכפי שהצלת אותי בעבר מקרני ראמים אימתניות – ענה לי גם עתה.",
  "22_23": "אספר ואפרסם את שמך וחסדך לאחיי; בתוך קהל עם רב אהלל ואשבח אותך.",
  "22_24": "יראי ה', הללו ושבחו אותו! כל צאצאי יעקב, כבדו אותו, ורעדו מיראת כבודו כל זרע ישראל!",
  "22_25": "כי הוא לא זלזל ולא מאס בסבלו של העני, לא הסתיר את פניו ממנו, וכאשר זעק אליו במצוקתו – שמע והאזין לו.",
  "22_26": "ממך נובעת תהילתי ושבחי בקהל גדול; את נדריי והבטחותיי אשלם לפני היראים אותך.",
  "22_27": "הענווים והצנועים יאכלו וישבעו מטובו, דורשי ה' יהללו אותו, ולבבכם יחיה ויתמלא שמחה לעולם ועד!",
  "22_28": "ייזכרו וישובו אל ה' כל יושבי קצוות הארץ, וישתחוו לפניך כל משפחות העמים.",
  "22_29": "כי המלוכה והשלטון האמיתי שייכים רק לה', והוא השליט והמנהיג על כל העמים.",
  "22_30": "כל עשירי הארץ אכלו וישתחוו לפניו; לפניו יכרעו כל בני האדם היורדים אל עפר המוות, שאינם יכולים לחיות את נפשם בכוחות עצמם.",
  "22_31": "הדורות הבאים יעבדו אותו, ויסופר להם על גבורתו וצדקתו של ה' מדור לדור.",
  "22_32": "יבואו ויגידו את צדקתו לעם שייוולד בעתיד – כי אכן עשה ה' נפלאות וגאל את עמו.",
  "23_1": "מזמור של ביטחון שחיבר דוד: ה' הוא הרועה המדריך אותי, ולכן שום דבר לא יחסר לי.",
  "23_2": "בשדות מרעה של דשא ירוק ורענן הוא מניח אותי לנוח, ועל פני מים שלווים ורגועים הוא מנהיג ומוביל אותי.",
  "23_3": "הוא משיב ומרענן את נפשי; הוא מדריך אותי בנתיבים של צדק ויושר למען כבוד שמו.",
  "23_4": "גם כאשר אלך בעמק חשוך ומסוכן של צלמוות ומוות – לא אפחד משום רע, כי אתה נמצא תמיד עמדי; מקל ההגנה שלך ומשענת התמיכה שלך – הם המנחמים ומעודדים אותי.",
  "23_5": "אתה עורך ומכין לפניי שולחן מלא כל טוב לנגד עיניהם של אויביי ומבקשי רעתי; משחת בשמן ערב את ראשי לכבוד, וכוסי מלאה ורוויה בשפע ובברכה.",
  "23_6": "אך ורק טוב וחסד ירדפו אחריי וילוו אותי בכל ימי חיי, ואזכה לשבת ולהתפלל בבית ה' לאורך ימים ושנים רבות.",
  "24_1": "מזמור שחיבר דוד: לה' שייכים הארץ וכל אשר בה, העולם וכל היושבים והחיים בו.",
  "24_2": "כי הוא זה שייסד וקבע אותה מעל פני הימים, וביסס אותה מעל פני הנהרות.",
  "24_3": "מי ראוי וזכאי לעלות אל הר ה' הקדוש? ומי יוכל לעמוד במקום מקדשו וקדושתו?",
  "24_4": "רק מי שידיו נקיות מחטא ומגזל ולבבו טהור ונקי מכוונות רעות, אשר לא נשבע בשמו של ה' לשווא, ולא נשבע לשקר כדי לרמות את זולתו.",
  "24_5": "אדם כזה יקבל ברכה ושפע מאת ה', וצדקה וגמול טוב מאלוהי ישועתו.",
  "24_6": "זהו הדור של דורשיו של ה', המבקשים את פניך וקרבתך, בני יעקב, לנצח.",
  "24_7": "הרימו, שערי המקדש, את ראשיכם והינשאו פתחי עולם – כדי שייכנס דרככם מלך הכבוד הנשגב!",
  "24_8": "מי הוא זה מלך הכבוד? ה' העז והגיבור, ה' הגיבור והמנצח במלחמה!",
  "24_9": "הרימו, שערי המקדש, את ראשיכם והינשאו פתחי עולם – ויבוא דרככם מלך הכבוד!",
  "24_10": "מי הוא זה מלך הכבוד? ה' צבאות, אדון כל צבאות השמיים והארץ – הוא מלך הכבוד לעד ולעולמי עולמים!",
  "25_1": "מזמור תפילה שחיבר דוד לפי סדר האותיות: אליך, ה', את כל נפשי ותפילתי אני נושא ומכוון.",
  "25_2": "אלוהיי, בך שמתי את מבטחי; אנא אל תיתן לי להתאכזב ולהתבייש, ואל יצהלו אויביי על מפלתי.",
  "25_3": "אכן, כל המייחלים ומקווים לעזרתך לא יתאכזבו; רק הבוגדים והעושים שקר ללא סיבה הם שיתביישו.",
  "25_4": "הודע ולמד אותי, ה', את דרכיך הנכונות, ואת נתיבות המוסר והצדק שלך למדני.",
  "25_5": "הדרך והנחה אותי באמיתך ולמד אותי, כי אתה הוא אלוהי ישועתי והצלתי; אליך קיוויתי וציפיתי בכל שעות היום.",
  "25_6": "זכור את רחמיך וחסדיך הגדולים, ה', שהרי הם קיימים מעולם ומשחר הבריאה.",
  "25_7": "את חטאי נעוריי ואת משגיי אל תזכור לי לחומרה; זכור אותי על פי מידת חסדך ואהבתך, למען טובך הגדול, ה'.",
  "25_8": "טוב וישר הוא ה', ולכן הוא מורה ומלמד גם לחוטאים כיצד לשוב אל הדרך הנכונה.",
  "25_9": "הוא מנהיג את האנשים הענווים בדרך המשפט והיושר, ומלמד את הצנועים את דרכו.",
  "25_10": "כל דרכיו והנהגותיו של ה' מלאות חסד ואמת עבור מי ששומרים את בריתו ואת מצוותיו הנאמנות.",
  "25_11": "למען כבוד שמך, ה', סלח ונקה את עווני וחטאי, אף על פי שהוא כבד ורב.",
  "25_12": "מי הוא האיש שירא את ה'? ה' ידריך ויורה לו את הדרך הנכונה שבה עליו לבחור.",
  "25_13": "נפשו תשכון בטוב, בשלווה ובנעימות, וצאצאיו יירשו את הארץ ויבורכו בה.",
  "25_14": "סודו והדרכתו הפנימית של ה' גלויים לאלה שיראים אותו, ואת עומק בריתו הוא מגלה ומודיע להם.",
  "25_15": "עיניי נשואות תמיד בתקווה אל ה', כי הוא זה שיחלץ ויוציא את רגליי מכל מלכודת ורשת.",
  "25_16": "פנה אליי וחמול עליי, כי בודד, גלמוד ועני אני במצוקתי.",
  "25_17": "הצרות והדאגות שבתוך לבי התרחבו והתרבו; אנא הוצא אותי מכל מצוקותיי ומכאוביי.",
  "25_18": "ראה את עוניי, סבלי ועמלי הקשה, וסלח ומחל לכל חטאיי.",
  "25_19": "ראה כמה רבים הפכו להיות אויביי, ובאיזו שנאה אלימה ואכזרית הם שונאים אותי.",
  "25_20": "שמור על נפשי והצל אותי; אל תיתן לי להתבייש, כי בך מצאתי מחסה.",
  "25_21": "התמימות והיושר הפנימי שלי ישמרו ויגנו עליי, כי אליך ייחלתי וקיוויתי.",
  "25_22": "פדה והצל, אלוהים, את עם ישראל כולו מכל צרותיו, מצוקותיו וייסוריו!",
  "26_1": "מזמור שחיבר דוד: שפוט אותי, ה', ועמוד לצדי, כי הלכתי בדרכי בתמימות וביושר לב; בה' בטחתי ולכן לא אמיל ולא אמעד.",
  "26_2": "בחן אותי, ה', ונסה את מעשיי; צרוף ובדוק את מחשבותיי ואת נבכי לבי.",
  "26_3": "כי חסדך וטובך עומדים לנגד עיניי תמיד, והתהלכתי בנאמנות באמיתך.",
  "26_4": "לא ישבתי בחברתם של אנשים שקרנים וריקים, ועם אנשים צבועים המסתירים את פרצופם האמיתי לא התחברתי.",
  "26_5": "שנאתי את חברתם של אנשים רעים ומזיקים, ועם רשעים לא ישבתי.",
  "26_6": "ארחץ את כפיי בניקיון מחטא ומעוול, ואקיף בהודיה את מזבחך, ה',",
  "26_7": "כדי להשמיע ברמה קול תודה והלל, ולספר על כל מעשיך הנפלאים.",
  "26_8": "ה', אהבתי בכל לבי את מעון ביתך ואת המקום שבו שוכן כבודך ותפארתך.",
  "26_9": "אל תאסוף ואל תכלה את נפשי יחד עם החוטאים, ואת חיי עם אנשים אלימים ששופכים דמים,",
  "26_10": "שבידיהם יש מזימות של עוול ורשע, וימינם מלאה בשוחד ובשחיתות.",
  "26_11": "ואילו אני – בתמימותי וביושרי אלך; פדה אותי מכל צרה וחמול עליי ברחמיך.",
  "26_12": "רגליי עומדות בבטחה במקום מישור ויציב; בקהל רב אברך ואהלל את ה'.",
  "27_1": "מזמור שחיבר דוד: ה' הוא האור המאיר את דרכי וישועתי – ממי אפחד? ה' הוא המעוז והמבצר של חיי – מפני מי אירא?",
  "27_2": "כאשר התקרבו אליי אנשים רעים כדי לטרוף אותי ולכלות את בשרי – אותם צרים ואויבים הם אלה שנכשלו ונפלו.",
  "27_3": "גם אם יחנה וייערך כנגדי מחנה צבאי שלם – לבי לא יפחד; גם אם תפרוץ עליי מלחמה קשה – באלוהים אני בוטח.",
  "27_4": "דבר אחד בלבד ביקשתי מאת ה', ואותו בלבד אני מחפש ודורש: לשבת בבית ה' כל ימי חיי, לחזות בנועם ובזיו השכינה של ה' ולבקר בהיכלו.",
  "27_5": "כי הוא יסתיר ויגן עליי בסוכתו ביום של צרה ורעה; הוא יחביא אותי בסתר אוהלו, ועל סלע גבוה ומבוצר ירומם אותי.",
  "27_6": "ועתה יתרומם ראשי בניצחון מעל כל אויביי המקיפים אותי, ואקריב במשכנו זבחים בשמחה ובתרועה, אשיר ואנגן שיר הודיה לה'.",
  "27_7": "שמע, ה', את קולי כאשר אני קורא ומתפלל; חמול עליי וענה לתחינתי.",
  "27_8": "בשמך אמר לי לבי: בקשו את קרבתי ואת פניי; ואכן, את פניך וקרבתך, ה', אני מבקש בכל מאודי.",
  "27_9": "אל תסתיר את פניך והשגחתך ממני, אל תדחה בכעס את עבדך; הרי תמיד היית עזרתי – אל תיטוש ואל תעזוב אותי, אלוהי ישועתי!",
  "27_10": "אפילו אם אבי ואמי יעזבו אותי – ה' יאסוף אותי וידאג לי באהבתו.",
  "27_11": "למד והורה לי, ה', את דרכך, והנחה אותי בנתיב ישר ובטוח, כדי שלא אפול בידי אויביי האורבים לי.",
  "27_12": "אל תמסור אותי בידי תאוותם של צריי, כי קמו נגדי עדי שקר שמפיצים דברי כזב ושואפים לאלימות.",
  "27_13": "אלמלא האמנתי שאזכה לראות בטובו ובחסדו של ה' בארץ החיים – כבר הייתי אובד ומתייאש.",
  "27_14": "קווה וייחל לה'! התחזק והיה אמיץ בלבבך, וקווה תמיד לה' בביטחון שלם!",
  "28_1": "מזמור שחיבר דוד: אליך, ה', אני קורא, צורי ומעוזי! אל תתעלם ואל תחריש ממני, פן אם תשתוק ולא תענה לי – אהיה נחשב כמי שכבר יורד אל הקבר.",
  "28_2": "שמע את קול תחנוניי כאשר אני זועק אליך לעזרה, בהרימי את כפיי בתפילה אל עבר קודש הקודשים שבהיכלך.",
  "28_3": "אל תגרור ואל תצרף את גורלי עם הרשעים ועושי העוול, המדברים דברי שלום וחנופה עם רעיהם אך בלבבם חורשים רעה.",
  "28_4": "תן להם גמול כפי מעשיהם הרעים וכפי רוע עלילותיהם; כפי מה שעוללו בידיהם שלם להם, והשב להם את גמולם הראוי.",
  "28_5": "כיוון שאינם מבינים ואינם מתבוננים במעשי ה' ובבריאתו – הוא יהרוס אותם ולא יבנה אותם עוד.",
  "28_6": "ברוך ומשובח ה', כי שמע את קול תפילתי ותחנוניי!",
  "28_7": "ה' הוא כוחי ומגיני, בו בטח לבי ונושעתי וקיבלתי עזרה; לבי שמח ורונן, ומתוך שיריי ותפילותיי אודה לו.",
  "28_8": "ה' הוא מקור הכוח והעוז לעמו, והוא מעוז של ישועות והצלה עבור המלך המשיח שלו.",
  "28_9": "הושע והצל את עמך וברך את נחלתך; רעה והנהג אותם באהבה, ונשא ורומם אותם לעד ולעולמי עולמים!",
  "29_1": "מזמור שחיבר דוד: תנו והודו לה', בני שרים ומלאכים; תנו לה' את הכבוד ואת השבח על כוחו ועוזו!",
  "29_2": "תנו לה' את הכבוד הראוי לשמו הגדול; השתחוו לה' בהדרת קודש וביראת רוממות.",
  "29_3": "קולו וגבורתו של ה' נשמעים מעל המים הסוערים; אל הכבוד הרעים ברעמים אדירים, ה' שולט על מים רבים ועצומים.",
  "29_4": "קול ה' נשמע בעוצמה ובכוח אדיר; קול ה' מתגלה בהדר וביופי מלכותי.",
  "29_5": "קול ה' שובר ומרסק עצי ארזים חזקים; ה' משבר אפילו את ארזי הלבנון האיתנים.",
  "29_6": "הוא מרקיד ומנענע את הרי הלבנון כמו עגל קל רגליים, ואת הר החרמון (שריון) כמו גור ראמים צעיר.",
  "29_7": "קול ה' חוצב ומתיז להבות אש וברקים ברקיע.",
  "29_8": "קול ה' מרעיד ומחולל את המדבר; ה' מרעיד את מדבר קדש השומם.",
  "29_9": "קול ה' מפחיד ומעורר את האיילות להמליט מחיל, וחושף ומפשיט את היערות מעליהם; ובהיכלו – כולם עומדים ואומרים: כבוד!",
  "29_10": "ה' ישב ושפט את העולם כבר בעת המבול הגדול, וה' יושב ומולך כמלך עליון לעולם ועד.",
  "29_11": "ה' ייתן עוז, כוח וגבורה לעמו; ה' יברך את עמו בשלום ובשלווה!",
  "30_1": "מזמור שיר שחיבר דוד לחנוכת הבית (בית המקדש):",
  "30_2": "ארומם ואשבח אותך, ה', כי משית והעלית אותי ממעמקי הצרה, ולא נתת לאויביי לשמוח על מפלתי.",
  "30_3": "ה' אלוהיי, זעקתי אליך במצוקתי ובמחייתי – וריפאת אותי והבראת אותי.",
  "30_4": "ה', העלית והצלת מן הקבר והשאול את נפשי; החזקת אותי בחיים כדי שלא ארד עם שוכני עפר ובור.",
  "30_5": "זמרו ושבחו לה', חסידיו ונאמניו, והודו לשם קודשו ולזכרו הטהור.",
  "30_6": "כי כעסו נמשך רק רגע קצר, ואילו ברצונו ובחסדו יש חיים ארוכים; בערב אדם עשוי לשכב בבכי ובצער, אך בבוקר מגיעה שמחה ורינה!",
  "30_7": "ואני, בימי שלוותי והצלחתי, חשבתי בטעות: לעולם לא אפול ולא אמעד.",
  "30_8": "אך הבנתי כי אתה, ה', ברצונך ובחסדך העמדת את הרי ואת ממלכתי בעוז וביציבות; ברגע שהסתרת את פניך – מיד הייתי מבוהל ואובד עצות.",
  "30_9": "אליך, ה', קראתי, ואל אלוהיי התחננתי בלשון בקשה:",
  "30_10": "איזו תועלת ורווח יהיו במותי ובשפיכת דמי, אם ארד לקבר ולשחת? האם העפר שבקבר יכול להודות לך? האם הוא יכול להגיד את אמתך?",
  "30_11": "שמע, ה', וחמול עליי; ה', היה לי לעוזר ולמושיע!",
  "30_12": "ואכן, הפכת את מספדי ואבלי למחול של שמחה; פתחת והסרת ממני את שק האבל, וחגרת אותי בבגדי שמחה ואושר,",
  "30_13": "כדי שנשמתי וכבודי יזמרו ויודו לך תמיד ולא יידומו; ה' אלוהיי, לעולם ועד אודה לך ואשבחך!",
  "31_1": "למנצח, מזמור תפילה לדוד.",
  "31_2": "בך, ה', שמתי את כל מבטחי; אל תיתן לי להתבייש לעולם; בצדקתך הצל וחלץ אותי.",
  "31_3": "הטה אליי את אוזנך, מהר והצל אותי; היה לי לצור ומבצר חזק, לבית מוגן שיושיע אותי.",
  "31_4": "כי סלעי ומצודתי הבטוחה אתה; למען כבוד שמך תנהיג אותי ותדריך אותי בדרך הישר.",
  "31_5": "הוצא אותי מן הרשת והמלכודת שטמנו לי בסתר, כי אתה הוא מעוזי ומגיני.",
  "31_6": "בידך אפקיד את רוחי ונשמתי; אתה פדית והצלת אותי, ה' אל האמת.",
  "31_7": "שנאתי והתרחקתי מכל הדבקים באלילי הבל ושווא, ואילו אני – רק בה' בטחתי.",
  "31_8": "אגיל ואשמח מאוד בחסדך, אשר ראית את עוניי וסבלי, וידעת והכרת את צרות נפשי ומצוקותיי.",
  "31_9": "ולא הסגרת אותי בידי האויב, אלא העמדת במקום רחב ובטוח את רגליי.",
  "31_10": "חמול עליי, ה', כי צר לי מאוד; עיני כהתה מרוב בכי וכעס, וגם נפשי ובטני דעכו מרוב צער.",
  "31_11": "כי ימיי כלים ביגון ושנותיי באנחות; כוחי כשל בגלל עווני, ועצמותיי נשחקו ורופפות.",
  "31_12": "בגלל כל אויביי הפכתי לחרפה, ובמיוחד לשכניי, ולפחד ומורא למכיריי; כל הרואים אותי ברחוב בורחים ממני.",
  "31_13": "נשכחתי מלב האנשים כאילו הייתי מת, והייתי בעיניהם ככלי שבור שאין בו שום חפץ.",
  "31_14": "כי שמעתי את דברי הדיבה והרכילות של רבים, והפחד מקיף אותי מסביב כאשר הם מתייעצים יחד נגדי וזוממים לקחת את חיי.",
  "31_15": "ואני – בך בלבד בטחתי, ה'; אמרתי בכל לבי: אתה הוא אלוהיי!",
  "31_16": "בידך וברשותך מסורות עתותיי וכל תקופות חיי; הצל אותי מיד אויביי ומן הרודפים אחריי.",
  "31_17": "האר את פניך והשגחתך לטובה על עבדך, והושע אותי בזכות חסדך ואהבתך.",
  "31_18": "ה', אל אתבייש כשאני קורא אליך; ייבושו הרשעים וישתתקו אל השאול והקבר.",
  "31_19": "ייאלמו וישתתקו שפתי שקר המדברות על הצדיק דברי עתק, גאווה ובוז.",
  "31_20": "כמה רב ועצום הוא טובך אשר צפנת ושמרת ליראיך, ואשר פעלת והענקת לבוטחים בך לנגד עיני כל בני האדם!",
  "31_21": "תסתיר אותם בסתר נוכחותך מפני מזימותיהם של אנשים רעים; תצפון ותגן עליהם בסוכה מפני ריב לשונות ודברי רכילות.",
  "31_22": "ברוך ומשובח ה', שהפליא והראה לי את חסדו הנפלא כמו במבצר ובעיר מצור מוגנת.",
  "31_23": "ואני חשבתי בבהלתי ובחפזי: נגזרתי ונכרתתי מנגד עיניך! אך באמת שמעת את קול תחנוניי כאשר זעקתי אליך.",
  "31_24": "אהבו את ה', כל חסידיו ונאמניו! ה' שומר ומגן על אנשי האמונה, ומשלם במידה מלאה לגאוותן הנוהג ביהירות.",
  "31_25": "התחזקו והיו אמיצים בלבבכם, כל המייחלים ומקווים לעזרת ה'!",
  "32_1": "מזמור של מוסר והשכל שחיבר דוד: אשרי ומאושר האדם שפשעו נסלח וחטאו כוסה ונמחל.",
  "32_2": "אשרי האדם שה' אינו מייחס לו עוון, וברוחו הפנימית אין שום צביעות או רמייה.",
  "32_3": "כאשר שתקתי ולא התוודיתי על חטאי, בלו ונשחקו עצמותיי מרוב זעקתי וכאבי כל היום.",
  "32_4": "כי יומם ולילה הייתה ידך כבדה עליי במוסר; לשד חיי ורעננותי התייבשו כבימי חרבוני קיץ לוהטים.",
  "32_5": "אז החלטתי להודות בפניך על חטאתי, ואת עווני לא הסתרתי עוד; אמרתי: אתוודה על פשעיי לפני ה', ואתה מיד סלחת ומחלת על עוון חטאתי.",
  "32_6": "על זאת יתפלל כל איש חסיד אליך בעת מציאת רצון וסליחה; ואז, גם כאשר יבואו שיטפונות של מים רבים וצרות גדולות – אליו הם לא יגיעו.",
  "32_7": "אתה מקום מסתור ומקלט עבורי; מפני כל צרה תנצור ותשמור עליי, ובשירי הצלה והצלה תקיף אותי תמיד.",
  "32_8": "ה' אומר: אשכילך ואלמדך באיזו דרך עליך ללכת; אייעץ לך בטוב ועיני תהיה תמיד עליך להשגיח.",
  "32_9": "אל תהיו חסרי בינה כמו סוס או פרד, שצריך לרסן את פיהם במתג ורסן כדי שלא יתקרבו להזיק לך.",
  "32_10": "מכאובים וייסורים רבים פוקדים את הרשע, אך מי שבוטח בה' – חסד ואהבה יקיפו אותו מכל עבר.",
  "32_11": "שמחו בה' וצהלו, הצדיקים, והריעו בשמחה, כל הישרים בלבבם!",
  "33_1": "רננו ושבחו את ה', הצדיקים; לאנשים ישרים והגונים נאה ומתאים להלל ולשבח.",
  "33_2": "הודו לה' בליווי נבל, בכינור עשור (בעל עשרה מיתרים) זמרו לו שירי קודש.",
  "33_3": "שירו לו שיר חדש ומחודש; היטיבו לנגן בכלי שיר בליווי תרועה של שמחה.",
  "33_4": "כי דבר ה' ישר ונכון, וכל מעשיו נעשים באמונה ובנאמנות מוחלטת.",
  "33_5": "הוא אוהב צדקה ומשפט; כל הארץ מלאה מחסדו וטובו של ה'.",
  "33_6": "בדבר ה' ובמאמרו נבראו השמיים, וברוח פיו כל צבא הכוכבים והמאורות.",
  "33_7": "הוא כונס ואוסף כמו חומה ונד את מי הים, ואוגר במאגרים נסתרים את מי התהומות.",
  "33_8": "ייראו מה' כל תושבי הארץ, ומפניו יחרדו ויכבדו כל יושבי תבל.",
  "33_9": "כי הוא רק אמר – והדבר נהיה מיד; הוא ציווה – והעולם עמד על מכונו.",
  "33_10": "ה' הפר וביטל את עצת עמי העולם, וסיכל את מזימותיהם ומחשבותיהם של הלאומים.",
  "33_11": "אך עצת ה' ותוכניתו תעמוד לנצח, ומחשבות לבו קיימות לדור ודור.",
  "33_12": "אשרי העם שה' הוא אלוהיו, העם שבחר בו לנחלה ולחלק לו.",
  "33_13": "ה' משקיף ממרומי השמיים, ורואה בהשגחתו את כל בני האדם.",
  "33_14": "ממקום משכנו הקדוש הוא מביט וצופה על כל יושבי הארץ.",
  "33_15": "הוא היוצר יחד את לב כולם, והוא המבין והמודע לכל מעשיהם ומניעיהם.",
  "33_16": "מלך אינו נושע ומנצח רק בזכות צבא עם רב, וגיבור מלחמה אינו ניצל רק בזכות כוחו העצום.",
  "33_17": "הסוס הוא משענת שווא להצלה, וברוב כוחו ומהירותו אינו יכול לחלץ את האדם לבדו.",
  "33_18": "הנה עין ה' והשגחתו פקוחות על יראיו, על כל המייחלים ומקווים לחסדו ולרחמיו,",
  "33_19": "כדי להציל ממוות את נפשם, ולכלכל ולהחיות אותם בימי רעב ומחסור.",
  "33_20": "נפשנו חיכתה וייחלה לה'; הוא עזרתנו והמגן השומר עלינו.",
  "33_21": "כי בו ישמח לבנו, שהרי בשם קודשו בטחנו בלב שלם.",
  "33_22": "יהי חסדך ורחמיך עלינו, ה', בדיוק כפי שייחלנו וקיווינו לעזרתך!",
  "34_1": "מזמור שחיבר דוד כאשר התחזה למשוגע לפני אכיש (המכונה אבמילך מלך גת), וזה גירש אותו וכך ניצל והלך לדרכו.",
  "34_2": "אברך ואשבח את ה' בכל עת ובכל מצב; תמיד תהילתו ושבחו יהיו בפי.",
  "34_3": "בה' תתפאר ותשמח נפשי; ישמעו זאת הענווים והסובלים וישמחו בהצלתי.",
  "34_4": "רוממו והגדילו את ה' יחד עמי, ונשבח את שמו הגדול כולנו יחדיו.",
  "34_5": "חיפשתי ודרשתי את ה' בתפילה והוא ענה לי, ומכל פחדיי ומוראיי הציל וחילץ אותי.",
  "34_6": "כל המביטים ומייחלים אליו זוכים לאור ולשמחה, ופניהם לעולם לא יתביישו.",
  "34_7": "הנה העני והמדוכא הזה (דוד) קרא בתפילה וה' שמע אותו, ומכל צרותיו ומצוקותיו הושיע אותו.",
  "34_8": "מלאך ה' חונה ושומר מסביב לאלה שיראים אותו, ומחלץ ומציל אותם מכל סכנה.",
  "34_9": "טעמו והתבוננו וראו בעצמכם כי ה' טוב ומיטיב; אשרי האדם המוצא בו מחסה ומבטח.",
  "34_10": "יראו את ה', קדושיו ונאמניו, שהרי שום מחסור וחסרון אין למי שיראים אותו באמת.",
  "34_11": "אפילו כפירי אריות חזקים עשויים להיעשות עניים ולרעוב לטרף, אך דורשי ה' ומבקשיו לא יחסרו שום דבר טוב.",
  "34_12": "בואו, בנים יקרים, והקשיבו לי; את יראת ה' ואת הדרך הנכונה אלמד אתכם.",
  "34_13": "מי הוא האדם החפץ בחיים אמיתיים, האוהב ימים רבים כדי לראות בהם טוב ושלווה?",
  "34_14": "שמור על לשונך שלא לדבר רע ולשון הרע, ועל שפתיך מלדבר דברי מרמה ושקר.",
  "34_15": "התרחק מכל מעשה רע ועשה רק טוב; בקש את השלום ורדוף אחריו להשיגו.",
  "34_16": "עיני ה' פקוחות להשגיח על הצדיקים, ואוזניו קשובות לזעקתם ותפילתם.",
  "34_17": "אך פני ה' וכעסו מופנים כנגד עושי הרע, כדי להשמיד ולהכרית מן הארץ את זכרם.",
  "34_18": "צעקו הצדיקים בתפילה וה' שמע אותם, ומכל צרותיהם הציל אותם.",
  "34_19": "ה' קרוב במיוחד אל האנשים שנשבר לבם מצער, ואת שפלי הרוח והענווים הוא מושיע.",
  "34_20": "צרות וניסיונות רבים עשויים לפקוד את הצדיק, אך מכולם מציל ומחלץ אותו ה'.",
  "34_21": "הוא שומר ומגן על כל איבריו ועצמותיו, ואפילו אחת מהן לא תישבר ברעה.",
  "34_22": "הרשעה והמעשים הרעים יביאו למותו של הרשע, וכל שונאי הצדיק יימצאו אשמים וייענשו.",
  "34_23": "ה' פודה ומציל ממוות את נפש עבדיו, ולעולם לא יאשמו ולא יאבדו כל אלה המוצאים בו מחסה.",
  "35_1": "מזמור שחיבר דוד: ה', ריב והכרע כנגד אלה שרבים עמי, והילחם כנגד אלה שנלחמים בי.",
  "35_2": "אחוז במגן ובצינה של הגנה, וקום לעזרתי במלחמתי.",
  "35_3": "שלוף חנית וחסום את הדרך לקראת הרודפים אחריי; אמור לנפשי: אני הוא ישועתך והצלתך!",
  "35_4": "יתביישו וייכלמו כל המבקשים לפגוע בנפשי; ייסוגו לאחור ויתמלאו בושה כל החושבים ומתכננים את רעתי.",
  "35_5": "שיהיו קלים ונסחפים כמו מוץ מול הרוח, כאשר מלאך ה' דוחף ומפזר אותם.",
  "35_6": "שדרכם תהיה חשוכה ומלאה במכשולים מחליקים, כשמלאך ה' רודף אחריהם ומפילם.",
  "35_7": "כי ללא כל סיבה ועל לא עוול בכפי טמנו לי מלכודת שחת ברשתם, וללא סיבה חפרו בור ללכוד את נפשי.",
  "35_8": "תבוא עליו מפלה ואסון פתאומי מבלי שיידע, והרשת שהוא עצמו טמן לאחרים תלכוד אותו, ובחורבן שתיכנן הוא עצמו ייפול.",
  "35_9": "ואילו נפשי תגל ותשמח בה', ותצהל בישועתו הגדולה.",
  "35_10": "כל עצמותיי ואיבריי יאמרו בהתרגשות: ה', מי כמוך מציל אדם חלש ועני ממי שחזק ממנו, ועני ואביון מידי גוזלו ועושקו!",
  "35_11": "קמים נגדי עדי חמס ושקר; דברים ומעשים שמעולם לא ידעתי ולא עשיתי הם שואלים ומאשימים אותי.",
  "35_12": "הם משלמים וגומלים לי רעה תחת הטובה שהענקתי להם, עד שגרמו לשכול ובדידות לנפשי.",
  "35_13": "ואילו אני – כאשר הם היו חולים, לבשתי שק של אבל, עיניתי את נפשי בצום והתפללתי עליהם, ותפילתי כאילו חזרה לחיקי בכוונתה הטהורה.",
  "35_14": "התנהגתי וכאבתי כאילו מדובר בחבר או באח שלי; כמי שמתאבל על אמו התהלכתי קודר ושפוף מצער.",
  "35_15": "אך כאשר אני נכשלתי וצלעתי – הם שמחו והתאספו יחד; התאספו נגדי אנשים שפלים ונכים מבלי שידעתי, קרעו את כבודי בדברי נאצה ולא שתקו.",
  "35_16": "בחברת חנפנים שלועגים תמורת כיכר לחם (מעוג), חרקו עליי את שיניהם בכעס ובשנאה.",
  "35_17": "אדוני, עד מתי תביט מנגד ותשתוק? השב והצל את נפשי מן החורבן שהם מביאים, ומידי אנשים אכזריים כאריות הצל את חיי היחידים.",
  "35_18": "אודה לך בהתרגשות בקהל רב, ובקרב עם עצום אהלל ואשבח אותך.",
  "35_19": "אל יחגגו וירקדו על מפלתי אויביי השקרנים, ושונאיי ששונאים אותי חינם – אל יקרצו עין בלעג זה לזה.",
  "35_20": "כי הם אינם מדברים דברי שלום, אלא חושבים מזימות מרמה כנגד האנשים השקטים והתמימים שיושבים בארץ.",
  "35_21": "הם פערו את פיהם לרווחה נגדי ואמרו בלעג: האח, האח! ראינו בעינינו את מפלתו!",
  "35_22": "אתה ראית זאת, ה', אל תחריש ואל תשתוק; אדוני, אל תתרחק ממני!",
  "35_23": "התעורר והקץ לעשות לי משפט צדק, אלוהיי ואדוני, הכרע בריבי!",
  "35_24": "שפוט אותי כפי צדקתך, ה' אלוהיי, ואל תיתן להם לשמוח על צרתי.",
  "35_25": "אל יאמרו בלבבם: האח, קיבלנו את רצון נפשנו! ואל יאמרו: הנה בלענו והשמדנו אותו!",
  "35_26": "יתביישו וייכלמו יחדיו כל השמחים לרעתי; יתעטפו בבושה ובחרפה כל המתנשאים והמתפארים עליי.",
  "35_27": "ירננו וישמחו כל החפצים בצדקתי ובניצחוני, ויאמרו תמיד: יתגדל ויתרומם ה' החפץ בשלום עבדו ובטובתו!",
  "35_28": "ולשוני תדבר ותספר על צדקתך, ובכל יום תהלל ותשבח אותך תמיד.",
  "36_1": "למנצח, לעבד ה' דוד.",
  "36_2": "נאום והכרת הרשע יושבים בלבו של החוטא; אין לנגד עיניו שום פחד ומורא מאלוהים.",
  "36_3": "כי הרשע מחמיא לעצמו בעיניו עד שנמצא שעוונו מאוס ומתועב בעיני הכל.",
  "36_4": "דברי פיו הם עוול ותרמית; הוא חדל מלהשכיל ולהיטיב את דרכיו.",
  "36_5": "עוול ומזימות רעות הוא חושב על משכבו; הוא מתייצב בעקביות על דרך שאינה טובה, ומעשים רעים אינו מואס.",
  "36_6": "ה', חסדך ואהבתך מגיעים עד השמיים, ונאמנותך ואמיתך עד ענקי השחקים.",
  "36_7": "צדקתך איתנה וחזקה כהרי אל רמים, ומשפטיך עמוקים ונסתרים כמי תהום רבה; אדם ובהמה כאחד אתה מושיע ומקיים, ה'.",
  "36_8": "כמה יקר ונעלה הוא חסדך, אלוהים! ובני האדם חוסים בבטחה בצל כנפיך הרחומות.",
  "36_9": "הם ישבעו משפע הדשן והברכה של ביתך, ומנחל תענוגותיך ועדניך תשקה אותם.",
  "36_10": "כי עמך נמצא מקור החיים האמיתיים, ובאורך ובזיוו נראה אור ושמחה.",
  "36_11": "המשך והרעף את חסדך על יודעיך ומכיריך, ואת צדקתך על הישרים בלבבם.",
  "36_12": "אל תיתן לרגל הגאוותן לבוא ולרמוס אותי, ויד הרשעים אל תגרש ואל תטלטל אותי.",
  "36_13": "הנה שם נפלו עושי העוול והפשע; הם הוכרעו ונפלו לארץ ולא יוכלו לקום עוד!",
  "37_1": "מזמור של הדרכה וביטחון לדוד: אל תתעצבן ואל תקנא ברשעים המצליחים, ואל תקנא בעושי עוול.",
  "37_2": "כי במהירות כמו עשב הם ייקצצו וייבלו, וכמו עשב ירוק הם יתייבשו וייעלמו.",
  "37_3": "בטח בה' ועשה מעשים טובים; שכון בארץ בשלווה וחייה בנאמנות ובאמונה.",
  "37_4": "התענג ושמח בה' ובמצוותיו, והוא ייתן וימלא לך את כל משאלות לבך הטובות.",
  "37_5": "גלול ומסור לה' את דרכך ובטח בו בלב שלם, והוא יוציא לפועל את ישועתך.",
  "37_6": "והוא יוציא כאור הזוהר את צדקתך, ואת משפטך וזכאותך יאיר כצהרי היום הבהירים.",
  "37_7": "דום והמתן בדממה לה' וצפה לעזרתו בסבלנות; אל תתרגז על אדם שמצליח בדרכו הרעה, על איש שמוציא לפועל מזימות של עוול.",
  "37_8": "הרפה מן הכעס ועזוב את החימה; אל תתרגז, כי כעס מוביל רק לעשות רע.",
  "37_9": "כי עושי הרע ייכרתו ויאבדו מן העולם, אך המקווים לה' – הם יירשו את הארץ ויתקיימו בה.",
  "37_10": "עוד מעט זמן קצר והרשע כבר לא יהיה; תתבונן היטב על מקומו – והוא איננו שם.",
  "37_11": "אך הענווים והצנועים יירשו ארץ, ויתענגו וייהנו מרוב שלום ושלווה.",
  "37_12": "הרשע זומם מזימות רעות כנגד הצדיק, וחורק עליו את שיניו בכעס ובשנאה.",
  "37_13": "אך ה' צוחק ולועג לו, כי הוא רואה שיום פקודתו ועונשו של הרשע כבר קרב ובא.",
  "37_14": "הרשעים פתחו חרב ודרכו את קשתם כדי להפיל עני ואביון, וכדי לטבוח באנשים שהולכים בדרך ישרה.",
  "37_15": "אך חרבם שלהם תיכנס ותפגע בתוך לבם שלהם, וקשתותיהם יישברו לרסיסים.",
  "37_16": "טוב ומתוק המעט שיש לצדיק בזכות יושרו, מההמון והשפע שיש לרשעים רבים.",
  "37_17": "כי זרועותיהם וכוחם של הרשעים יישברו, אך את הצדיקים תומך ומחזיק ה'.",
  "37_18": "ה' יודע ומשגיח על ימיהם וחייהם של האנשים התמימים והשלמים, ונחלתם תתקיים לעד.",
  "37_19": "הם לא יתביישו בעת של צרה ורעה, ובימי רעב ומחסור הם ישבעו ויתברכו.",
  "37_20": "כי הרשעים יאבדו, ואויבי ה' יכלו כמו שומן כבשים הנשרף על המזבח – כעשן הם יכלו וייעלמו כליל.",
  "37_21": "הרשע לווה כספים ואינו מחזיר את חובו, ואילו הצדיק חומל, מעניק ונותן ברוחב לב.",
  "37_22": "כי מבורכיו של ה' יירשו את הארץ, ואילו המקוללים מפניו ייכרתו ממנה.",
  "37_23": "צעדיו של אדם ישר מכוננים ומודרכים מאת ה', ואת דרכו של הצדיק הוא אוהב ורוצה בה.",
  "37_24": "גם אם ימעד וייפול – לא יתרסק ולא יוטל לארץ, כי ה' תומך ומחזיק בידו.",
  "37_25": "נער צעיר הייתי וגם זקנתי, ומעולם לא ראיתי צדיק אמיתי שננטש לעזאזל וזרעו נאלץ לחזר על הפתחים לבקש לחם.",
  "37_26": "בכל יום הוא מגלה רחמים ומלווה לנזקקים, וצאצאיו זוכים לברכה.",
  "37_27": "סור מרע ועשה טוב, ותזכה לשכון ולחיות בשלווה לעולם.",
  "37_28": "כי ה' אוהב צדק ומשפט ולא יעזוב את חסידיו ונאמניו לעולם; הם יישמרו תמיד, אך זרעם של הרשעים ייכרת.",
  "37_29": "הצדיקים יירשו את הארץ, וישכנו בה לעד ולעולמי עולמים.",
  "37_30": "פיו של הצדיק הוגה ומדבר דברי חוכמה, ולשונו מבטאת משפט וצדק.",
  "37_31": "תורת אלוהיו נמצאת עמוק בתוך לבו, ולכן צעדיו לא ימעדו מדרך הישר.",
  "37_32": "הרשע צופה ועוקב אחרי הצדיק, ומבקש הזדמנות להמית אותו.",
  "37_33": "אך ה' לא יעזוב ולא יפקיר את הצדיק בידו, ולא יניח לו להרשיע אותו כאשר יישפט.",
  "37_34": "קווה וייחל לה' ושמור את דרכו, והוא ירומם אותך לרשת את הארץ; כאשר הרשעים ייכרתו – אתה תראה זאת בעיניך.",
  "37_35": "ראיתי רשע עריץ וחזק, שמתפשט ומתגאה כמו אילן רענן באדמתו המקורית;",
  "37_36": "אך עבר זמן קצר והנה הוא איננו; חיפשתי אותו – ולא נמצא עוד שום זכר לו.",
  "37_37": "התבונן באיש התמים וראה את האדם הישר, כי לאיש שלום יש עתיד ואחרית טובה.",
  "37_38": "ואילו הפושעים והמורדים יישמדו יחדיו, ואחריתם ועתידם של הרשעים ייכרתו.",
  "37_39": "ישועתם של הצדיקים באה מאת ה'; הוא מעוזם ומבצרם בעת של צרה ומצוקה.",
  "37_40": "ה' עוזר להם ומחלץ אותם; הוא יחלץ אותם מידי הרשעים ויושיע אותם, כי שמו בו את מבטחם.",
  "38_1": "מזמור שחיבר דוד להזכיר ולהעלות את זכרונו לפני ה' בעת חוליו וייסוריו.",
  "38_2": "ה', אל תוכיח אותי מתוך כעסך הגדול, ואל תייסר אותי בחמת זעמך.",
  "38_3": "כי חיצי ייסוריך ננעצו בי עמוק, וידך המייסרת נחתה עליי בכובד.",
  "38_4": "אין שום מקום בריא ושלם בבשרי בגלל כעסך; אין שלום ומרפא בעצמותיי בגלל חטאיי ועוונותיי.",
  "38_5": "כי עוונותיי וחטאיי גדלו ועברו מעל ראשי; כמו משא כבד מדי הם מכבידים עליי ואינני יכול לשאתם.",
  "38_6": "פצעיי הבאישו ונמקו מרוב חולי, כעונש על איוולתי ושגיאותיי.",
  "38_7": "נעוויתי ונתעקמתי, שחתי והשתופפתי עד מאוד; כל היום התהלכתי קודר באבל ובצער.",
  "38_8": "כי מותניי וקרביי מלאו חום דלקתי לוהט, ואין שום מתום ובריאות בבשרי.",
  "38_9": "נחלשתי ונדכאתי עד מאוד; שאגתי וזעקתי מתוך המיית לבי וסבלי.",
  "38_10": "אדוני, כל משאלת לבי גלויה וידועה לפניך, ואנחתי ומצוקתי אינן נסתרות ממך.",
  "38_11": "לבי סוער ופועם בחוזקה, כוחי עזב אותי, ואפילו מאור עיניי כהה ואיננו עמי.",
  "38_12": "אוהביי ורעיי עומדים מרחוק בגלל נגעי ומחלתי, וקרוביי עומדים מרחוק ואינם ניגשים לעזור.",
  "38_13": "ואילו המבקשים את נפשי מניחים מלכודות, ודורשי רעתי מדברים מזימות הרס ומהרהרים בתרמיות כל היום.",
  "38_14": "ואילו אני – התנהגתי כחירש שאינו שומע, וכאילם שאינו פותח את פיו להשיב.",
  "38_15": "והייתי כמו אדם שאינו שומע כלל, ושאין בפיו דברי ויכוח ותוכחה להגן על עצמו.",
  "38_16": "כי אליך, ה', ייחלתי וקיוויתי; אתה הוא שתענה במקומי, ה' אלוהיי!",
  "38_17": "כי אמרתי בתפילתי: פן ישמחו עליי אויביי, וכאשר רגלי תמעד – יתנשאו ויתפארו עליי.",
  "38_18": "כי אני מוכן וקרוב לנפילה (צליעה), ומכאובי ויגוני עומדים לנגד עיניי תמיד.",
  "38_19": "כי את עווני אגיד ואתוודה עליו, ואדאג ואצטער על חטאתי.",
  "38_20": "אך אויביי חיים, בריאים וחזקים, ורבו מאוד האנשים ששונאים אותי ללא שום סיבה צודקת.",
  "38_21": "והם משלמים לי רעה תחת הטובה שעשיתי להם; הם מתנכלים לי רק משום שאני רודף אחרי הטוב והיושר.",
  "38_22": "אל תעזוב אותי, ה'! אלוהיי, אל תתרחק ממני!",
  "38_23": "מהר לעזרתי, אדוני, ישועתי והצלתי!",
  "39_1": "למנצח, למשפחת ידותון המשורר, מזמור לדוד.",
  "39_2": "אמרתי בלבי: אשמור ואזהר בדרכיי כדי שלא אחטא בלשוני; אשים מחסום לפי כל עוד הרשע עומד לנגדי ומתגרה בי.",
  "39_3": "נאלמתי דומייה ושתקתי, נמנעתי אפילו מדיבור טוב; אך בגלל השתיקה כאבי הפנימי גבר ונעכר יותר.",
  "39_4": "לבי התחמם וסער בקרבי, ובעת מחשבותיי והרהוריי בערה אש יקוד – ואז פתחתי ודיברתי בלשוני:",
  "39_5": "הודע ולמד אותי, ה', את קצי וסוף ימיי, ומהו שיעור ומשך ימיי עלי אדמות, כדי שאדע כמה חולף וקצר אני בעולם.",
  "39_6": "הנה נתת לי ימי חיים קצרים מדודים ברוחב טפחים בלבד, וכל משך שנות חיי נחשב כאין וכאפס לפניך; אכן כל אדם הניצב בעולם אינו אלא הבל חולף.",
  "39_7": "אכן כצל חולף מתהלך כל אדם, ורק על הבל ודברים חולפים הם סוערים וטורחים; אדם צובר הון ורכוש ואינו יודע מי יאסוף וייקח אותם אחרי מותו.",
  "39_8": "ועתה, אדוני, למה אני מייחל ומקווה בעולם הזה? תקוותי ותוחלתי תלויות בך בלבד!",
  "39_9": "הצל אותי מכל פשעיי וחטאיי, ואל תשים אותי למושא חרפה ובוז לאדם נבל ושפל.",
  "39_10": "נאלמתי ושתקתי, לא אפתח את פי בטענה – כי ידעתי שאתה הבאת עליי את הייסורים בצדק.",
  "39_11": "הסר מעליי את מכתך וייסוריך, שהרי מהמאבק עם ידך הכבדה אני כלה ונחלש.",
  "39_12": "בתוכחות ובעונשים על עוון ייסרת את האדם, והמסת את כל הדברים היקרים והחמודים שלו כאילו אכל אותם עש; אכן כל אדם אינו אלא הבל.",
  "39_13": "שמע את תפילתי, ה', והאזן לזעקתי; אל תשתוק ואל תתעלם מדמעותיי, שהרי גר וזר אני עמך בארץ, ותושב חולף כמו כל אבותיי.",
  "39_14": "הרפה ממני והנח לי מעט כדי שאתאושש ואתחזק, בטרם אלך מן העולם הזה ולא אהיה עוד בין החיים.",
  "40_1": "למנצח, מזמור תודה שחיבר דוד.",
  "40_2": "קיוויתי וייחלתי בביטחון שלם לה', והוא הטה את אוזנו אליי ושמע את זעקתי ותפילתי.",
  "40_3": "והוא העלה וחילץ אותי מבור שאון ומצולה, מטיט טובעני וחלקלק, והעמיד את רגליי על גבי סלע איתן וכונן וייצב את פסיעותיי.",
  "40_4": "והוא שם בפי שיר חדש, שיר תהילה והודיה לאלוהינו; רבים יראו את ישועתי וייראו מה', ויבטחו בה' גם הם.",
  "40_5": "אשרי האיש ששם את ה' למבטחו היחיד, ולא פנה אל אנשים גאוותנים ורברבנים ואל רודפי שקר וכזב.",
  "40_6": "נפלאות רבות וגדולות עשית, ה' אלוהיי, ומחשבותיך וכוונותיך הטובות כלפינו – אין דבר שניתן לערוך ולהשוות אליך; אם ארצה להגיד ולדבר עליהן – הן רבות מכדי שניתן יהיה לספרן!",
  "40_7": "קורבנות של זבח ומנחה לא דרשת כעיקר; אוזניים פתחת לי לשמוע ולהבין את רצונך; קורבנות עולה וחטאת לא ביקשת כתחליף ליושר הלב.",
  "40_8": "אז אמרתי: הנה באתי ברצון לשרתך; במגילת ספר התורה כתוב ומצווה עליי מה לעשות.",
  "40_9": "לעשות את רצונך הטוב, אלוהיי, חפצתי בכל לבי, ותורתך חקוקה בתוך מעיי וקרביי.",
  "40_10": "בישרתי ופרסמתי את צדקתך בקהל רב; הנה את שפתיי לא אמנע מלשבח, ה', אתה יודע זאת היטב.",
  "40_11": "את צדקתך לא הסתרתי בתוך לבי; את נאמנותך ואת ישועתך אמרתי בקול; לא כיחדתי ולא העלמתי את חסדך ואמיתך מקהל גדול.",
  "40_12": "אתה, ה', לא תמנע ולא תחסום את רחמיך ממני; חסדך ואמיתך ישמרו ויגנו עליי תמיד.",
  "40_13": "כי הקיפו אותי צרות ורעות רבות לאין מספר; עוונותיי השיגו ומצאו אותי ואינני יכול אפילו לראות מרוב בושה וחולשה; הם רבים יותר משערות ראשי, ולבי כשל ורפה.",
  "40_14": "רצה והסכם, ה', להציל אותי; ה', מהר לעזרתי!",
  "40_15": "יתביישו וייכלמו יחדיו כל המבקשים להכרית ולכלות את נפשי; ייסוגו לאחור ויתמלאו בושה כל החפצים ברעתי.",
  "40_16": "יישמו ויוכו בתדהמה בגלל חרפתם ובושתם, אותם אנשים האומרים עליי בלעג: האח, האח!",
  "40_17": "אך ישישו וישמחו בך כל מבקשי קרבתך; יאמרו תמיד: יתגדל ויתרומם ה', כל אותם האוהבים את ישועתך!",
  "40_18": "ואילו אני – אדם עני ואביון, אך אדוני חושב ודואג לי; עזרתי ומציל נפשי אתה, אלוהיי, אל תתעכב!",
  "41_1": "למנצח, מזמור תפילה לדוד.",
  "41_2": "אשרי ומאושר האדם שמתבונן, דואג ומסייע לאדם דל ומסכן; ביום שבו תבוא עליו צרה – ה' ימלט ויציל אותו.",
  "41_3": "ה' ישמור עליו ויקיים אותו בחיים, הוא ייחשב למאושר ומבורך בארץ, ואל תמסור אותו בידי תאוותם של אויביו.",
  "41_4": "ה' יתמוך ויחזק אותו בעת שישכב על מיטת חוליו; את כל משכבו תהפוך ותרפא בעת חוליו עד שיבריא.",
  "41_5": "אני אמרתי בתפילתי: ה', חמול עליי; רפא את נפשי ואת גופי, כי שגיתי וחטאתי לפניך.",
  "41_6": "אויביי מדברים עליי דברים רעים ושואלים בלעג: מתי הוא ימות כבר ויישכח ויימחק שמו מן העולם?",
  "41_7": "וכאשר אחד מהם בא לבקר אותי כביכול לחלות את פניי – שקר הוא מדבר; לבו אוסף רכילות ומחשבות רעות, וכאשר הוא יוצא החוצה – הוא מפיץ אותן.",
  "41_8": "יחד מתלחשים עליי כל שונאיי; עליי הם חושבים ומתכננים דברים רעים ומזיקים.",
  "41_9": "ואומרים: מחלה סופנית ומקוללת נדבקה בו, ועכשיו שהוא נפל למשכב – הוא לא יקום ממנו עוד!",
  "41_10": "אפילו איש שלומי וידידי הקרוב שבטחתי בו ואשר אכל לחם על שולחני – הגדיל עליי את עקבו ובגד בי בנבזות.",
  "41_11": "אך אתה, ה', חמול עליי והקם אותי ממיטת חוליי, ואוכל לגמול להם כפי שמגיע להם.",
  "41_12": "בזאת אדע בבירור כי חפצת בי ורצית בי – בכך שאויבי לא יריע ולא יחגוג על מפלתי.",
  "41_13": "ואילו אני – בזכות תמימותי ויושר לבי תמכת בי, ותעמיד ותציב אותי לפניך לנצח.",
  "41_14": "ברוך ומשובח ה' אלוהי ישראל, מן העולם ועד העולם! אמן ואמן!",
  "42_1": "למנצח, שיר מוסר והשכל עמוק שחיברו בני קורח.",
  "42_2": "כמו אייל שצמא ומשתוקק לפלגי מים קרירים, כך נפשי משתוקקת וצמאה אליך, אלוהים.",
  "42_3": "צמאה נפשי לאלוהים, לאל החי והקיים; מתי כבר אזכה לבוא ולראות את פני אלוהים בבית המקדש?",
  "42_4": "דמעותיי הפכו למזווני יומם ולילה מרוב צער, כאשר אויביי מקניטים אותי כל היום ושואלים: היכן הוא אלוהיך שעליו בטחת?",
  "42_5": "את הימים הטובים ההם אזכור ולבי יישפך בי מגעגועים – כיצד הייתי עובר בתוך שיירות העולים לרגל ומוביל אותם עד בית אלוהים, בקולות שירה, תודה והמון חוגג.",
  "42_6": "מדוע את שפופה ועצובה, נפשי, ומדוע את נאנחת בקרבי? קווי וייחלי לאלוהים, כי עוד אזכה להודות לו על הישועות שיביא במאור פניו!",
  "42_7": "אלוהיי, נפשי כפופה ועצובה בקרבי; לכן אזכור אותך ממקומות גלותי בארץ הירדן, מהרי החרמון ומהר מצער הקטן.",
  "42_8": "תהום עמוקה אחת של צרה קוראת לתהום אחרת לקול רעש מפלי המים שלך; כל גלי משבריך והצרות ששלחת עברו ושטפו אותי.",
  "42_9": "אך בטוח אני שביום יצווה ה' את חסדו עליי, ובלילה שירתו תהיה עמי – תפילת הודיה לאל חיי.",
  "42_10": "אומר לאל, סלעי ומבצרי: מדוע שכחת אותי? מדוע עליי להתהלך קודר ושפוף בגלל לחץ האויב?",
  "42_11": "כמו מכת חרב קטלנית בעצמותיי הן חרפות אויביי המציקים לי, כשהם אומרים לי כל יום בלעג: היכן אלוהיך?",
  "42_12": "מדוע את שפופה ועצובה, נפשי, ומדוע את סוערת בקרבי? קווי לאלוהים, כי עוד אודה לו על הישועות המאירות של פניי, כי הוא אלוהיי!",
  "43_1": "שפוט והכרע בדיני, אלוהים, והגן על ענייני מול עם חסר חסד ומוסר; מאיש רמייה, שקר ועוול הצל וחלץ אותי.",
  "43_2": "כי אתה הוא אלוהיי ומעוזי – מדוע נטשת אותי? מדוע עליי להתהלך שחוח ואבל תחת לחצו של האויב?",
  "43_3": "שלח את אורך ואת אמיתך – הם אלה שידריכו וינהיגו אותי, ויביאו אותי אל הר קודשך ואל משכנותיך.",
  "43_4": "ואז אבוא אל מזבח אלוהים, אל האל שהוא מקור שמחתי ואושרי העילאי, ואודה לך בנגינת כינור, אלוהים אלוהיי!",
  "43_5": "מדוע את שפופה, נפשי, ומדוע את סוערת בקרבי? קווי לאלוהים, כי עוד אודה לו; הוא הישועה של פניי ואלוהיי!",
  "44_1": "למנצח, מזמור השכל לבני קורח בעת גלות ומצוקה לאומית.",
  "44_2": "אלוהים, באוזנינו שמענו ואבותינו סיפרו לנו על המעשים והניסים הגדולים שפעלת בימיהם, בימי קדם.",
  "44_3": "אתה במו ידך גירשת עמים זרים מארץ כנען ונטעת במקומם את אבותינו; היכית לאומים אחרים ושילחת אותם.",
  "44_4": "כי לא בזכות חרבם ירשו את הארץ, וזרועם וכוחם לא הושיעו אותם, אלא יד ימינך, זרועך החזקה ומאור פניך – משום שרצית בהם ואהבת אותם.",
  "44_5": "אתה הוא מלכי ושליטי, אלוהים; צווה עתה ישועה וגאולה לבני יעקב!",
  "44_6": "בעזרתך ננגח ונכניע את צרינו, ובשמך הגדול נרמוס את הקמים נגדנו.",
  "44_7": "כי אינני בוטח בקשתי לבדה, וחרבי אינה זו שתושיע אותי.",
  "44_8": "אלא אתה הושעת אותנו מאויבינו, ואת שונאינו הבשת והכלמת.",
  "44_9": "באלוהים התהללנו ושיבחנו כל היום, ולשמך נודה לעולם ועד.",
  "44_10": "אך עתה נטשת אותנו והבשת אותנו, ואינך יוצא עוד להנהיג את צבאותינו במלחמה.",
  "44_11": "הסגת אותנו לאחור מבוהלים מפני האויב, ושונאינו שוסו ובזזו לעצמם את רכושנו.",
  "44_12": "מסרת אותנו כצאן המיועד לשחיטה, ופיזרת אותנו בין עמי הגולה.",
  "44_13": "מכרת את עמך במחיר אפסי וללא שום רווח, ולא העלית את שוויים במכירתם.",
  "44_14": "שמת אותנו לחרפה ולקלס לשכנינו, ללעג ולקלס לאלה שמסביבנו.",
  "44_15": "שמת אותנו למשל ולשנינה בקרב העמים, ולתנועת ראש מזלזלת בין הלאומים.",
  "44_16": "כל היום חרפתי ובושתי עומדות לנגדי, ובושת פניי מכסה אותי לגמרי,",
  "44_17": "מקול המחרף והמגדף, ומפני האויב ומבקש הנקמה.",
  "44_18": "כל האסונות האלה באו עלינו – ובכל זאת לא שכחנו אותך, ולא בגדנו בבריתך הנאמנה.",
  "44_19": "לבנו לא נסוג לאחור מאמונתך, ופסיעותינו לא נטו מדרך מצוותיך,",
  "44_20": "אף על פי שריסקת והשפלת אותנו במקום תנים שומם, וכיסית אותנו בצלמוות של חושך ומוות.",
  "44_21": "אילו שכחנו את שם אלוהינו ופרשנו את כפינו להתפלל לאל זר –",
  "44_22": "הרי אלוהים היה חוקר ויודע זאת, כי הוא יודע את כל סודות ונבכי הלב!",
  "44_23": "אך ההפך הוא הנכון: דווקא בגללך ובשל נאמנותנו לך אנחנו נהרגים כל היום, ונחשבים כמו צאן המובל לטבח.",
  "44_24": "התעורר! למה תיראה כישן, אדוני? הקץ ואל תיטוש אותנו לנצח!",
  "44_25": "למה תסתיר את פניך מאיתנו, ותשכח את עונינו, עינויינו ומצוקתנו?",
  "44_26": "כי נפשנו כרעה ונשחקה עד עפר, וגופנו נדבק לארץ מרוב חולשה.",
  "44_27": "קומה והיה עזרה לנו, ופדה והצל אותנו למען חסדך ואהבתך!",
  "45_1": "למנצח על שושנים, מזמור השכל לבני קורח, שיר אהבה ושבח למלך המשיח.",
  "45_2": "לבי הומה ורוחש דברים טובים וחשובים; אומר אני: שיריי מוקדשים למלך, ולשוני רהוטה ומהירה כמו עט של סופר מיומן.",
  "45_3": "יפה תואר ונאה אתה מכל בני האדם, חן ונועם נשפכו על שפתיך; לכן ברך אותך אלוהים לעולם.",
  "45_4": "חגור את חרבך על ירכך, גיבור מלחמה – זהו הודך ותפארתך המלכותית!",
  "45_5": "ובהדרך עלה ורכב בהצלחה על ענייני אמת, ענווה וצדק; וימינך תלמד אותך מעשים נוראי הוד וגבורה.",
  "45_6": "חיציך חדים ופוגעים בלב אויבי המלך, ועמים שלמים נופלים תחת ממשלתך.",
  "45_7": "כסאך, מלך שנמשח מאת אלוהים, יעמוד לעולם ועד; שרביט מלכותך הוא שרביט של יושר וצדק.",
  "45_8": "אהבת צדק ושנאת רשע; על כן משח אותך אלוהים, אלוהיך, בשמן ששון ומלוכה יותר מכל חבריך המלכים.",
  "45_9": "בגדיך מבושמים בריחות מור, אהלות וקציעה מתוך ארמונות של שן, שבהם שימחו אותך בכלי נגינה.",
  "45_10": "בנות מלכים נמצאות בין נשות כבודך; המלכה ניצבת לימינך מקושטת בזהב מובחר מאופיר.",
  "45_11": "הקשיבי, בת (הכלה/האומה), ראי והטי את אוזנך: שכחי את עמך הישן ואת בית אביך הזר,",
  "45_12": "ואז יחפוץ המלך ביופייך ובמעלייך; ומכיוון שהוא אדונך ומלכך – השתחווי לו בכבוד.",
  "45_13": "ובת צור ואנשי עיר המסחר יבואו במנחה ובתשורות, ועשירי העם יחלו את פניך בבקשת קרבה.",
  "45_14": "כל כבודה והדרה של בת המלך פנימיים וצנועים, ולבושה עשוי אריגי זהב משובחים.",
  "45_15": "בבגדים רקומים תובל אל המלך; עלמות וחברות המלוות אותה יובאו אליך.",
  "45_16": "הן יובלו בשמחה גדולה ובגיל, וייכנסו אל תוך היכל המלך.",
  "45_17": "במקום אבותיך יהיו בניך וצאצאיך, ותמנה אותם לשרים ושליטים בכל הארץ.",
  "45_18": "אזכיר ואפרסם את שמך וכבודך בכל דור ודור; לכן עמים יודו לך וישבחו אותך לעולם ועד.",
  "46_1": "למנצח, לבני קורח, שיר בקולות עלמות (סופרן).",
  "46_2": "אלוהים הוא המחסה והמעוז שלנו, עזרה איתנה שנמצאת תמיד ומוכנה בעת צרה.",
  "46_3": "לכן לא נירא ולא נפחד גם אם הארץ כולה תרעש ותשתנה, וגם אם הרים יתמוטטו לתוך מעמקי הים;",
  "46_4": "גם אם מימיו יגעשו ויתכסו קצף, וגם אם הרים ירעדו מגאוותו וגליו של הים – לעולם לא נחרד.",
  "46_5": "הנה יש נהר שפלגיו המשקים מביאים שמחה לעיר אלוהים, משכנו הקדוש של האל העליון.",
  "46_6": "אלוהים שוכן בקרבה ולכן היא לא תתמוטט; אלוהים יעזור לה כבר עם פנות בוקר וזריחת השמש.",
  "46_7": "עמים רעשו וממלכות נזדעזעו; השמיע ה' את קולו – ומיד נמסה הארץ כולה מפניו.",
  "46_8": "ה' צבאות נמצא עמנו תמיד; מבצר ומחסה גבוה לנו אלוהי יעקב לנצח!",
  "46_9": "בואו וחזו במעשיו הגדולים של ה', אשר שם הרס ומפלות לאויבי הארץ.",
  "46_10": "הוא משבית ומפסיק מלחמות עד קצה תבל; הוא שובר קשת, קוצץ חניתות, ועגלות מלחמה הוא שורף באש.",
  "46_11": "ה' אומר: הרפו מריב ומדאגה, ודעו כי אנוכי אלוהים; אתרומם ואמלוך על העמים, אתרומם בכל הארץ!",
  "46_12": "ה' צבאות נמצא עמנו; מבצר מגן לנו אלוהי יעקב לעולמים!",
  "47_1": "למנצח, מזמור שבח שחיברו בני קורח.",
  "47_2": "כל העמים, מחאו כפיים בשמחה, והריעו לאלוהים בקול רינה ותרועה!",
  "47_3": "כי ה' עליון ונורא הוד, מלך גדול ושליט על כל הארץ.",
  "47_4": "הוא מכניע עמים תחתינו, ולאומים תחת רגלינו.",
  "47_5": "הוא בוחר למעננו את נחלתנו האהובה, את תפארת יעקב אשר אהב לתמיד.",
  "47_6": "עלה אלוהים בהתרוממות לקול תרועת ניצחון, ה' עלה לקול שופר.",
  "47_7": "זמרו ושבחו לאלוהים, זמרו! זמרו למלכנו, זמרו שיר הלל!",
  "47_8": "כי אלוהים הוא המלך על כל העולם כולו; זמרו לו שיר מוסר והשכל נשגב.",
  "47_9": "אלוהים מולך על כל העמים, אלוהים יושב על כסא קודשו הנשגב.",
  "47_10": "נדיבי העמים ומנהיגיהם נאספו יחד עם עמו של אלוהי אברהם, כי לאלוהים שייכים כל מגיני ושליטי הארץ – והוא מרומם ונעלה על הכל!",
  "48_1": "שיר ומזמור שחיברו בני קורח על ירושלים:",
  "48_2": "גדול ה' ומהולל מאוד בעיר אלוהינו, בהר קודשו המקודש.",
  "48_3": "יפה נוף ומקור שמחה לכל הארץ הוא הר ציון, הנמצא בירכתי צפון, עירו של המלך הגדול.",
  "48_4": "אלוהים נודע בארמונותיה כמשגב וכמבצר מגן בטוח.",
  "48_5": "כי הנה מלכי האויב התאספו והתחברו יחד, עברו בברית להילחם בה;",
  "48_6": "אך ברגע שהם ראו אותה – נדהמו והתמלאו פליאה, נבהלו ונמלטו בחרדה.",
  "48_7": "רעדה ופחד אחזו בהם במקומם, כמו כאבים וצירים של אישה יולדת.",
  "48_8": "ברוח קדים עזה אתה שובר ומרסק את אוניות תרשיש החזקות.",
  "48_9": "כפי ששמענו בסיפורי העבר – כן ראינו עתה במו עינינו בעיר ה' צבאות, בעיר אלוהינו; אלוהים יכונן וישמור עליה לעולם ועד!",
  "48_10": "הרהרנו וחשבנו על חסדך וטובך, אלוהים, בתוך היכל בית מקדשך.",
  "48_11": "כשמך הגדול, אלוהים, כך תהילתך ושבחך מגיעים עד קצוות תבל; יד ימינך מלאה בצדק וביושר.",
  "48_12": "ישמח הר ציון ותגלנה בנות ובנות ערי יהודה, בגלל משפטי הצדק שעשית להצלתם.",
  "48_13": "סבבו את ציון והקיפו אותה מסביב, ספרו את מגדליה המבוצרים;",
  "48_14": "התבוננו היטב בחומתה הבצורה והביטו בארמונותיה המפוארים, כדי שתוכלו לספר על כך לדורות הבאים:",
  "48_15": "כי זהו אלוהים, אלוהינו לעולם ועד; הוא ינהיג אותנו וידריך אותנו תמיד עד יום מותנו (ובכל הדורות)!",
  "49_1": "למנצח, מזמור השכל שחיברו בני קורח.",
  "49_2": "שמעו זאת כל העמים, האזינו היטב כל תושבי העולם החולף,",
  "49_3": "גם פשוטי עם וגם נכבדים, עשיר ועני כאחד.",
  "49_4": "פי ידבר דברי חוכמה, והרהורי לבי יבטאו תבונה והבנה עמוקה.",
  "49_5": "אטה את אוזני להבין משל עמוק, ואפתח ואסביר את חידתי בליווי כינור.",
  "49_6": "מדוע אפחד בימי רע וצרה, כאשר עוון עוקביי ואויביי המנסים להכשילני מקיף אותי?",
  "49_7": "אותם אנשים שבוטחים בעושרם ובכספם, וברוב רכושם הם מתפארים ומתהללים –",
  "49_8": "הרי שום איש אינו יכול לפדות בכספו את אחיו ממוות, ואינו יכול לתת לאלוהים כופר תמורת חייו;",
  "49_9": "יקר ונעלה מדי הוא פדיון נפשם של בני האדם, ודבר זה לא ייתכן לעולם בכסף,",
  "49_10": "כאילו יוכל אדם לחיות לנצח ולא לראות את הקבר והשחת!",
  "49_11": "הרי הכל רואים שגם חכמים מתים, וכסילים וטיפשים אובדים יחדיו, ומותירים את רכושם והונם לאחרים.",
  "49_12": "במחשבתם הפנימית הם מדמיינים שבתיהם יעמדו לנצח ומשכנותיהם לדור ודור, ואף קראו שמות קרקעות ונחלות על שמם.",
  "49_13": "אך אדם מכובד אינו נשאר לנצח בעולם הזה; הוא נמשל כבהמות שמתות וכלות.",
  "49_14": "זוהי דרכם של הכסילים שיש בה שטות, והדורות הבאים אחריהם עדיין נהנים מדבריהם ומחקים את מעשיהם.",
  "49_15": "כמו צאן הם מיועדים לשאול, והמוות רועה אותם; בבוקר הגאולה ירדו בהם הישרים, וצורתם תבלה ותכלה בקבר מבלי שמשכנם המפואר יישאר להם.",
  "49_16": "אך את נפשי אלוהים יפדה ויחלץ מיד השאול והמוות, כי הוא ייקח אותי אליו באהבה.",
  "49_17": "אל תפחד ואל תקנא כאשר איש נהיה עשיר, וכאשר כבוד והוד ביתו מתרבים;",
  "49_18": "כי במותו לא ייקח עמו מאומה מכל רכושו, וכבודו ועושרו לא ירדו עמו אל הקבר.",
  "49_19": "אף על פי שבחייו הוא בירך את עצמו ושיבח את נפשו, וגם אחרים שיבחו אותו כשהיטיב לעצמו –",
  "49_20": "סופו לבוא אל מקום אבותיו המתים, אשר לעולם לא יראו עוד את אור השמש.",
  "49_21": "אדם שחי בכבוד ובעושר אך אין לו תבונה ומוסר – נמשל כבהמות שמושמדות ואינן.",
  "50_1": "מזמור שחיבר אסף: אל אלוהים ה' דיבר, וקרא לכל תושבי הארץ ממזרח השמש ועד מקום שקיעתה במערב.",
  "50_2": "מציון, שהיא שיא היופי והשלמות, הופיע והתגלה אלוהים בהדרו.",
  "50_3": "אלוהינו יבוא להתגלות ולא יחריש עוד; אש אוכלת לוהטת לפניו, ורוח סערה חזקה נושבת מסביבו.",
  "50_4": "הוא קורא לשמיים ממעל ולארץ מתחת כדי לשפוט את עמו.",
  "50_5": "אספו אליי את חסידיי, את אלה שכרתו עמי ברית על קורבן ומחויבות.",
  "50_6": "והשמיים מספרים ומעידים על צדקתו, כי אלוהים עצמו הוא השופט.",
  "50_7": "שמע, עמי, ואדבר, ישראל – ואעיד בך: אלוהים, אלוהיך אנוכי!",
  "50_8": "לא על קורבנותיך אני מוכיח אותך, והרי עולותיך עומדות לנגדי תמיד.",
  "50_9": "אך אין לי שום צורך לקחת פר מביתך או תיישים ממכלאותיך;",
  "50_10": "כי לי שייכות כל חיות היער, ובהמות הפרוסות באלפי הרים.",
  "50_11": "אני מכיר את כל עופות ההרים, וכל חיות השדה גלויות וידועות לפניי.",
  "50_12": "אם הייתי רעב כביכול – לא הייתי צריך לומר זאת לך, שהרי תבל כולה וכל אשר בה שייכים לי!",
  "50_13": "האם אני אוכל בשר של שוורים או שותה דם של עתודים?!",
  "50_14": "הקרב לאלוהים תודה והכרת הטוב, ושלם לעליון את נדריך והבטחותיך;",
  "50_15": "וקרא אליי ביום צרה ומצוקה – אני אחלץ ואושיע אותך, ואתה תכבד אותי בהודיה.",
  "50_16": "ולאדם הרשע אמר אלוהים: מה פתאום אתה מדקלם ומספר את חוקיי, ונושא את בריתי על שפתיך?",
  "50_17": "והרי אתה שונא מוסר ותוכחה, ואת דבריי השלכת מאחורי גבך בזלזול!",
  "50_18": "אם ראית גנב – הסכמת עמו ושיתפת פעולה, ועם נואפים היה חלקך.",
  "50_19": "את פיך שילחת לדבר רע ולשון הרע, ולשונך מצרפת ורוקמת דברי מרמה.",
  "50_20": "אתה יושב ומדבר סרה באחיך, ועל בן אמך אתה מטיל דופי ועלילות שווא.",
  "50_21": "את המעשים האלה עשית ואני שתקתי והמתנתי, וחשבת בטעות שאהיה כמוך ואסכים עמך; כעת אוכיח אותך ואערוך את כל חטאיך לנגד עיניך!",
  "50_22": "הבינו זאת נא היטב, כל שוכחי אלוהים, פן אטרוף ואעניש ולא יהיה שום מציל!",
  "50_23": "מי שמקריב תודה מכבד אותי באמת, ומי שמתקן ומיישר את דרכו – אראה לו את ישועת אלוהים!",
  "51_1": "למנצח, מזמור תפילה שחיבר דוד,",
  "51_2": "כאשר בא אליו נתן הנביא להוכיחו אחרי מעשה בת שבע.",
  "51_3": "חמול עליי, אלוהים, כפי רוב חסדך; כפי גודל רחמיך מחק וסלח על פשעיי.",
  "51_4": "כבס וטהר אותי שוב ושוב מעווני, ומחטאתי נקה אותי כליל.",
  "51_5": "כי אני מכיר ומודה בפשעיי, וחטאתי עומדת לנגד עיניי תמיד בתחושת חרטה.",
  "51_6": "נגדך לבדך חטאתי ואת מה שרע בעיניך עשיתי; לכן אתה צודק בדיבורך ובתוכחתך, וזך ונקי במשפטך.",
  "51_7": "הנה נולדתי באנושיות שיש בה פגמים, וביצר נורא הרתה אותי אמי.",
  "51_8": "הנה אמת וכנות פנימית אהבת במעמקי האדם, ובחדרי הלב הנסתרים תלמדני חוכמה ומוסר.",
  "51_9": "חטא וטהר אותי באזוב כפי שמטהרים מצורע ואהיה טהור; כבס אותי ואהיה לבן וזך יותר משלג.",
  "51_10": "השמע לי בשורות של ששון ושמחה, ותגלנה העצמות ששברת בתוכחתך.",
  "51_11": "הסתר את פניך מחטאי ומעוונותיי, ומחק את כל פשעיי.",
  "51_12": "לב טהור ונקי ברא לי, אלוהים, ורוח פנימית נכונה ויציבה חדש בקרבי.",
  "51_13": "אל תשליך אותי מלפניך ומקרבתך, ואת רוח קודשך אל תיקח ממני לעולם!",
  "51_14": "השב לי את השמחה והששון של ישועתך, וברוח נדיבה וטובה תמוך בי וחזקני.",
  "51_15": "אז אלמד פושעים את דרכיך הטובות, וחוטאים ישובו אליך בתשובה.",
  "51_16": "הצל אותי מעוון דמים, אלוהים אלוהי ישועתי, ולשוני תרנן ותשבח בשמחה את צדקתך.",
  "51_17": "ה', פתח את שפתיי, ופי יספר וישמיע את תהילתך ושבחך.",
  "51_18": "כי אינך חפץ בקורבנות זבח סתמיים שאוכל לתת, וקורבן עולה אינו מרצה אותך ללא חרטת הלב.",
  "51_19": "קורבנותיו האמיתיים של אלוהים הם רוח נשברת וענווה; לב נשבר ונדכא מחרטה, אלוהים, לא תבזה לעולם.",
  "51_20": "היטב ברצונך ובחסדך את ציון, ובנה והשלם את חומות ירושלים.",
  "51_21": "אז תחפוץ בזבחי צדק, בעולה ובקורבן כליל; אז יעלו פרים לרצון על מזבחך.",
  "52_1": "למנצח, מזמור השכל שחיבר דוד,",
  "52_2": "כאשר בא דואג האדומי והלשין לשאול המלך: הנה דוד הגיע אל בית אחימלך הכהן בנוב.",
  "52_3": "מדוע אתה מתפאר ברשע ובמעשים רעים, איש גיבור ותקיף? הרי חסדו של אל קיים ומגן כל היום!",
  "52_4": "כוונות הרס ומזימות חושבת לשונך; כתער חד ומגולח היא פועלת בעורמה ותרמית.",
  "52_5": "אהבת את הרע יותר מאשר את הטוב, ואת השקר יותר מאשר לדבר דברי צדק ואמת.",
  "52_6": "אהבת כל מילות חורבן והרס, לשון רמייה שכמותך!",
  "52_7": "לכן גם האל ינתץ ויהרוס אותך לנצח; הוא יחטוף אותך ויעקור אותך מאוהלך ומביתך, ויעקור את שורשך מארץ החיים לעד.",
  "52_8": "הצדיקים יראו זאת וייראו מה', ועליו יצחקו וילעגו באמרם:",
  "52_9": "הנה האיש שלא שם את אלוהים למבצרו ולמעוזו, אלא בטח ברוב עושרו והתחזק ברשעותו והונו!",
  "52_10": "ואילו אני – רענן ושופע כעץ זית בבית אלוהים; בטחתי בחסד אלוהים לעולם ועד.",
  "52_11": "אודה לך לעולם על מה שעשית למעני, ואקווה ואייחל לשמך כי טוב הוא בנוכחות חסידיך ונאמניך.",
  "53_1": "למנצח על מחלת (כלי נגינה או נעימה של ייסורים), מזמור השכל לדוד.",
  "53_2": "אמר האדם הנבל והשפל בלבו: אין אלוהים; הם השחיתו את דרכם, עשו מעשי עוול מתועבים, ואין ביניהם איש שעושה טוב.",
  "53_3": "אלוהים השקיף מן השמיים על בני האדם, לראות האם יש ביניהם אדם משכיל וחכם הדורש את אלוהים.",
  "53_4": "כולם סטו אחורנית, כולם כאחד נשחתו ונתקלקלו; אין איש שעושה טוב, אין אפילו אחד.",
  "53_5": "האם לא יידעו ויבינו עושי העוול, שבולעים וגוזלים את עמי כאילו אכלו לחם, ואל אלוהים אינם קוראים ואינם מתפללים?",
  "53_6": "שם ייתקפו פחד נורא במקום שלא היה בו פחד רגיל, כי אלוהים פיזר וריסק את עצמות החונים עליך להילחם בך; הבשת אותם, כי אלוהים מאס בהם.",
  "53_7": "מי ייתן ותצא מציון הישועה הגדולה של עם ישראל! כאשר ישיב אלוהים את שבות עמו ויגאלם – ישמח יעקב ויצהל כל ישראל!",
  "54_1": "למנצח בנגינת כלי שיר, מזמור השכל לדוד,",
  "54_2": "כאשר באו אנשי זיף ואמרו לשאול: הנה דוד מסתתר בארצנו.",
  "54_3": "אלוהים, בשמך הגדול והנשגב הושע אותי, ובגבורתך ועוצמתך עשה לי משפט צדק.",
  "54_4": "אלוהים, שמע את תפילתי, והאזן לדברי פי.",
  "54_5": "כי אנשים זרים ועוינים קמו עליי, ועריצים אכזריים ביקשו ליטול את נפשי; הם לא שמו את יראת אלוהים לנגד עיניהם.",
  "54_6": "הנה אלוהים הוא העוזר והתומך בי; אדוני נמצא בין אלה שסומכים ומחזיקים את נפשי.",
  "54_7": "העוול והרע ישובו אל אויביי ואל האורבים לי; באמיתך ובנאמנותך השמד והכרת אותם.",
  "54_8": "בנדבה וברוחב לב אקריב לך קורבנות, ואודה לשמך, ה', כי טוב ומטיב הוא.",
  "54_9": "כי מכל צרה ומצוקה הצלת אותי, ובמפלת אויביי ראו עיניי את ישועתך.",
  "55_1": "למנצח בנגינת כלי שיר, מזמור השכל לדוד בעת מצוקה ובגידה פנימית.",
  "55_2": "האזן, אלוהים, לתפילתי, ואל תתעלם מתחנוניי ובקשתי.",
  "55_3": "הקשב אליי וענה לי; אני מתהלך אבל ומבוהל בשיחתי ובצערי, וסוער מכאב,",
  "55_4": "מקול איומי האויב, ומפני הלחץ וההצקה של הרשע; כי הם מפילים עליי עלילות שווא ועוול, ובכעס רב שונאים ומתנכלים לי.",
  "55_5": "לבי רועד וחרד בקרבי, ואימת מוות כבדה נפלה עליי.",
  "55_6": "פחד ורעדה באו בי, וחלחלה וחרדה גדולה כיסו אותי.",
  "55_7": "ואמרתי מתוך צערי: מי ייתן לי כנף כשל יונה, ואעוף הרחק מכאן ואשכון במקום שקט ובטוח!",
  "55_8": "הנה הייתי מרחיק לנדוד, והייתי לן ונח במדבר השקט.",
  "55_9": "הייתי ממהר למצוא לי מקום מקלט ומפלט מפני רוח סוערת ומפני סופת האויבים.",
  "55_10": "השמד, אדוני, ופלג את לשונם של אויביי בסכסוכים, כי ראיתי אלימות ומריבה שולטות בעיר.",
  "55_11": "יומם ולילה הם מסובבים אותה על חומותיה, ועוול ועמל מצויים בקרבה.",
  "55_12": "מזימות הרס ושחיתות שוכנות בתוכה, ומרחובותיה לא פוסקים עושק, מרמה ושקר.",
  "55_13": "כי לא אויב גלוי הוא שמחרף ומקלל אותי – שאז הייתי יכול לשאת זאת; ולא שונא מוצהר הוא שמתנשא עליי – שאז הייתי מסתתר מפניו;",
  "55_14": "אלא אתה – איש במעמדי, ידידי הקרוב, אלופי ואיש סודי!",
  "55_15": "אשר יחד היינו ממתיקים סוד ומדברים בקרבה, ובבית אלוהים היינו הולכים יחד בהתרגשות ובחברותא.",
  "55_16": "ייפול עליהם מוות פתאומי, שיירדו אל השאול בעודם חיים, כי מעשי רשע שוכנים במגוריהם ובקרבם.",
  "55_17": "ואילו אני – אל אלוהים אקרא, וה' יושיע ויציל אותי.",
  "55_18": "בערב, בבוקר ובצהריים אשוחח בתפילה ואהמה מצערי – והוא ישמע את קולי.",
  "55_19": "הוא פדה והציל בשלום את נפשי מן הקרב והמלחמה שנערכו נגדי, כי רבים היו הנלחמים עמדי (או רבים המלאכים שעמדו לצדי).",
  "55_20": "ישמע האל ויענה ויכניע אותם, הוא שיושב ומולך מקדמת עולם לנצח; שהרי הם אינם משתנים ואינם חוזרים בהם מדרכם הרעה, ואינם יראים מאלוהים.",
  "55_21": "הבוגד שלח את ידיו לפגוע באנשי שלומו שסמכו עליו, וחילל והפר את בריתו הנאמנה.",
  "55_22": "דברי פיו חלקלקים ומפתים כמו חמאה אך בתוך לבו יש מלחמה; דבריו רכים משמן ערב, אך בפועל הם חרבות שלופות וקטלניות.",
  "55_23": "השלך על ה' את כל משאך, דאגתך ויהבך – והוא יכלכל, יתמוך ויחזק אותך; לעולם לא ייתן לצדיק להתמוטט וליפול!",
  "55_24": "ואתה, אלוהים, תוריד את הרשעים אל בור שחת ואבדון; אנשי דמים, שקר ומרמה לא יגיעו אפילו למחצית ימי חייהם הרגילים, ואילו אני – בך אבטח תמיד!",
  "56_1": "למנצח, על נעימת שיר רחוקה (יונת אלם רחוקים), שיר יקר ומכתם לדוד כאשר תפסו אותו פלשתים בגת.",
  "56_2": "חמול עליי, אלוהים, כי אויב אנושי שואף לבלוע אותי; כל היום הלוחם בי לוחץ ומציק לי.",
  "56_3": "אויביי והאורבים לי שואפים לכלות אותי כל היום, כי רבים הם הנלחמים בי ביהירות ובגאווה.",
  "56_4": "ביום שבו יפקוד אותי פחד – אני בך אבטח!",
  "56_5": "באלוהים אהלל ואשבח את דברו והבטחתו; באלוהים בטחתי ולא אפחד – מה כבר יכול לעשות לי אדם בשר ודם?",
  "56_6": "כל היום הם מעוותים ומסלפים את דבריי, וכל מחשבותיהם מכוונות רק לרעתי.",
  "56_7": "הם מתאספים ואורבים בסתר, עוקבים אחרי כל פסיעותיי ועקביי, כאשר הם מקווים ליטול את נפשי.",
  "56_8": "האם יימלטו מן הדין על עוונם? בכעסך הצודק, אלוהים, הכרע והורד עמים רשעים!",
  "56_9": "את כל נדודי ובריחותיי ספרת וידעת; שים את דמעותיי בנאד השמירה שלך – הרי כולן רשומות בספר הזיכרון שלך!",
  "56_10": "אז ייסוגו אויביי לאחור ביום שבו אקרא אליך; זאת ידעתי בבירור – כי אלוהים נמצא עמדי!",
  "56_11": "באלוהים אהלל את דברו, בה' אשבח את הבטחתו.",
  "56_12": "באלוהים שמתי את מבטחי ולא אירא – מה כבר יכול לעשות לי אדם?",
  "56_13": "עליי מוטלים, אלוהים, הנדרים שהבטחתי לך; אשלם ואקריב קרבנות תודה ושבח לפניך,",
  "56_14": "כי הצלת את נפשי ממוות, והרי שמרת את רגליי מנפילה וממעידה, כדי שאתהלך לפני אלוהים באור החיים בעולם הזה.",
  "57_1": "למנצח, 'אל תשחת', מכתם שחיבר דוד כאשר ברח מפני שאול והסתתר במערה.",
  "57_2": "חמול עליי, אלוהים, חמול עליי, כי בך מצאה נפשי מחסה ומבטח; ובצל כנפיך הרחומות אמצא הגנה עד שיעברו האסונות והסכנות.",
  "57_3": "אקרא לאלוהים עליון, לאל הגומר ומשלים את טובו עליי.",
  "57_4": "הוא ישלח ישועה מן השמיים ויושיע אותי, ויחרף ויבייש את מי ששואף לבלוע אותי; אלוהים ישלח את חסדו ואת אמיתו.",
  "57_5": "נפשי שוכבת בתוך אנשים אכזריים כאריות, לוהטים מכעס; שיניהם פוצעות כחניתות וכחיצים, ולשונם חדה ופוצעת כחרב חדה.",
  "57_6": "התרומם מעל השמיים, אלוהים, ועל כל הארץ יתגלה כבודך!",
  "57_7": "רשת טמנו לצעדיי עד שנפשי שחה ונשברה; כרו וחפרו לפניי בור – אך הם עצמם נפלו לתוכו!",
  "57_8": "נכון ויציב הוא לבי, אלוהים, נכון ויציב לבי בביטחונו; אשיר ואנגן שירי תהילה.",
  "57_9": "התעוררי, נשמתי וכבודי! התעוררו, נבל וכינור! אעיר ואקדים את עלות השחר בשיריי.",
  "57_10": "אודה לך בין העמים, אדוני, ואזמר לך בין הלאומים.",
  "57_11": "כי חסדך ואהבתך גדולים ונשגבים עד השמיים, ונאמנותך מגיעה עד ענקי השחקים.",
  "57_12": "התרומם מעל השמיים, אלוהים, ועל כל פני הארץ יתפרסם כבודך!",
  "58_1": "למנצח, 'אל תשחת', שיר מוסר ומכתם שחיבר דוד כנגד שופטים מושחתים.",
  "58_2": "האם באמת שותקים אתם מלדבר צדק, שופטים? האם ביושר והגינות אתם שופטים את בני האדם?",
  "58_3": "אף להפך: בתוך לבבכם אתם מתכננים מעשי עוול, ובארץ אתם שוקלים ומחלקים חמס ועושק במעשי ידיכם!",
  "58_4": "הרשעים סרו מדרך הישר עוד מן הרחם; דוברי שקר תעו והושחתו עוד מבטן לידתם.",
  "58_5": "הארס שלהם מסוכן כמו ארס של נחש, וכמו פתן חירש שאוטם את אוזנו,",
  "58_6": "כדי שלא לשמוע את קולם של לוחשי הנחשים והמכשפים המיומנים.",
  "58_7": "אלוהים, שבור ורסק את שיניהם שבפיהם; נתץ את מלתעות כפירי האריות האכזריים, ה'!",
  "58_8": "יימסו וייעלמו כמים הזורמים ונבלעים במהירות; כאשר יכוון את חיציו – שייכרתו ויתקהו מיד.",
  "58_9": "שיהיו כמו שבלול הנמס והולך ברירו, וכנפל של אישה שלא זכה לראות את אור השמש.",
  "58_10": "בטרם יספיקו סירכם להרגיש את חום קוצי האטד הבוערים – יסער עליהם אלוהים בעודם חיים ורעננים.",
  "58_11": "ישמח הצדיק כאשר יראה את משפט הנקמה הצודק, וירחץ את רגליו בדם הרשעים המובסים.",
  "58_12": "ואז יאמר כל אדם: אכן יש פרי וגמול טוב לצדיק, אכן יש אלוהים שופט וצודק בארץ!",
  "59_1": "למנצח, 'אל תשחת', מכתם לדוד כאשר שאול שלח אנשים לשמור על ביתו כדי להמיתו.",
  "59_2": "הצל אותי מאויביי, אלוהיי, ומאלה שקמים עליי שמור אותי במבצר גבוה.",
  "59_3": "הצל אותי מעושי עוול ופשע, ומידי אנשים אלימים ששופכים דמים הושע אותי.",
  "59_4": "כי הנה הם אורבים לנפשי, אנשים עזים ותקיפים מתאספים נגדי – ללא שום פשע וללא שום חטא מצדי, ה'!",
  "59_5": "בלי שום עוול שעשיתי הם רצים ומתכוננים לתקוף; התעורר לקראתי, ראה והיווכח בצדקתי!",
  "59_6": "ואתה ה' אלוהי צבאות, אלוהי ישראל, הקץ לפקוד ולהעניש את כל העמים הרשעים; אל תחמול על שום בוגד ועושה פשע.",
  "59_7": "בערב הם שבים, נובחים ונוהמים כמו כלבים משוטטים, ומקיפים את העיר כדי ללכוד אותי.",
  "59_8": "הנה הם מתיזים ופולטים דברי ארס בפיהם, חרבות פוצעות מצויות על שפתותיהם, כי אומרים בלגלוג: מי שומע אותנו?",
  "59_9": "אך אתה, ה', תצחק ותלגלג עליהם; תלעג לכל העמים הרשעים.",
  "59_10": "מול כוחו ועוזו של האויב – אליך אייחל ואצפה, כי אלוהים הוא מבצרי ומעוזי הגבוה.",
  "59_11": "אלוהי חסדי יקדים את עזרתו אליי; אלוהים ייתן לי לראות במפלתם של אויביי האורבים לי.",
  "59_12": "אל תשמיד אותם במכה אחת פתאומית פן ישכח עמי את הלקח; טלטל ופזר אותם בכוחך והורד אותם, ה' מגיננו!",
  "59_13": "על חטאת פיהם ועל דברי שפתותיהם – שיילכדו בגאוותם שלהם, ובשל הקללות והשקרים שהם מספרים.",
  "59_14": "כלה אותם בכעסך הצודק, כלה אותם עד שלא יישארו; ויידעו כולם כי אלוהים מושל ביעקב ועד קצוות תבל!",
  "59_15": "ושישובו בערב, שינבחו וייהמו כמו כלבים ויסובבו מסביב לעיר בחוסר אונים.",
  "59_16": "הם ינועו ויחפשו אוכל לטרוף, ואם לא ישבעו – ילינו וילונו ברעבונם.",
  "59_17": "ואילו אני – אשיר שיר הלל לעוזך ולכוחך, וארנן עם שחר לחסדך; כי היית לי למבצר מגן ולמקלט ביום צרתי ומצוקתי.",
  "59_18": "מקור עוזי וכוחי, אליך אנגן שיר תהילה; כי אלוהים הוא מעוזי ומבצרי, אלוהי חסדי ואהבתי!",
  "60_1": "למנצח על שושן עדות, מכתם שחיבר דוד ללמד ולהדריך,",
  "60_2": "כאשר נלחם בארם נהריים ובארם צובא, ויואב בן צרויה שב והכה את אדום בגיא מלח – שנים עשר אלף איש.",
  "60_3": "אלוהים, נטשת אותנו ופרצת פרצות במחננו, כעסת עלינו – אנא שוב והחזר אותנו אליך!",
  "60_4": "הרעדת את הארץ וביקעת אותה בסדקים; רפא את שבריה המתמוטטים, כי היא רועדת.",
  "60_5": "הראית לעמך קשיים וצרות קשות; השקית אותנו כוס ייסורים מבלבלת כיין תרעלה.",
  "60_6": "אך נתת ליראיך נס ודגל להתרומם ולהתנופף, למען הוכחת האמת והצדק.",
  "60_7": "כדי שייחלצו וייוושעו אהוביך וידידיך – הושע בימינך החזקה וענה לי!",
  "60_8": "אלוהים דיבר בהיכל קודשו בהבטחה גדולה: אשמח ואחלק את שכם, ואת עמק סוכות אמדוד לחלוקה.",
  "60_9": "שלי הוא הגלעד ושלי מנשה, ואפרים הוא מעוז ראשי ומבצרי, ויהודה הוא מקור המחוקקים ומנהיגיי.",
  "60_10": "מואב יהיה כסיר רחצה לשירותי, על אדום אשליך את מנעולי לסמל בעלות, ועל פלשת אריע בקול ניצחון!",
  "60_11": "מי יוביל אותי ויכניסני אל עיר מבצר בצורה? מי ינחני לכבוש את אדום?",
  "60_12": "האם לא אתה, אלוהים, אשר נטשת אותנו בעבר, ולא יצאת עם צבאותינו לקרב?",
  "60_13": "הענק לנו עזרה והצלה מן האויב והצר, שהרי ישועת אדם בשר ודם היא הבל ושווא!",
  "60_14": "באלוהים נעשה חיל וגבורה, והוא זה שירמוס ויכניע את צרינו ואויבינו!",
  "61_1": "למנצח על נגינת כלי שיר, מזמור שחיבר דוד.",
  "61_2": "שמע, אלוהים, את זעקתי ותחינתי; הקשב לתפילתי.",
  "61_3": "מקצה הארץ אקרא אליך בעת שלבי עטוף ביגון ובחולשה; על צור ומבצר שגבוה ממני תנחני ותעלני להגנה.",
  "61_4": "כי היית לי למחסה ומקלט בטוח, למגדל עוז מבוצר מפני האויב.",
  "61_5": "אשכון באוהלך ובמשכנך לעולמים, אמצא מחסה והגנה בסתר כנפיך הרחומות.",
  "61_6": "כי אתה, אלוהים, שמעת את נדריי והבטחותיי, ונתת לי את נחלתם של יראי שמך.",
  "61_7": "ימים ושנים רבות תוסיף על ימי חייו של המלך; שנותיו יהיו לדור ודור.",
  "61_8": "יישב וימלוך לעולם לפני אלוהים; צווה שחסד ואמת ישמרו ויגנו עליו תמיד.",
  "61_9": "כך אזמר ואשבח את שמך לעולם ועד, כדי שאשלם את נדריי מדי יום ביומו.",
  "62_1": "למנצח, על ידי ידותון המשורר, מזמור ביטחון שחיבר דוד.",
  "62_2": "אך ורק אל אלוהים נפשי ממתינה בדממה ובשלווה; ממנו מגיעה כל ישועתי.",
  "62_3": "רק הוא סלעי, מבצרי וישועתי; הוא מעוזי הגבוה ולכן לא אתמוטט ולא אמעד רבות.",
  "62_4": "עד מתי תתנכלו ותתנפלו כולם על איש אחד לרוצחו ולהפילו, כאילו היה קיר נטוי או גדר רעועה שדוחפים אותה?",
  "62_5": "אך ורק להפיל אותו מגדולתו וממעמדו הם מתייעצים; הם רוצים שקר – בפיהם הם מברכים ומחמיאים, אך בקרבם הם מקללים.",
  "62_6": "אך ורק לאלוהים דומי והמתיני בשלווה, נפשי, כי ממנו נובעת תקוותי ותוחלתי.",
  "62_7": "רק הוא סלעי וישועתי, מעוזי הגבוה ולכן לא אמעד לעולם.",
  "62_8": "על אלוהים נשענים ישועתי וכבודי; צור כוחי ומחסי הבטוח נמצאים באלוהים.",
  "62_9": "בטחו בו בכל עת, בני העם! שפכו לפניו בתפילה את כל מעמקי לבבכם; אלוהים הוא מחסה ומקלט לנו לנצח!",
  "62_10": "אך ורק הבל הם בני אדם פשוטים, וכזב חולף הם אנשים רמי מעלה; במאזני צדק אם יעלו – כולם יחד קלים מהבל חסר ערך.",
  "62_11": "אל תבטחו בעושק ובגזל ואל תתלו תקוות שווא בשלל; גם אם עושר והון יתרבו – אל תשימו עליהם את לבבכם ומבטחכם.",
  "62_12": "אחת דיבר אלוהים, ושתיים אלה שמעתי והבנתי: כי הכוח והעוז שייכים אך ורק לאלוהים,",
  "62_13": "וכי לך, אדוני, שייך החסד האמיתי; כי אתה הוא שמשלם וגומל לכל איש כפי מעשיו!",
  "63_1": "מזמור של געגועים שחיבר דוד בהיותו במדבר יהודה:",
  "63_2": "אלוהים, אתה אלוהיי, אותך אני מחפש ומשחר עם בוקר; צמאה לך נפשי, וכלה אליך בשרי, בארץ ציה ויבשה שאין בה מים,",
  "63_3": "כמו הגעגועים שבהם חזיתי בך במקום המקדש, לראות את עוזך ותפארת כבודך.",
  "63_4": "כי חסדך ואהבתך טובים ויקרים יותר מן החיים עצמם; שפתיי יהללו וישבחו אותך תמיד.",
  "63_5": "כך אברך אותך בכל ימי חיי, ובשמך אשא את כפיי בתפילה.",
  "63_6": "כמו משומן ומדשן מובחר תשבע ותרגיש סיפוק נפשי, ובשפתי רינה ושמחה יהלל אותך פי,",
  "63_7": "כאשר אזכור אותך על משכבי בלילה, ובמשמרות הלילה אהרהר בך.",
  "63_8": "כי היית לי לעזרה ולתמיכה, ובצל כנפיך ארנן ואשיר בשמחה.",
  "63_9": "נפשי דבקה בך באהבה עמוקה, וימינך החזקה תומכת בי.",
  "63_10": "ואילו אלה המבקשים להשמיד את נפשי לרעה – יבואו ויירדו אל מעמקי תחתיות הארץ והקבר.",
  "63_11": "יסגירו אותם ללהב החרב, והם יהיו למאכל שועלים ותנים במדבר.",
  "63_12": "ואילו המלך ישמח באלוהים, ויתפאר כל מי שנשבע בשמו באמת; כי ייסכר ויושתק פיהם של דוברי השקר והכזב.",
  "64_1": "למנצח, מזמור תפילה שחיבר דוד.",
  "64_2": "שמע, אלוהים, את קולי בעת שיחתי ותחינתי; מפחד האויב נצור ושמור את חיי.",
  "64_3": "הסתר והגן עליי מסוד וממזימת אנשים רעים, ומהתקהלות רועשת של עושי עוול,",
  "64_4": "אשר שננו והשחיזו את לשונם כחרב חדה, וכיוונו את חיצם המר – דברי רכילות והשמצה,",
  "64_5": "כדי לירות במחבוא ובסתר באדם תמים ונקי; לפתע יורו בו מבלי לירא ומבלי לפחד.",
  "64_6": "הם מחזקים את עצמם בעניין רע, מתכננים ומספרים כיצד לטמון מלכודות, ואומרים בשחצנות: מי יראה אותנו?",
  "64_7": "הם חוקרים ומחפשים עלילות שווא, ואומרים: תמנו תוכנית חכמה ומוסתרת; וכל זאת מתוך מעמקי לבו ומחשבותיו הנסתרות של האיש.",
  "64_8": "אך אלוהים יירה בהם חץ פתאומי, ומכותיהם ומפלתם יבואו עליהם לפתע.",
  "64_9": "הם יכשילו את עצמם כאשר לשונם תפנה נגדם; כל הרואים אותם ינודו בראשם בתימהון ובלעג.",
  "64_10": "וייראו כל בני האדם, ויספרו בהתפעלות על מעשה אלוהים, ואת פועלו יבינו וישכילו.",
  "64_11": "ישמח הצדיק בה' וימצא בו מחסה ומבטח, ויתהללו כל האנשים הישרים בלבבם!",
  "65_1": "למנצח, מזמור שיר שחיבר דוד על שפע הארץ ותפילת האדם:",
  "65_2": "לך, אלוהים, נאה ונכונה שתיקת הודיה מלאת יראת כבוד בציון, ולך ישולם כל נדר והבטחה.",
  "65_3": "אתה שומע תפילה; אליך כל בני האדם ובשר ודם יבואו להתפלל.",
  "65_4": "דברי עוונות וחטאים גברו והכבידו עליי; אך את פשעינו – אתה תכפר, תמחל ותטהר.",
  "65_5": "אשרי ומאושר האדם שבו תבחר ותקרב אותו כדי שישכון בחצרותיך; נשבע ונתענג מטוב ביתך, מקדושת היכלך.",
  "65_6": "במעשים נוראי הוד ובצדק תענה לנו, אלוהי ישועתנו; אתה מבטחם ותקוותם של כל קצוות הארץ ושל הימים הרחוקים.",
  "65_7": "הוא המכין ומייצב הרים איתנים בכוחו הגדול, בהיותו חגור בגבורה ובעוצמה.",
  "65_8": "הוא המשקיט והמרגיע את שאון הימים הסוערים, את שאון גליהם, ואת המולת העמים והלאומים.",
  "65_9": "וייראו יושבי קצוות הארץ מאותותיך ומנפלאותיך; את מבואות הבוקר (המזרח) והערב (המערב) תרנין ותשמח.",
  "65_10": "פקדת והשגחת על הארץ והשקית אותה בשפע, העשרת אותה מאוד בפלג אלוהים המלא מים; תכין להם דגן ותבואה, כי כך הכנת וכוננת את האדמה.",
  "65_11": "את תלמיה החרושים אתה מרווה במים, משקיע ומיישר את רגביה; ברסיסי גשמים תרכך אותה, ואת צמחייתה תברך.",
  "65_12": "עיטרת והכתרת את שנת היבול בטובך וברכתך, ונתיבי ענניך מרעיפים שומן ושפע רב.",
  "65_13": "ירעפו גשמי ברכה על נאות המדבר הירוקות, וגבעות הארץ נחגרות בשמחה.",
  "65_14": "שדות המרעה התכסו בצאן רב, והעמקים עטופים בבר ובתבואה; כולם מריעים ושרים משמחה!",
  "66_1": "למנצח, שיר ומזמור הודיה לאלוהים: הריעו בשמחה לאלוהים, כל תושבי הארץ!",
  "66_2": "זמרו ושבחו את כבוד שמו הגדול; תנו לו כבוד בתהילתכם.",
  "66_3": "אמרו לאלוהים: כמה נוראים ונשגבים הם מעשיך! מרוב עוצמתך יתכחשו ויחניפו לך אויביך מרוב פחד.",
  "66_4": "כל הארץ ישתחוו לך ויזמרו לשמך; יזמרו שיר תהילה לשמך לנצח.",
  "66_5": "לכו וראו את מפעלי אלוהים ונפלאותיו; נורא ועצום הוא במעשיו כלפי בני האדם.",
  "66_6": "הוא הפך את ים סוף ליבשה, ובתוך הנהר עברו אבותינו ברגל יבשה; שם שמחנו בו ובחסדו הגדול.",
  "66_7": "הוא מושל בגבורתו לעולם; עיניו צופות ומשגיחות על כל העמים, והמורדים לא יוכלו להתנשא עליו.",
  "66_8": "ברכו, עמים, את אלוהינו, והשמיעו ברמה את קול תהילתו,",
  "66_9": "הוא ששם ושומר את נפשנו בחיים, ולא הניח לרגלנו למעוד וליפול.",
  "66_10": "כי בחנת וניסית אותנו, אלוהים; צרפת וטיהרת אותנו מייסורים כפי שצורפים ומזקקים כסף.",
  "66_11": "הבאת אותנו לתוך מלכודת ומצור, ושמת מועקה ומשא כבד על מותנינו.",
  "66_12": "נתת לאנשים לרכוב על ראשנו ולשלוט בנו, באנו באש ובמים ובסכנות איומות – אך בסוף הוצאת אותנו למקום רוויה, שפע והרחבה!",
  "66_13": "אבוא לביתך בעולות ובקורבנות, אשלם לך את כל נדריי והבטחותיי,",
  "66_14": "אשר פצו ונדרו שפתיי, ואשר דיבר פי בעת צרתי ומצוקתי.",
  "66_15": "עולות שמנות ומובחרות אעלה לך יחד עם קטורת אילים; אקריב בקר יחד עם עתודים.",
  "66_16": "לכו, שמעו ואספרה, כל יראי אלוהים, את מה שעשה לטובת נפשי!",
  "66_17": "אליו קראתי בפי, ותהילה ושבח היו תחת לשוני.",
  "66_18": "אילו ראיתי וחשבתי עוול ורשע בלבי – ה' לא היה שומע ומקבל את תפילתי.",
  "66_19": "אך אכן שמע אלוהים, הקשיב והאזין לקול תפילתי ותחנוניי.",
  "66_20": "ברוך ומשובח אלוהים, שלא דחה את תפילתי, ולא הסיר את חסדו ואהבתו ממני!",
  "67_1": "למנצח בנגינות, מזמור שיר בצורת המנורה:",
  "67_2": "אלוהים יחון אותנו ויברך אותנו, יאיר את פניו והשגחתו עמנו תמיד;",
  "67_3": "כדי שתוודע ותתפרסם בארץ דרכך הטובה, ובכל העמים ישועתך והצלתך.",
  "67_4": "יודו וישבחו אותך עמים כולם, אלוהים; יודו לך עמים כולם יחדיו!",
  "67_5": "ישמחו וירננו לאומים, כי תשפוט עמים בצדק וביושר, ולאומים בארץ תנהיג ותדריך.",
  "67_6": "יודו לך עמים, אלוהים; יודו לך עמים כולם!",
  "67_7": "הארץ נתנה את יבולה ואת פריה בשפע; יברך אותנו אלוהים, אלוהינו!",
  "67_8": "יברך אותנו אלוהים, וייראו ויכבדו אותו כל קצוות הארץ!",
  "68_1": "למנצח, שיר ומזמור ניצחון והודיה שחיבר דוד:",
  "68_2": "יקום אלוהים ויתפזרו אויביו, וינוסו שונאיו מפני נוכחותו!",
  "68_3": "כפי שרוח מניסה ומפזרת עשן – כך תנדף אותם; כפי שדונג נמס מפני האש – כך יאבדו הרשעים מפני אלוהים.",
  "68_4": "ואילו הצדיקים ישמחו ויצהלו לפני אלוהים, וישישו בשמחה גדולה.",
  "68_5": "שירו לאלוהים, זמרו לשמו; סללו דרך למי שרוכב בערבות ובשחקים בשמו 'י-ה', ועלזו לפניו!",
  "68_6": "אבי היתומים ודיין האלמנות הוא אלוהים במעון קודשו.",
  "68_7": "אלוהים מושיב אנשים בודדים ועריריים בבית ומשפחה, מוציא אסירים כבולים אל חירות ושלווה; אך המורדים והסוררים שוכנים בארץ צחיחה.",
  "68_8": "אלוהים, בצאתך לפני עמך במדבר, בצעדך בישימון השמם;",
  "68_9": "הארץ רעדה וגם השמיים נטפו מים מפני אלוהים; הר סיני זה רעד מפני אלוהים, אלוהי ישראל.",
  "68_10": "גשם של נדבות וברכות הרעפת, אלוהים; כאשר נחלתך הייתה עייפה וצמאה – אתה חיזקת וכוננת אותה.",
  "68_11": "עדת עמך ישבה בה; בטובך הכנת ודאגת לעני, אלוהים.",
  "68_12": "ה' נותן את אמירתו ובשורת הניצחון; המבשרות והשרות הן צבא וקהל רב.",
  "68_13": "מלכי צבאות ינוסו ויברחו בבהלה, והאישה היושבת בבית תחלק את השלל הרב.",
  "68_14": "גם אם שכבתם בין משפתיים וגדרות צאן במנוחה – הנה אתם זוהרים ככנפי יונה המצופות כסף, ואברותיה בזהב ירקרק ונוצץ.",
  "68_15": "כאשר פיזר שדי מלכים בה – הלבינה הארץ מניצחון כמו שלג הצח על הר צלמון.",
  "68_16": "הר אלוהים הוא הר הבשן, הר של גבעות רמות וגבוהות הוא הר הבשן.",
  "68_17": "למה אתם מקפצים ומקנאים, הרים גבנוניים ורמים, בהר שחמד אלוהים לשבתו בו? הרי ה' ישכון בהר ציון לנצח!",
  "68_18": "מרכבות אלוהים הן רבבות, אלפי שנאן ומלאכים; אדוני שוכן בם, כפי שהיה בסיני בקודש.",
  "68_19": "עלית למרום ושבית שבי, לקחת מתנות כדי לחלקן לבני אדם, ואף סוררים ומורדים שבו כדי שישכון בקרבם י-ה אלוהים.",
  "68_20": "ברוך אדוני יום יום, אשר מעמיס עלינו שפע וברכה; האל הוא ישועתנו לנצח!",
  "68_21": "האל הוא לנו אל של ישועות והצלות, ולה' אלוהים שייכים המוצאים וההצלות מן המוות.",
  "68_22": "אך אלוהים ימחץ וירסק את ראש אויביו, את קודקוד שערם של המתהלכים באשמותיהם.",
  "68_23": "אמר אדוני: אפילו מהרי הבשן אשיב את האויבים הנמלטים, אשיב אותם אפילו ממעמקי הים,",
  "68_24": "כדי שתרחץ רגלך בדם האויבים המובסים, ולשון כלביך תלחך ממנו את חלקה.",
  "68_25": "ראו העמים את תהלוכותיך, אלוהים; את תהלוכות מלכי ואלוהיי בקודש.",
  "68_26": "הקדימו המשוררים, אחריהם המנגנים בכלי שיר, ובתוכם עלמות המתופפות בתופים.",
  "68_27": "במקהלות עם רב ברכו את אלוהים; ברכו את ה', כל יוצאי מקור ישראל!",
  "68_28": "שם בנימין הצעיר רודה ושולט בהם, שרי יהודה ורגמתם המכובדת, שרי זבולון ושרי נפתלי.",
  "68_29": "ציווה אלוהיך את עוזך וכוחך; חזק, אלוהים, את מה שפעלת ועשית למעננו!",
  "68_30": "מהיכלך שבירושלים – יביאו לך מלכים מנחות ושי של כבוד.",
  "68_31": "געור בחיית הקנים (מצרים/מעצמות רשע), בעדת פרים ועגלי עמים, שמתרפסים ומביאים מטילי כסף; פזר עמים החפצים במלחמות!",
  "68_32": "יבואו שרים ונכבדים ממצרים, וארץ כוש תמהר להרים ולהושיט את ידיה בתפילה לאלוהים.",
  "68_33": "ממלכות הארץ, שירו לאלוהים, זמרו שיר תהילה לאדוני!",
  "68_34": "למי שרוכב בשמי שמי קדם הנצחיים; הנה הוא משמיע בקולו קול עוז וגבורה.",
  "68_35": "תנו והכירו בעוז ובכוח של אלוהים; על ישראל שרויה גאוותו ותפארתו, ועוזו מתגלה בשחקים.",
  "68_36": "נורא ואדיר אתה, אלוהים, מתוך מקדשיך; אל ישראל הוא הנותן עוז ותעצומות לעמו – ברוך אלוהים!",
  "69_1": "למנצח על שושנים, מזמור תפילה שחיבר דוד בעת מצוקה גדולה.",
  "69_2": "הושיעני, אלוהים, כי מי הצרות והסכנות הגיעו עד נפשי ואיימו להטביעני!",
  "69_3": "טבעתי בטיט עמוק וטובעני ואין שום מעמד ומקום יציב לעמוד; באתי למעמקי מים וזרם שיטפון שטף אותי.",
  "69_4": "יגעתי ונלאיתי מזעקתי, גרוני ניחר וצמא, עיניי כהו מרוב ציפייה וייחול לאלוהיי.",
  "69_5": "רבו משערות ראשי האנשים ששונאים אותי חינם ללא סיבה; עצמו והתחזקו אויביי השקרנים המבקשים להשמידני; מה שלא גזלתי מעולם – נאלצתי להשיב להם!",
  "69_6": "אלוהים, אתה יודע את שגיאותיי ואיוולתי, ואשמותיי אינן נסתרות ממך.",
  "69_7": "אל יתביישו בגללי המקווים לך, ה' אלוהי צבאות; אל ייכלמו בגללי מבקשי פניך, אלוהי ישראל!",
  "69_8": "כי למענך ולכבודך נשאתי חרפה וגידופים, ובושה וחרפה כיסו את פניי.",
  "69_9": "הפכתי לזר ומנוכר לאחיי, ולאדם לא מוכר לבני אמי.",
  "69_10": "כי קנאת כבוד ביתך אכלה ושרפה אותי, וחרפות מחרפיך נפלו עליי.",
  "69_11": "ובכיתי בצום ובעינוי נפשי – וזה עצמו נהפך לי לחרפות וללעג בפיהם.",
  "69_12": "ולבשתי בגד שק של אבל – והייתי להם למשל ולשנינה.",
  "69_13": "יושבי השער מדברים ומלגלגים עליי, ושירי שותי השיכר נסובים עליי.",
  "69_14": "ואילו אני – תפילתי מופנית אליך, ה', בעת רצון; אלוהים, ברוב חסדך ענה לי באמיתת ישועתך!",
  "69_15": "הצל אותי מן הטיט ואל אטבע; אינצל משונאיי וממעמקי מי הצרות.",
  "69_16": "אל ישטפני זרם מים, ואל תבלעני המצולה, ואל יסגור הבור את פיו עליי.",
  "69_17": "ענה לי, ה', כי טוב ורחום חסדך; כפי רוב רחמיך פנה אליי בחמלה.",
  "69_18": "ואל תסתיר את פניך מעבדך, כי צר לי מאוד – מהר וענה לי!",
  "69_19": "קרב אל נפשי וגאל אותה; בגלל אויביי המאיימים פדה והצל אותי.",
  "69_20": "אתה ידעת את חרפתי, בושתי וכלימתי; לנגד עיניך עומדים כל צריי ומבקשי רעתי.",
  "69_21": "החרפה שברה את לבי וחליתי מרוב צער; קיוויתי למישהו שינוד ויחמול עליי אך לא היה איש, ולמנחמים – ולא מצאתי.",
  "69_22": "ונתנו במאכלי ראש ולענה, וכאשר צמאתי השקו אותי חומץ.",
  "69_23": "יהי שולחנם ועושרם שלפניהם למלכודת ולפח, ושלומם וביטחונם למוקש המכשיל אותם.",
  "69_24": "תחשכנה עיניהם מראות, ומותניהם ירעדו תמיד בחולשה.",
  "69_25": "שפוך עליהם את זעמך, וחרון אפך וכעסך ישיגו אותם.",
  "69_26": "יהי ארמונם ומחנם שמם, ובאוהליהם לא יהיה שום יושב.",
  "69_27": "כי את מי שאתה הכית וייסרת – הם הוסיפו לרדוף, ועל מכאובי פצועיך הם מדברים בלעג.",
  "69_28": "תן והוסף עונש על עוונם, ואל יזכו לבוא בצדקתך ובסליחתך.",
  "69_29": "יימחקו מספר החיים, ועם הצדיקים אל ייכתבו לטובה.",
  "69_30": "ואילו אני – עני, כואב ומיוסר; ישועתך והצלתך, אלוהים, תרומם ותשמור אותי במבצר גבוה.",
  "69_31": "אהלל ואשבח את שם אלוהים בשיר, ואגדל וארומם אותו בהודיה.",
  "69_32": "ודבר זה ייטב וירצה לה' יותר משור ומפר בעל קרניים ומפריס פרסה.",
  "69_33": "יראו זאת הענווים והסובלים וישמחו; דורשי אלוהים – יחיה ויתמלא שמחה לבבכם!",
  "69_34": "כי ה' שומע ומאזין לאביונים, ואת אסיריו ועמו הנתון במצוקה אינו מבזה.",
  "69_35": "יהללו וישבחו אותו שמיים וארץ, הימים וכל היצורים הרוחשים בהם.",
  "69_36": "כי אלוהים יושיע את ציון ויבנה מחדש את ערי יהודה, והם יישבו שם ויירשו אותה.",
  "69_37": "וזרע עבדיו וצאצאיהם יירשו אותה לנצח, ואוהבי שמו ישכנו בתוכה בשלווה ובביטחון.",
  "70_1": "למנצח, מזמור תפילה לדוד להזכיר ולהעלות את זכרונו לפני ה'.",
  "70_2": "אלוהים, מהר להציל אותי; ה', מהר לעזרתי!",
  "70_3": "יתביישו וייכלמו כל המבקשים את נפשי להמיתה; ייסוגו לאחור ויתביישו כל החפצים ברעתי.",
  "70_4": "ישובו וייסוגו בגלל בושתם וחרפתם, אותם אנשים האומרים עליי בלעג: האח, האח!",
  "70_5": "ישישו וישמחו בך כל מבקשי קרבתך, ויאמרו תמיד: יתגדל אלוהים, כל האוהבים את ישועתך!",
  "70_6": "ואילו אני עני ואביון – אלוהים, מהר אליי לעזרה! עזרתי ומחלץ נפשי אתה, ה', אל תתעכב!",
  "71_1": "בך, ה', שמתי את כל מבטחי; אל אבוש ואל אתאכזב לעולם.",
  "71_2": "בצדקתך תציל ותחלץ אותי; הטה אליי את אוזנך והושע אותי.",
  "71_3": "היה לי לצור מעוז ולבית מבצר לבוא אליו תמיד; ציווית להושיע אותי, כי סלעי ומצודתי הבטוחה אתה.",
  "71_4": "אלוהיי, חלץ אותי מיד הרשע, מכף איש מעוול וחומס.",
  "71_5": "כי אתה הוא תקוותי, אדוני ה'; בך בטחתי עוד מנעוריי.",
  "71_6": "עליך נסמכתי עוד מן הבטן, וממעי אמי אתה הוא שהוצאת אותי; בך תהילתי ושבחי תמיד.",
  "71_7": "כמו פלא ומופת של ייסורים הייתי לרבים, אך אתה היית מחסי ומבצרי החזק.",
  "71_8": "יימלא פי תהילתך ושבחך, וכל היום אספר את תפארתך.",
  "71_9": "אל תשליכני לעת זקנה; כאשר כוחי כלה ונחלש – אל תעזוב אותי!",
  "71_10": "כי אויביי דיברו עליי רעות, ושומרי נפשי והאורבים לי נועצו יחדיו,",
  "71_11": "באמרם: אלוהים עזב אותו! רדפו ותפסו אותו כי אין לו שום מציל!",
  "71_12": "אלוהים, אל תתרחק ממני; אלוהיי, מהר לעזרתי!",
  "71_13": "ייבושו ויכלו שונאי נפשי; ייעטפו בחרפה ובכלימה כל המבקשים את רעתי.",
  "71_14": "ואילו אני – תמיד אייחל ואקווה, ואוסיף להודות על כל תהילתך.",
  "71_15": "פי יספר את צדקתך, וכל היום את ישועתך, כי אין מספר לחסדיך ואינני יודע לספור את כולם.",
  "71_16": "אבוא לספר בגבורותיו של אדוני ה'; אזכיר את צדקתך שלך לבדך.",
  "71_17": "אלוהים, לימדת והדרכת אותי מנעוריי, ועד היום הזה אני מספר את נפלאותיך.",
  "71_18": "וגם עד זקנה ושיבה, אלוהים, אל תעזוב אותי, עד שאספר על כוח זרועך לדור הזה, ולכל מי שיבוא בעתיד – על גבורתך.",
  "71_19": "וצדקתך, אלוהים, מגיעה עד מרומי שמיים, אשר עשית מעשים גדולים; אלוהים, מי כמוך!",
  "71_20": "אשר הראית אותנו צרות רבות ורעות – תשוב ותחיה אותי, וממעמקי תהומות הארץ תשוב ותעלה אותי.",
  "71_21": "תרבה את גדולתי ומעמדי, ותסובב אותי ותנחמני.",
  "71_22": "גם אני אודה לך בכלי נבל על אמיתך, אלוהיי; אזמר לך בכינור, קדוש ישראל!",
  "71_23": "תרננה ותרקודנה שפתיי כאשר אזמר לך, וכן נפשי אשר פדית והצלת מכל צרה.",
  "71_24": "גם לשוני תהגה ותספר כל היום על צדקתך, כי התביישו וכי נכלמו כל המבקשים את רעתי.",
  "72_1": "מזמור של תפילה שחיבר דוד למען שלמה בנו (ולמלך המשיח): אלוהים, תן למלך את משפטיך והנהגתך הצודקת, ואת צדקתך תן לבן המלך.",
  "72_2": "הוא ישפוט את עמך בצדק, ואת ענייך ומסכניך במשפט ישר.",
  "72_3": "ההרים יישאו ויביאו שלום וברכה לעם, והגבעות יתמלאו צדקה ושגשוג.",
  "72_4": "הוא יעשה משפט צדק לעניי העם, יושיע את בני האביונים, וישבור ויכניע את העושק והרודן.",
  "72_5": "ייראו ויכבדו אותך כל עוד השמש מאירה, ולפני הירח – מדור לדורות עולמים.",
  "72_6": "ברכתו תרד בעדינות כמו מטר על עשב גזוז, וכמו רביבי גשם המרטיבים ומרווים את הארץ.",
  "72_7": "בימיו יפרח וישגשג הצדיק, ויהיה שפע של שלום עד שלא יישאר עוד ירח (לנצח).",
  "72_8": "והוא ימשול וישלוט מים עד ים, ומנהר פרת ועד קצוות תבל.",
  "72_9": "לפניו יכרעו שוכני המדבריות והאיים, ואויביו ילחכו עפר בכניעה.",
  "72_10": "מלכי תרשיש והאיים הרחוקים יביאו מנחה ותשורות; מלכי שבא וסבא יגישו מתנות של כבוד.",
  "72_11": "וישתחוו לו כל המלכים, וכל העמים יעבדו ויכבדו אותו.",
  "72_12": "כי הוא יציל אביון שזועק לעזרה, ועני שאין לו שום תומך ועוזר.",
  "72_13": "הוא יחוס ויחמול על הדל והאביון, ואת נפשות האביונים יושיע.",
  "72_14": "מעושק ומאלימות יגאל ויפדה את נפשם, ודמם יהיה יקר וחשוב בעיניו.",
  "72_15": "והוא יחיה ויאריך ימים, וייתנו לו מזהב שבא המשובח; ויתפללו בעדו תמיד, וכל היום יברכו אותו.",
  "72_16": "יהיה שפע רב של תבואה בארץ אפילו בראשי ההרים, יבולה ירעש וייראה מפואר כיערות הלבנון, ואנשי הערים יפרחו ויתרבו כמו עשב השדה.",
  "72_17": "יהי שמו וזכרו קיים לעולם; כל עוד השמש קיימת יינון ויתגדל שמו, ויתברכו בו כל העמים וישבחו את אושרו.",
  "72_18": "ברוך ה' אלוהים, אלוהי ישראל, אשר עושה מעשי ניסים ונפלאות לבדו!",
  "72_19": "וברוך שם כבודו ותפארתו לעולמי עולמים, ויימלא כבודו את כל הארץ כולה – אמן ואמן!",
  "72_20": "כאן תמו ונשלמו תפילותיו ומזמוריו של דוד בן ישי (שבספר השני שבתהילים).",
  "73_1": "מזמור שיר לאסף: אכן אלוהים נוהג בטוב וברחמים עם ישראל, ועם כל מי שלבבו טהור וישר.",
  "73_2": "אך אשר אליי – כמעט מעדו רגליי, וכפסע היה ביני לבין נפילה באמונתי ובדרכי,",
  "73_3": "מכיוון שקינאתי בהוללים וביהירים כאשר ראיתי את השלווה וההצלחה שמהן נהנים הרשעים.",
  "73_4": "כי אין להם ייסורים וקשיי מוות עד יומם האחרון, וגופם בריא, חזק ושמן.",
  "73_5": "הם אינם נושאים בעמל ובסבל הרגיל של בני אדם, ואינם נפגעים בנגעים ובאסונות הפוקדים את האנושות.",
  "73_6": "לכן הגאווה מעטרת אותם כמו שרשרת ענק על צווארם, והאלימות והחמס עוטפים אותם כבגד ולבוש.",
  "73_7": "מרוב שומן ורווחה עיניהם בולטות החוצה; תאוות ליבם והזיותיהם עולות על כל דמיון ומתגשמות בקלות.",
  "73_8": "הם לועגים ומתלוצצים, מדברים ברשעות ובזדון, ומתכננים עושק ועוול מתוך תחושת עליונות והתנשאות.",
  "73_9": "בפיהם הם מטיחים דברים חצופים כנגד השמיים, ולשונם משוטטת בארץ ומכפישה כל אדם.",
  "73_10": "לכן אנשים מעמו של ה' נמשכים אחריהם ושבים להביט בדרכם, ושותים את דבריהם כמים לרוויה.",
  "73_11": "והם אומרים בזלזול: 'כיצד יידע האל? והאם בכלל יש ידיעה והשגחה אצל האל העליון על מעשינו?'.",
  "73_12": "הנה, אלה הם הרשעים – תמיד שלווים ובטוחים בעולם הזה, ועושרם וכוחם הולכים ומתרבים!",
  "73_13": "ואז הרהרתי בתסכול: האם לחינם שמרתי על לב טהור, ורחצתי את כפיי בניקיון מחטא ומעוול?",
  "73_14": "הרי הייתי מוכה בייסורים כל היום כולו, ותוכחות וייסורים פקדו אותי מדי בוקר בבוקר!",
  "73_15": "אך אם הייתי מחליט לומר ולפרסם דברים כאלה בפומבי – הרי שהייתי בוגד בקהל בניך הנאמנים ומכשיל אותם.",
  "73_16": "לכן ניסיתי להתעמק ולהבין את הסוד הזה בשכלי, אך הדבר היה קשה ומייגע מאוד בעיניי,",
  "73_17": "עד שנכנסתי אל מקדשי האל והתבוננתי ברוח הקודש והאמונה – ואז הבנתי והשכלתי מה יהיה סופם ואחריתם של הרשעים:",
  "73_18": "אכן בדרכים חלקלקות ומסוכנות אתה מעמיד אותם, והפלת אותם ברגע אחד אל חורבן ושממה!",
  "73_19": "איך הפכו למשל ולשממה כהרף עין! הם אבדו וכלו כליל מרוב בהלות ופחדים פתאומיים.",
  "73_20": "כמו חלום שחולף ונעלם כשאדם מתעורר משנתו – כך אתה, ה', בעת שאתה מתעורר לשפוט, תבזה ותבטל את דמותם החולפת.",
  "73_21": "כאשר ליבי החמיץ וכאב מכעס, ובכליותיי הרגשתי עקיצות ודקירות של מרירות –",
  "73_22": "הרי הייתי אז חסר דעת וכסיל, וכמו בהמה הייתי במחשבותיי לפניך, בלי לראות את התמונה השלמה.",
  "73_23": "אך באמת אני תמיד נתון בהשגחתך ועמך; תמכת ואחזת ביד ימיני לבל אמעד.",
  "73_24": "בעצתך החכמה תנהיג אותי בחיים, ולאחר מכן תיקח אותי אליך בכבוד ובשלוות נצח.",
  "73_25": "מי יש לי בשמיים מלבstage מלבדך? ובהיותי עמך, אינני חפץ בשום דבר אחר בכל הארץ!",
  "73_26": "כלה בשרי וליבי מתשוקה ומחולשה, אך אלוהים הוא צור ליבי, משענתי האיתנה וחבלי ונחלתי לנצח.",
  "73_27": "כי הנה אלה המתרחקים ממך סופם שיאבדו; השמדת וכרתת את כל מי שבוגד בך וסר מאחריך.",
  "73_28": "ואילו לי – קרבת אלוהים היא הטוב האמיתי! שמתי בה' אלוהים את מחסי ומבטחי, כדי לספר ולשבח את כל פלאי מעשיך.",
  "74_1": "מזמור של התבוננות (משכיל) לאסף: למה, אלוהים, נטשת אותנו לתמיד, ועולה עשן כעסך בעמך שנמשל לצאן מרעיתך?",
  "74_2": "זכור את קהילתך ועדתך אשר קנית ופדית מימי קדם, את שבט ישראל שגאלת להיות נחלתך, ואת הר ציון הזה אשר בחרת לשכון בו!",
  "74_3": "הנף ומהר את צעדיך אל עבר החורבות והשממות הנצחיות; ראה כל מה שהשחית וחילל האויב בבית המקדש!",
  "74_4": "אויביך שאגו והריעו בתוך מקום המועד והמקדש שלך; הם הציבו את דגליהם ואותות הניצחון שלהם כסמל לשלטונם.",
  "74_5": "היה נראה הדבר כאילו הניפו גרזנים למעלה בתוך סבך עצים ביער כדי לגדוע ולהרוס.",
  "74_6": "ועתה, את כל פיתוחי העץ והתבליטים המפוארים של המקדש ריסקו והיכו יחד בגרזנים ובפטישים.",
  "74_7": "הציתו באש את מקדשך המפואר, חיללו והשליכו לארץ את משכן שמך הקדוש.",
  "74_8": "אמרו בליבם: 'נשמיד אותם ואת צאצאיהם יחד!'; שרפו את כל בתי הכנסת ומקומות ההתכנסות לאל בכל הארץ.",
  "74_9": "את אותותינו והניסים שלנו לא ראינו עוד; אין עוד נביא בקרבנו, ואין איש בינינו שיודע עד מתי תימשך הצרה.",
  "74_10": "עד מתי, אלוהים, יחרף ויגדף הצר? האם ינאץ האויב את שמך לנצח?",
  "74_11": "למה אתה משיב ומחזיר את ידך – את יד ימינך החזקה? הוצא אותה מתוך חיקך וכלה את האויבים!",
  "74_12": "והרי אלוהים הוא מלכי מימי קדם, הפועל ניסים וישועות בקרב הארץ כולה.",
  "74_13": "אתה הוא זה שבקעת בגבורתך את ים סוף, ושיברת את ראשי מפלצות הים (התנינים) בתוך המים.",
  "74_14": "אתה ריסקת את ראשי הלווייתן האדיר, ונתת אותו למאכל לחיות המדבר ולשובי הציות.",
  "74_15": "אתה בקעת מעיין ונחל מן הסלע, ואתה ייבשת נהרות איתנים ושופעים.",
  "74_16": "שלך הוא היום וגם שלך הוא הלילה; אתה הכנת וכוננת את הירח (מאור) ואת השמש.",
  "74_17": "אתה קבעת את כל גבולות הארץ; קיץ וחורף – אתה הוא זה שיצרת אותם.",
  "74_18": "זכור זאת, ה': האויב חירף ולעג לך, ועם כסיל ונבל נאץ את שמך הנשגב!",
  "74_19": "אל תמסור לחית טרף את נפש יונתך התמימה (כנסת ישראל); ואת חיי ענייך ונדכאיך אל תשכח לעולם.",
  "74_20": "הבט ושים ליבך אל הברית שכרת עמנו, כי פינות החושך של הארץ נתמלאו במשכנות של אלימות וחמס.",
  "74_21": "אל תניח למדוכא ולנדכא לשוב ריקם ומבוייש; עני ואביון יודו ויהללו את שמך!",
  "74_22": "קומה, אלוהים, וריבה את ריבך! זכור את החרפה והגידוף שמטיח בך אדם נבל כל היום.",
  "74_23": "אל תשכח את קול צעקות אויביך, ואת שאון המורדים בך העולה וגובר ללא הרף.",
  "75_1": "למנצח, על נעימת 'אל תשחת', מזמור שיר לאסף.",
  "75_2": "אנו מודים לך, אלוהים, מודים לך ושמך קרוב אלינו; הבריות מספרות ומפרסמות את נפלאותיך.",
  "75_3": "כי אלוהים אומר: כאשר יגיע המועד שקבעתי – אני אשפוט ביושר ובצדק גמור.",
  "75_4": "כאשר הארץ וכל יושביה נמסים מפחד ומאובדן עשתונות – אני הוא זה שמייצב ומחזק את עמודיה.",
  "75_5": "אמרתי להוללים ולגאוותנים: אל תתהוללו, ולרשעים אמרתי: אל תרימו ראש בגאווה ואל תתייהרו בכוחכם (קרן)!",
  "75_6": "אל תרימו למרום את גאוותכם, ואל תדברו בחוצפה ובצוואר זקוף ומתנשא.",
  "75_7": "כי הגדולה וההרמה אינן באות מן המזרח, מן המערב או מן המדבר הדרומי,",
  "75_8": "אלא אלוהים הוא השופט האמיתי – את האחד הוא משפיל ומוריד, ואת האחר הוא מרים ומרומם.",
  "75_9": "כי כוס משפט יש בידו של ה', ובה יין חזק ומסוך במרקחת עונשים, והוא מוזג ממנו; אכן את שמריה ימצו וישתו כל רשעי הארץ.",
  "75_10": "ואילו אני אספר ואכריז על מעשיו לעולם, ואזמר לאלוהי יעקב.",
  "75_11": "ואת כל קרנות הגאווה והכוח של הרשעים אגדע ואשבור, ואילו קרנות הצדיקים יתרוממו וינשאו.",
  "76_1": "למנצח, בנגינת כלי מיתר, מזמור שיר לאסף.",
  "76_2": "נודע ונתגלה אלוהים ביהודה; בישראל שמו גדול ומפואר.",
  "76_3": "ויהי משכנו בירושלים (שלם), ומעונו שוכן בהר ציון.",
  "76_4": "שם שיבר את חצי הקשת הלוהטים, את המגן, את החרב ואת כלי המלחמה כולם.",
  "76_5": "נהדר ונעלה אתה, מלא אור והוד, נשגב יותר מהרי הטרף של האויבים.",
  "76_6": "נשדדו והובסו אבירי הלב והלוחמים האמיצים, נרדמו שנת מוות פתאומית, וכל גיבורי החיל לא מצאו עוד את כוח ידיהם להילחם.",
  "76_7": "מגערתך הקשה, אלוהי יעקב, נרדמו ונאלמו מרכבות סוסים ופרשים כאחד.",
  "76_8": "אתה הוא הנורא והאדיר, ומי יוכל לעמוד לפניך ברגע שמתעורר כעסך?",
  "76_9": "מן השמיים השמעת את פסק הדין והמשפט; הארץ כולה פחדה ונאלמה בדממה,",
  "76_10": "כאשר קם אלוהים למשפט, כדי להושיע את כל עניי ונדכאי הארץ.",
  "76_11": "כי אפילו חמת וכעס האדם יודו לך בסופו של דבר, וכאשר תחגור את שארית זעמך תכניע את האויב.",
  "76_12": "נדרו נדרים ושלמו אותם לה' אלוהיכם; כל הסובבים אותו יביאו מנחות ושי לאל הנורא והקדוש.",
  "76_13": "הוא יקטע ויבצור את רוח הגאווה של השרים והשליטים; הוא נורא ומטיל אימה על כל מלכי הארץ.",
  "77_1": "למנצח, על ידי ידותון המשורר, מזמור לאסף.",
  "77_2": "קולי מופנה אל אלוהים ואני זועק; קולי אל אלוהים, והוא יאזין ויקשיב לי.",
  "77_3": "ביום צרתי דרשתי וחיפשתי את ה'; ידי הייתה פרושה בתפילה בלילה ללא הפוגה, ונפשי סירבה להתנחם.",
  "77_4": "אזכור את אלוהים ואהמה מגעגוע ומכאב; אשוחח עם נפשי ותתעטף רוחי ביגון.",
  "77_5": "אחזת ופקחת את שמורות עיניי ולא יכולתי לישון; נסערתי ונדהמתי עד שלא יכולתי להוציא מילה מפי.",
  "77_6": "חשבתי על ימי קדם, על שנים של דורות עברו וההיסטוריה המפוארת של עמי.",
  "77_7": "אזכור בלילה את נגינתי ושירתי בעבר; עם ליבי אשוחח ואחקור היטב ברוחי:",
  "77_8": "האם לנצח ייטוש אותנו ה', ולא ירצה בנו עוד לעולם?",
  "77_9": "האם פסק ואזל חסדו לתמיד? האם תם וכלה דברו והבטחתו לכל הדורות?",
  "77_10": "האם שכח האל לחמול ולהיות חנון? האם בכעסו סגר ואטם את רחמיו?",
  "77_11": "ואז אמרתי: זהו הכאב והשבר שלי – השינוי שחל כביכול בפעולת יד ימינו של האל העליון.",
  "77_12": "אזכיר ואעלה על נס את מעשי יה; אזכור תמיד את נפלאותיך וניסיך מימי קדם.",
  "77_13": "אהגה ואתבונן בכל פועלך הגדול, ובמעשי גבורתך אשוחח.",
  "77_14": "אלוהים, דרכך נעלה בקדושה ובטהרה; מי אל גדול ונשגב כמו אלוהים שלנו?",
  "77_15": "אתה הוא האל עושה פלא; הודעת והפגנת בעמים את כוחך וגבורתך.",
  "77_16": "גאלת בזרוע נטויה ובכוח עצום את עמך, את בני יעקב ויוסף.",
  "77_17": "ראוך המים בקריעת ים סוף, אלוהים, ראוך המים וחרדו; אף מעמקי התהומות רעדו ורגזו.",
  "77_18": "ענני השמיים הזרימו מים רבים כסופה, השחקים השמיעו קול רעמים אדיר, וחצי הברקים שלך התעופפו לכל עבר.",
  "77_19": "קול רעמך התגלגל בסערה, ברקים האירו את תבל כולה, והארץ רעדה וגעשה.",
  "77_20": "בים הייתה דרכך ונתיבך עבר בתוך מים אדירים, ועקבותיך הנסתרות לא נודעו.",
  "77_21": "הנהגת כעדר צאן את עמך, בידם של משה ואהרון הנאמנים.",
  "78_1": "מזמור של מוסר והתבוננות (משכיל) לאסף: האזינו, עמי, לתורתי ולהדרכתי; הטו את אוזנכם לדברי פי.",
  "78_2": "אפתח את פי במשל מאלף, אביע חידות וסודות ממעמקי ימי קדם,",
  "78_3": "דברים אשר שמענו וידענו אותם היטב, ואבותינו סיפרו והנחילו לנו.",
  "78_4": "לא נסתיר אותם מבניהם, ונספר לדור הבא את תהילות ה', את כוחו העצום ואת הנפלאות אשר עשה.",
  "78_5": "הוא הקים עדות ביעקב ותורה שם בישראל, אשר ציווה את אבותינו להודיע וללמד אותם לבניהם,",
  "78_6": "כדי שיידע הדור הבא, בנים שעתידים להיוולד, ויקומו ויספרו לבניהם שלהם;",
  "78_7": "וזאת כדי שישימו באלוהים את מבטחם ותקוותם, לא ישכחו את מעשי האל, וינצרו את מצוותיו;",
  "78_8": "ולא יהיו כאבותיהם – דור סורר וממרה, דור שלא הכין וכיוון את ליבו כראוי, ולא הייתה רוחו נאמנה לאל.",
  "78_9": "בני אפרים, נושאי קשת וחמושים, נסוגו וברחו לאחור ביום קרב ומערכה.",
  "78_10": "לא שמרו את ברית אלוהים, ובדרכי תורתו מאנו ללכת.",
  "78_11": "הם שכחו את מעשיו המופלאים, ואת הניסים שהראה להם.",
  "78_12": "לעיני אבותיהם עשה פלא בארץ מצרים, בשדה צוען המפורסם.",
  "78_13": "הוא בקע את הים והעביר אותם בתוכו, והעמיד את המים כחומה זקופה.",
  "78_14": "הנחה אותם בענן יומם, וכל הלילה באור אש לוהטת.",
  "78_15": "בקע צורים וסלעים במדבר, והשקה אותם מים בשפע רב כאילו שאבו ממעמקי תהומות.",
  "78_16": "הוציא נחלים וזרמים מתוך הסלע, והוריד מים שוצפים כנהרות.",
  "78_17": "אך הם הוסיפו לחטוא כנגדו, ולמרוד באל עליון בארץ ציה ושממה.",
  "78_18": "וניסו ובחנו את האל בליבם, כשביקשו בתאווה אוכל לנפשם.",
  "78_19": "ודיברו כנגד אלוהים ואמרו בספקנות: 'האם יוכל האל לערוך שולחן ולספק סעודה במדבר?",
  "78_20": "הן היכה בסלע ויזובו מים ונחלים שטפו – אך האם יוכל גם לתת לחם? האם יכין בשר לעמו?'.",
  "78_21": "לכן שמע ה' והתמלא זעם, ואש בערה ביעקב ואף כעס עלה כנגד ישראל,",
  "78_22": "מכיוון שלא האמינו באלוהים, ולא בטחו בישועתו ובכוחו.",
  "78_23": "ובכל זאת ציווה שחקים ממעל, ודלתות השמיים פתח,",
  "78_24": "והוריד עליהם מַן לאכול כמטר, ודגן שמיים נתן להם.",
  "78_25": "לחם אבירים ומלאכים אכל כל אדם; צידה וספק מזון שלח להם לשובע.",
  "78_26": "הסיע רוח קדים מזרחית בשמיים, והנהיג בעוזו רוח דרומית (תימן),",
  "78_27": "והמטיר עליהם בשר בשפע כעפר, ועופות כנף רבים כחול שעל שפת הים.",
  "78_28": "והפיל אותו בתוך מחנהו, סביב סביב למשכנותיו.",
  "78_29": "ואכלו ושבעו מאוד, ואת תאוותם הביא וסיפק להם.",
  "78_30": "עוד לא הספיקו להיגמל מתאוותם, ועוד המזון בפיהם,",
  "78_31": "ואף אלוהים עלה בהם, והרג בחזקים ובשמנים שבהם, ואת בחורי ישראל הכריע במגפה.",
  "78_32": "בכל זאת חטאו עוד, ולא האמינו בניסיו ובנפלאותיו.",
  "78_33": "לכן כילה את ימיהם בהבל ובריקנות, ושנותיהם עברו בבהלה ובחרדה.",
  "78_34": "כאשר היכה והרג בהם – אז דרשו אותו ושבו אליו, וקמו מוקדם לבקש את פני האל.",
  "78_35": "ונזכרו כי אלוהים הוא צורם ומחזקם, ואל עליון הוא גואלם.",
  "78_36": "אך פיתו אותו בפיהם בדברי חנופה, ובלשונם שיקרו לו;",
  "78_37": "וליבם לא היה נאמן ויציב עימו, ולא עמדו בבריתו.",
  "78_38": "והוא, בהיותו רחום, כיפר על עוונם ולא השחית אותם כליל; פעמים רבות כבש את כעסו ולא עורר את כל חמתו,",
  "78_39": "ונזכר כי הם רק בשר ודם, רוח חולפת והולכת שאיננה שבה.",
  "78_40": "כמה פעמים המרו את פיו במדבר, והעציבו אותו בארץ שממה!",
  "78_41": "וחזרו וניסו את האל, ואת קדוש ישראל הגבילו והכעיסו.",
  "78_42": "לא זכרו את ידו וגבורתו, ואת היום שבו פדה אותם מן האויב והצר;",
  "78_43": "את האותות והמופתים אשר שם במצרים, ואת פלאיו בשדה צוען.",
  "78_44": "כאשר הפך לדם את נהרותיהם, ואת יובליהם לא יכלו לשתות.",
  "78_45": "שילח בהם ערוב של חיות רעות שיאכלם, וצפרדעים שהשחיתו את ארצם.",
  "78_46": "ונתן לחסיל את יבולם החקלאי, ואת פרי עמלם לארבה.",
  "78_47": "הרג בברד כבד את גפניהם, ואת עצי השקמה שלהם באבני ברד חזקות (חנמל).",
  "78_48": "והסגיר לברד את בהמתם, ואת מקניהם לברקים ולרשפי אש.",
  "78_49": "שילח בהם את חרון אפו, זעם, עברה, צרה ומשלחת מלאכי חבלה רעים.",
  "78_50": "פילס נתיב ופתח דרך לכעסו; לא מנע ממוות את נפשם, ואת חייהם הסגיר למגפת הדבר.",
  "78_51": "והיכה כל בכור במצרים, ראשית כוחם ואונם באוהלי חם.",
  "78_52": "והוציא כצאן את עמו ישראל, והנהיג אותם כעדר במדבר.",
  "78_53": "והנחה אותם לבטח ולא פחדו, ואילו את אויביהם המצרים כיסה הים.",
  "78_54": "והביא אותם אל גבול קודשו, אל ההר הזה שקנתה ורכשה יד ימינו.",
  "78_55": "וגירש מפניהם עמים וגויים, והפיל להם נחלה בחבל חלוקה, והשכין באוהליהם את שבטי ישראל.",
  "78_56": "אך הם ניסו והמרו את אלוהים עליון, ואת עדותיו ומצוותיו לא שמרו.",
  "78_57": "ונסוגו ובגדו כאבותיהם; נהפכו וסטו כקשת רפויה ומטעה שאינה קולעת למטרה.",
  "78_58": "והכעיסו אותו בבמות עבודה זרה שלהם, ובפסליהם עוררו את קנאתו.",
  "78_59": "שמע אלוהים והתמלא עברה, ומאס בישראל מאוד על מעשיהם.",
  "78_60": "ונטש את משכן שילה, האוהל שבו שכן בקרב בני אדם.",
  "78_61": "ומסר לשבי את ארון עוזו, ואת תפארתו ביד האויב הפלשתי.",
  "78_62": "והסגיר לחרב את עמו, ועל נחלתו התעבר וכעס.",
  "78_63": "בחוריו אכלה אש המלחמה, ובתולותיו לא זכו לשירי חופה ונישואין.",
  "78_64": "כוהניו נפלו בחרב, ואלמנותיו לא יכלו לבכות ולהספיד מרוב צרה.",
  "78_65": "ואז התעורר ה' כמו אדם שישן, כגיבור המתנער מיינו ומריע לקראת קרב.",
  "78_66": "והיכה את אויביו מאחור במכות כואבות (בטחורים), וחרפת עולם נתן להם.",
  "78_67": "ומאס באוהל יוסף, ובשבט אפרים לא בחר להנהיג עוד,",
  "78_68": "אלא בחר בשבט יהודה, בהר ציון אשר אהב.",
  "78_69": "ובנה כגבהי מרומים את מקדשו, יציב לעולם כארץ אשר ייסד אותה לתמיד.",
  "78_70": "ובחר בדוד עבדו, ולקח אותו ממכלאות הצאן;",
  "78_71": "מאחורי הצאן המניקות הביא אותו, לרעות ולהנהיג את יעקב עמו ואת ישראל נחלתו.",
  "78_72": "והוא הנהיג ורעה אותם בתום ליבו ובטהרתו, ובתבונת ידיו הדריך והוביל אותם.",
  "79_1": "מזמור קינה לאסף: אלוהים, גויים באו לנחלתך, טימאו את היכל קודשך, ושמו את ירושלים לעיי חורבות!",
  "79_2": "נתנו את נבלת עבדיך למאכל לעוף השמיים, ואת בשר חסידיך לחיות הארץ.",
  "79_3": "שפכו את דמם כמים סביבות ירושלים, ואין איש שקובר אותם.",
  "79_4": "היינו לחרפה ולבושה לשכנינו, ללעג ולקלס לסובבים אותנו.",
  "79_5": "עד מתי, ה'? האם תכעס לנצח? האם תבער כמו אש קנאתך?",
  "79_6": "שפוך את חמתך על הגויים אשר לא ידעו אותך, ועל ממלכות אשר בשמך אינן קוראות,",
  "79_7": "כי אכלו והחריבו את יעקב, ואת משכנו ונווהו שממו והחריבו.",
  "79_8": "אל תזכור לנו עוונות של דורות ראשונים; ימהרו ויקדמו אותנו רחמיך, כי נעשינו דלים ומושפלים מאוד.",
  "79_9": "עזור לנו, אלוהי ישענו, למען כבוד שמך; והצל אותנו וכפר על חטאינו למען שמך הנשגב.",
  "79_10": "למה יאמרו הגויים בלעג: 'איה אלוהיהם?'; ייוודע בקרב הגויים לעינינו נקמת דם עבדיך שנשפך!",
  "79_11": "תבוא לפניך אנקת האסיר והשבוי הכבול; בגדולת זרועך שחרר והציל את אלה הנידונים למיתה.",
  "79_12": "והשב לשכנינו פי שבעה אל חיקם על החרפה אשר חירפו אותך, ה'.",
  "79_13": "ואנחנו, עמך וצאן מרעיתך, נודה לך לעולם; מדור לדור נספר את תהילתך ושבחך.",
  "80_1": "למנצח, על נעימת 'שושנים', עדות ומזמור לאסף.",
  "80_2": "רועה ישראל, האזנה והקשב, אתה הנוהג את יוסף כעדר צאן; שוכן הכרובים, הופע בהודך והאר פניך!",
  "80_3": "לפני שבטי אפרים, בנימין ומנשה, עורר את גבורתך ובוא להושיע אותנו!",
  "80_4": "אלוהים, השב אותנו מן הגלות והצרה, והאר פניך אלינו וניוושע!",
  "80_5": "ה' אלוהי צבאות, עד מתי תעשן בכעס כנגד תפילת עמך?",
  "80_6": "האכלת אותם לחם דמעות ומכאוב, והשקית אותם דמעות בכלי מידה גדול פי שלושה.",
  "80_7": "שמת אותנו למריבה ולסכסוך לשכנינו, ואויבינו לועגים לנו בינם לבין עצמם.",
  "80_8": "אלוהי צבאות, השב אותנו אליך, והאר פניך ברצון וניוושע!",
  "80_9": "גפן ממצרים עקרת והוצאת (עם ישראל); גירשת גויים ונטעת אותה בארץ.",
  "80_10": "פינית מקום לפניה, והיא העמיקה שורשיה ומילאה את הארץ.",
  "80_11": "הרים כוסו בצילה, וענפיה הפורחים היו כמו ארזי אל אדירים.",
  "80_12": "שלחה ענפיה עד הים התיכון, ויונקותיה וסעיפיה עד נהר פרת.",
  "80_13": "למה פרצת את גדרותיה המגנות, וכל עוברי הדרך קוטפים ובוזזים את פירותיה?",
  "80_14": "חזיר יער מכרסם ומשחית אותה, וחיות השדה רועות ואוכלות בה.",
  "80_15": "אלוהי צבאות, שוב נא אלינו! הבט משמיים וראה, ופקוד לטובה את הגפן הזאת;",
  "80_16": "ואת השתיל (כנה) אשר נטעה יד ימינך, ואת הבן והענף שאימצת וחיזקת לעצמך.",
  "80_17": "היא שרופה באש וכסוחה כקוצים; מגערת פניך יאבדו האויבים המשחיתים אותה.",
  "80_18": "תהא ידך ועזרתך על איש ימינך (מלך ישראל), על בן אדם אשר אימצת וחיזקת למענך.",
  "80_19": "ולא נסוג ולא נתרחק ממך עוד; תחיה אותנו ונשוב לקרוא בשמך.",
  "80_20": "ה' אלוהי צבאות, השב אותנו, האר פניך אלינו וניוושע!",
  "81_1": "למנצח, על נעימת הגתית, שיר שבח לאסף.",
  "81_2": "שירו ורננו בהתלהבות לאלוהים מעוזנו, הריעו בשמחה לאלוהי יעקב!",
  "81_3": "פתחו בשיר ושאו זמרה, תנו תוף נעים יחד עם כינור ונבל.",
  "81_4": "תקעו שופר בראש חודש, ובזמן ההתכנסות והכיסוי ליום חגנו הקדוש (ראש השנה וסוכות).",
  "81_5": "כי חוק ומצווה הוא לישראל, משפט וסדר שנקבע מאת אלוהי יעקב.",
  "81_6": "תעודה ועדות קבע ביוסף כאשר יצא לפעול על ארץ מצרים; שפת ה' אשר לא ידעתי שמעתי:",
  "81_7": "הסירותי מסבל וממשא את שכם כתפו, כפיו נפטרו מסחיבת דודי הטיט.",
  "81_8": "בצרה קראת אליי ואני חילצתי אותך; עניתי לך בסתר רעם ענן, בחנתי אותך על מי מריבה.",
  "81_9": "שמע, עמי, ואעידה ואזהיר בך: ישראל, לו רק תשמע בקולי!",
  "81_10": "לא יהיה בקרבך אל זר, ולא תשתחווה לאל נכר.",
  "81_11": "אנוכי ה' אלוהיך המעלה אותך מארץ מצרים; הרחב את פיך לבקש – ואני אמלא כל משאלותיך בטוב!",
  "81_12": "אך עמי לא שמע לקולי, וישראל לא אבה ולא רצה ללכת בדרכי.",
  "81_13": "על כן שילחתי ועזבתי אותם בשרירות ליבם ובעקשנותם, שילכו בעצותיהם המוטעות.",
  "81_14": "לו רק עמי שומע לי, וישראל בדרכיי יהלכו –",
  "81_15": "בקלות וכהרף עין הייתי מכניע את אויביהם, ועל צורריהם הייתי מחזיר את ידי להכותם.",
  "81_16": "שונאי ה' היו מתכחשים ומחניפים לו מרוב פחד, וזמנם והצלחתם של ישראל היו מתקיימים לעד.",
  "81_17": "והייתי מאכיל אותם ממיטב חלב החיטה המובחרת, ומסלע הייתי משביע אותך דבש טהור.",
  "82_1": "מזמור תוכחה לאסף: אלוהים ניצב בעדת שופטי העם (עדת אל), ובקרב שופטים הוא שופט ומבקר את מעשיהם:",
  "82_2": "עד מתי תשפטו במשוא פנים ובעוול, ותכבדו ותעדיפו את פני הרשעים לתמיד?",
  "82_3": "שפטו בצדק את היתום והדל, עשו משפט ישר לעני ולחסר כל.",
  "82_4": "חלצו והצילו את הדל ואת האביון, ומיד רשעים הצילו אותם!",
  "82_5": "אך השופטים אינם יודעים ואינם מבינים, בחשכת בורותם ושחיתותם הם מתהלכים; בגלל עוול זה רועדים ומתמוטטים כל יסודות סדרי הארץ.",
  "82_6": "אני אמרתי: 'אלוהים ושופטים רמים אתם, ובני אל עליון כולכם';",
  "82_7": "אכן, כאדם בן תמותה רגיל תמותו, וכאחד השרים הנופלים תיפלו!",
  "82_8": "קומה, אלוהים, ושפוט אתה את הארץ, כי אתה תנחל ותמשול בכל הגויים!",
  "83_1": "שיר מזמור תפילה לאסף.",
  "83_2": "אלוהים, אל תדום ואל תשקוט; אל תחריש ואל תישאר פסיבי, אל!",
  "83_3": "כי הנה אויביך הומים ורועשים, ושונאיך הרימו ראש בגאווה.",
  "83_4": "על עמך הם מתכננים מזימות בסתר, ומתייעצים יחד כנגד אלה שאתה מגן עליהם (צפוניך).",
  "83_5": "אמרו בזדון: 'בואו ונכחיד אותם מלהיות עם, ולא ייזכר עוד שם ישראל לעולם!'.",
  "83_6": "כי נועצו יחד בלב אחד ובמחשבה משותפת; נגדך כרתו ברית עוינת:",
  "83_7": "אוהלי אדום והישמעאלים, מואב וההגריים,",
  "83_8": "גבל, עמון ועמלק, פלשת יחד עם יושבי צור;",
  "83_9": "גם ממלכת אשור הצטרפה אליהם, והיו לזרוע תומכת ולסיוע לבני לוט (מואב ועמון).",
  "83_10": "עשה להם כמו שעשית למדין, כמו לסיסרא וליבין בנחל קישון,",
  "83_11": "אשר הושמדו בעין דור והיו לדומן וזבל על פני האדמה.",
  "83_12": "עשה את שריהם ומנהיגיהם כמו עורב וכמו זאב, וכמו זבח וכמו צלמונע את כל נסיכיהם,",
  "83_13": "אשר אמרו בתאוות כיבוש: 'נירש לעצמנו את נאות אלוהים ומשכנותיו!'.",
  "83_14": "אלוהיי, שים אותם כגלגל קוצים הנסחף ברוח, וכקש מתעופף לפני סערה.",
  "83_15": "כמו אש הבוערת ביער, וכלהבה המלהיטה הרי קוצים –",
  "83_16": "כך תרדוף אותם בסערתך, ובסופתך תבהיל ותרתיע אותם.",
  "83_17": "מלא את פניהם בבושה ובקלון, כדי שיחפשו ויכירו את שמך, ה'.",
  "83_18": "יבושו וייבהלו עד עולמי עד, ייכלמו ויאבדו כליל;",
  "83_19": "ויידעו כולם כי אתה, ששמך ה' לבדך, עליון ונשגב על כל פני הארץ!",
  "84_1": "למנצח, על נעימת הגתית, מזמור שיר לבני קורח.",
  "84_2": "מה אהובים ונעימים משכנותיך, ה' צבאות!",
  "84_3": "נכספה וגם כלתה נפשי מרוב געגועים לחצרות ה'; ליבי וגופי מריעים ושרים בשמחה לאל חי.",
  "84_4": "אפילו ציפור מצאה לה בית, ודרור קן לעצמה ששמה בו את אפרוחיה – בסמוך למזבחותיך, ה' צבאות, מלכי ואלוהיי!",
  "84_5": "אשרי היושבים בבית קודשך, עוד יהללו וישבחו אותך תמיד!",
  "84_6": "אשרי האדם שעוזו ומבטחו בך, ואשר מסילות העלייה לרגל חקוקות בליבו.",
  "84_7": "עוברים בעמק הבכא והיובש והופכים אותו למעיין מים, ואף גשמי ברכה ראשונים עוטפים אותו בבריכות.",
  "84_8": "הם הולכים מחיל אל חיל, מתגברים והולכים בדרכם, עד שייראה כל אחד מהם אל אלוהים בציון.",
  "84_9": "ה' אלוהי צבאות, שמעה נא תפילתי; האזינה והקשב, אלוהי יעקב!",
  "84_10": "מגיננו ראה, אלוהים, והבט בחסד על פני משיחך הנבחר.",
  "84_11": "כי טוב יום אחד בחצרותיך מאלף ימים במקום אחר; בחרתי להסתופף על סף בית אלוהיי מאשר לדור בשלווה באוהלי רשע.",
  "84_12": "כי שמש ומגן הוא ה' אלוהים; חן וכבוד ייתן ה', ולא ימנע שום טוב מההולכים בתמימות וביושר.",
  "84_13": "ה' צבאות, אשרי האדם הבוטח בך בכל ליבו!",
  "85_1": "למנצח, מזמור שיר לבני קורח.",
  "85_2": "התרצית, ה', לארצך בעין טובה; השבת את שבות עמך יעקב מן הגלות והמצוקה.",
  "85_3": "נשאת וסלחת לעוון עמך, כיסית ומחלת על כל חטאתם לתמיד.",
  "85_4": "אספת וסילקת את כל עברתך, נסוגת מחרון אפך וכעסך.",
  "85_5": "שוב נא אלינו והחזר אותנו, אלוהי ישענו, והפר את כעסך עמנו.",
  "85_6": "האם לעולם תכעס עלינו? האם תמשוך את אפך מדור לדור?",
  "85_7": "האם לא תשוב ותחיה אותנו מחדש, כדי שעמך ישמח בך ובישועתך?",
  "85_8": "הראנו, ה', את חסדך ואהבתך, ואת ישועתך תיתן ותעניק לנו.",
  "85_9": "אשמע מה ידבר האל ה' – כי ידבר שלום אל עמו ואל חסידיו, ובלבד שלא ישובו לסכלותם ולחטאיהם.",
  "85_10": "אכן קרובה ישועתו ליראיו, כדי שישכון כבוד ושכינה בארצנו.",
  "85_11": "חסד ואמת נפגשו יחד בהרמוניה, צדק ושלום נשקו והתחברו זה לזה.",
  "85_12": "אמת מן הארץ תצמח, וצדק מן השמיים ישקיף וישפיע טובה.",
  "85_13": "גם ה' ייתן את הטוב והברכה, וארצנו תיתן את יבולה בשפע.",
  "85_14": "הצדק יילך לפניו להנחות, וישים ויכוון את פעמיו לדרך ישרה.",
  "86_1": "תפילה לדוד: הטה, ה', את אוזנך וענה לי, כי עני וחסר ישע אני.",
  "86_2": "שמור על נפשי כי חסיד ונאמן אני; הושע את עבדך הבוטח בך, אתה הוא אלוהיי!",
  "86_3": "חון אותי, אדוני, כי אליך אני זועק ומתפלל כל היום.",
  "86_4": "שמח את נפש עבדך, כי אליך, אדוני, אני נושא את נפשי ותקוותי.",
  "86_5": "כי אתה, אדוני, טוב וסלחן, ורב חסד ורחמים לכל הקוראים אליך.",
  "86_6": "האזינה, ה', לתפילתי, והקשב היטב לקול תחנוניי.",
  "86_7": "ביום צרתי אקרא אליך, כי בטוח אני שתענה לי.",
  "86_8": "אין כמוך בין האלים, אדוני, ואין שום מעשים דומים למעשיך המופלאים.",
  "86_9": "כל הגויים אשר יצרת יבואו וישתחוו לפניך, אדוני, ויכבדו את שמך הנשגב.",
  "86_10": "כי גדול אתה ועושה נפלאות אדירות; אתה אלוהים לבדך!",
  "86_11": "הורני, ה', את דרכך ואהלך באמיתך; יחד וחבר את ליבי ליראה ולכבד את שמך.",
  "86_12": "אודה לך, אדוני אלוהיי, בכל ליבי, ואכבד את שמך לעולם ועד.",
  "86_13": "כי חסדך גדול ורחב עליי, והצלת את נפשי ממעמקי שאול ומוות.",
  "86_14": "אלוהים, אנשים זדים ויהירים קמו עליי, ועדת עריצים אלימים ביקשו ליטול את נפשי, ולא שמו אותך לנגד עיניהם.",
  "86_15": "ואתה, אדוני, אל רחום וחנון, ארך אפיים ורב חסד ואמת.",
  "86_16": "פנה אליי וחנני; תן את עוזך וכוחך לעבדך, והושע את בן אמתך.",
  "86_17": "עשה עימי אות ומופת לטובה, ויראו שונאי ויבושו, כי אתה, ה', עזרת לי וניחמת אותי.",
  "87_1": "מזמור שיר לבני קורח על יסודות קודשו בהרים הרמים.",
  "87_2": "אוהב ה' את שערי ציון יותר מכל משכנות יעקב האחרים.",
  "87_3": "דברים נכבדים ומפוארים מדוברים בך, עיר האלוהים!",
  "87_4": "אזכיר את רהב (מצרים) ובבל למכירי ויודעי שמי; הנה פלשת וצור עם כוש – כל אחד יתגאה: 'זה נולד שם בציון!'.",
  "87_5": "ולציון ייאמר: איש ואיש מכל העמים נולד בה כבמולדתו, והוא אל עליון יכונן ויחזק אותה לעד.",
  "87_6": "ה' יספור במפקד הלאומים ובספר העמים: 'זה וזה נולד בה בציון!'.",
  "87_7": "ומשוררים וכלי נגינה ישירו יחד: כל מקורותיי ומעיינות שמחתי בך!",
  "88_1": "שיר מזמור לבני קורח, למנצח על מחלת לענות, משכיל להימן האזרחי.",
  "88_2": "ה' אלוהי ישועתי, יומם צעקתי ובלילה באתי לפניך בתחינה.",
  "88_3": "תבוא לפניך תפילתי, הטה את אוזנך אל זעקתי הכואבת.",
  "88_4": "כי שבעה נפשי צרות וייסורים, וחיי התקרבו אל סף השאול והמוות.",
  "88_5": "נחשבתי כבר כאחד מאלה היורדים אל קבר הבור; הייתי כמו גבר תשוש שאין בו עוד כוח.",
  "88_6": "משוחרר ומושלך בין המתים, כמו חללים השוכבים בקבר, אשר אינך זוכר אותם עוד והם נגזרו ונכרתו מידך.",
  "88_7": "שמת אותי בבור תחתיות חשוך, במקומות אפלים ובמעמקים.",
  "88_8": "עליי סמכה וכבדה חמתך, ובכל גלי משבריך עינית אותי.",
  "88_9": "הרחקת ממני את מכריי ואוהביי, שמת אותי לתועבה בעיניהם; אני כלוא וסגור ואינני יכול לצאת.",
  "88_10": "עיני כהתה ודועכת מרוב צער ועוני; קראתי אליך, ה', בכל יום, פרשׂתי אליך את כפיי.",
  "88_11": "האם למתים תעשה פלא? האם רפאים יקומו מן הקבר ויודו לך?",
  "88_12": "האם יסופר בקבר חסדך, ואמונתך ונאמנותך במקום האבדון?",
  "88_13": "האם ייוודעו בחושך פלאיך, וצדקתך בארץ השכחה שאין בה זיכרון?",
  "88_14": "ואני – אליך, ה', זעקתי, ובבוקר תקדם אותך תפילתי.",
  "88_15": "למה, ה', תיטוש את נפשי, ותסתיר את פניך ממני?",
  "88_16": "עני וגווע אני מנעוריי, נשאתי את אימותיך ופחדיך עד שנואשתי וכמעט אבדתי.",
  "88_17": "עליי עברו חרוני כעסיך, וביעותיך ואימותיך השמידו ושיתקו אותי.",
  "88_18": "סבבו אותי מכל עבר כמים שוטפים כל היום, הקיפו עליי יחד מכל צד.",
  "88_19": "הרחקת ממני אוהב ורע, ומכריי נעלמו אל תוך החושך והאפלה.",
  "89_1": "מזמור של התבוננות (משכיל) לאיתן האזרחי.",
  "89_2": "חסדי ה' לעולם אשירה; לדור ודור אודיע ואפרסם את אמונתך בפי.",
  "89_3": "כי אמרתי: עולם של חסד ייבנה לתמיד, ובשמיים הנצחיים תכין ותקיים את אמונתך.",
  "89_4": "כרתי ברית עם בחיר לבי, נשבעתי לדוד עבדי הנאמן:",
  "89_5": "עד עולם אכין ואבסס את זרעך, ואבנה לדור ודור את כיסא מלכותך.",
  "89_6": "ויודו השמיים והמלאכים את פלאיך, ה', ואף את אמונתך בקהל הקדושים.",
  "89_7": "כי מי בשחקים יכול להיערך ולהשתוות לה'? מי ידמה לה' בין כל בני האלים והמלאכים?",
  "89_8": "אל נערץ ונורא בסוד קדושים רבה, ואדיר ומטיל מורא על כל הסובבים אותו.",
  "89_9": "ה' אלוהי צבאות, מי כמוך חסין ואדיר, יָהּ, ואמונתך ונאמנותך סובבות אותך מכל עבר!",
  "89_10": "אתה מושל בגאות הים וברוממותו; בעת שמתרוממים גליו – אתה הוא המשקיט והמרגיע אותם.",
  "89_11": "אתה ריסקת כחלל פצוע את רהב (מצרים), ובזרוע עוזך פיזרת את אויביך.",
  "89_12": "לך השמיים ואף לך הארץ; תבל וכל אשר בה – אתה ייסדת וכוננת אותם.",
  "89_13": "צפון ודרום (תימן) אתה בראת אותם; הר תבור והר חרמון בשמך ירננו בשמחה.",
  "89_14": "לך זרוע בעלת גבורה אדירה; תעוז ידך ותתרומם יד ימינך.",
  "89_15": "צדק ומשפט הם בסיס ומכון כיסא כבודך; חסד ואמת מקדימים והולכים לפני פניך.",
  "89_16": "אשרי העם היודע תרועה ושמחת קודש; ה', באור פניך הנעימות יהלכון!",
  "89_17": "בשמך יגילו וישמחו כל היום, ובצדקתך יתרוממו ויתנשאו.",
  "89_18": "כי תפארת כוחם ועוזם אתה, וברצונך וחסדך תרים ותרומם את קרננו וכוחנו.",
  "89_19": "כי לה' שייך מגננו המגן עלינו, ולקדוש ישראל שייך מלכנו.",
  "89_20": "אז דיברת בחזון נבואי לחסידיך ונביאיך ואמרת: שמתי עזר וגבורה על גיבור, רוממתי בחור מתוך העם;",
  "89_21": "מצאתי את דוד עבדי, ובשמן קודשי משחתי אותו למלך.",
  "89_22": "אשר ידי תהיה מוכנה לעזור לו תמיד, ואף זרועי תחזק ותאמץ אותו.",
  "89_23": "לא יוכל אויב להערים עליו או ללחוץ אותו, ובן עוולה לא יענה ויכניע אותו.",
  "89_24": "ואכתת וארסק מפניו את צורריו, ואת שונאיו אנצח ואכה במגפה.",
  "89_25": "ואמונתי וחסדי יהיו עמו תמיד, ובשמי תורם ותתעלה קרנו ותוקפו.",
  "89_26": "ואשים על הים את שלטון ידו, ועל נהרות את יד ימינו.",
  "89_27": "הוא יקרא לי באהבה: 'אבי אתה, אלי וצור ישועתי!'.",
  "89_28": "אף אני אשים אותו כבן בכור ואהוב, עליון ונכבד על כל מלכי הארץ.",
  "89_29": "לעולם אשמור לו את חסדי, ובריתי תישאר נאמנת וקיימת עימו.",
  "89_30": "ושמתי לעד את שושלת זרעו, ואת כיסא מלכותו אקיים כימי השמיים הנצחיים.",
  "89_31": "אך אם יעזבו בניו את תורתי, ובמשפטיי הישרים לא ילכו;",
  "89_32": "אם את חוקותיי יחללו, ואת מצוותיי לא ישמרו –",
  "89_33": "אז אפקוד ואעניש בשבט מוסר את פשעם, ובייסורים ונגעים את עוונם;",
  "89_34": "אך את חסדי לא אפר ולא אקח ממנו, ולא אשקר ולא אבגוד באמונתי.",
  "89_35": "לא אחלל ולא אבטל את בריתי, ומוצא שפתיי והבטחתי לא אשנה.",
  "89_36": "פעם אחת נשבעתי בקדושתי – האם אכזב ואשקר לדוד?",
  "89_37": "זרעו יהיה קיים לעולם, וכיסאו יהיה יציב ומאיר לפניי כשמש.",
  "89_38": "כמו הירח ייכון ויישאר לעולם, וכמו עד נאמן בשחקים לעד ולנצח סלה.",
  "89_39": "והנה עתה אתה זנחת ומאסת, והתמלאת כעס ועברה על משיחך!",
  "89_40": "הפרת וביטלת את ברית עבדך, חיללת והשלכת לארץ את כתר נזרו.",
  "89_41": "פרצת את כל גדרותיו וחומותיו, שמת את מבצריו לחורבה ולשממה.",
  "89_42": "בזזו ושדדו אותו כל עוברי הדרך, והיה ללעג ולחרפה לשכניו.",
  "89_43": "הרמת וחיזקת את יד ימינם של צורריו, ושימחת את כל אויביו במפלתו.",
  "89_44": "אף הפכת והקהית את חדות חרבו, ולא העמדת וחיזקת אותו במלחמה.",
  "89_45": "השבתת וביטלת את זוהר תפארתו (מטהרו), ואת כיסא מלכותו הפלת לארץ.",
  "89_46": "קיצרת את ימי נעוריו וחיוניותו, עטפת והלבשת אותו בושה וכלימה.",
  "89_47": "עד מתי, ה'? האם תסתתר מאיתנו לנצח? האם תבער כמו אש חמתך?",
  "89_48": "זכור נא כמה קצרים חיי האדם בעולם החלד; על איזה הבל ושווא בראת את כל בני האדם אם כך סופם?",
  "89_49": "מי הוא האדם שיחיה לנצח ולא יראה מוות? האם יוכל למלט את נפשו מאחיזת השאול?",
  "89_50": "איה חסדיך הראשונים והמפוארים, אדוני, אשר נשבעת לדוד באמונתך ובנאמנותך?",
  "89_51": "זכור, אדוני, את חרפת עבדיך, את אשר נשאתי בחיקי את כל עלבונותיהם של עמים רבים,",
  "89_52": "אשר חירפו אויביך, ה', אשר לעגו וביזו את עקבות פעמיו של משיחך!",
  "89_53": "ברוך ה' לעולם, אמן ואמן!",
  "90_1": "תפילה מאת משה, איש האלוהים: אדוני, אתה היית לנו למעון ומחסה בטוח בכל דור ודור.",
  "90_2": "עוד בטרם נולדו ההרים וחוללת ויצרת ארץ ותבל – מעולם ועד עולם אתה הוא האל הנצחי.",
  "90_3": "אתה משיב את האדם עד היותו דק כעפר דכא, ואומר: 'שובו אל העפר, בני אדם'.",
  "90_4": "כי אלף שנים בעיניך הן כיום אתמול שחלף וכאשמורת לילה קצרה.",
  "90_5": "זרמת וסחפת אותם בזרם הזמן, כשינה הם נחשבים; בבוקר הם צומחים ורעננים כעשב השדה,",
  "90_6": "בבוקר הוא פורח ומלבלב, ולעת ערב הוא נחתך ומתייבש.",
  "90_7": "כי כלינו ואבדנו בכעסך, ומחמתך וזעמך נבהלנו.",
  "90_8": "הצגת את עוונותינו לנגד עיניך, ואת חטאינו הנסתרים חשפת לאור פניך.",
  "90_9": "כי כל ימינו חולפים ופונים בעברתך וכעסך; כלינו את שנות חיינו במהירות כמו הבל היוצא מן הפה.",
  "90_10": "ימי שנותינו בהם שבעים שנה, ואם בגבורות – שמונים שנה; ורוב עמלם וגאוותם הוא רק יגיעה ואוון, כי חולפים הם במהירות ואנו עפים ונעלמים.",
  "90_11": "מי יודע ומשיג את מלוא עוצמת אפך? וכמידת היראה הראויה ממך – כך הוא תוקף עברתך.",
  "90_12": "למֵד אותנו לחשב ולמנות את ימינו כראוי, כדי שנביא אל ליבנו חוכמה ובינה.",
  "90_13": "שוב נא, ה'! עד מתי תימשך הרעה? התנחם ורחם על עבדיך.",
  "90_14": "השבע אותנו בבוקר מחסדך ואהבתך, ונרננה ונשמחה בכל ימי חיינו.",
  "90_15": "שמח אותנו כמידת הימים שבהם עינית אותנו, כשנים שבהן ראינו רעה וצער.",
  "90_16": "ייראה ויתגלה אל עבדיך פועלך הגדול, והוד תפארתך ייגלה על בניהם.",
  "90_17": "ויהי נועם ה' אלוהינו שורה עלינו; ומעשה ידינו כונן ובסס עלינו, ומעשה ידינו כוננהו והצליחהו!",
  "91_1": "מי שיושב במחסה ובסתר האל העליון – בצל כנפיו והגנתו של שדי יתלונן וימצא מנוחה.",
  "91_2": "אומר אל ה': 'אתה מחסי ומבצרי, אלוהיי אשר בו אני בוטח!'.",
  "91_3": "כי הוא יציל אותך ממלכודת ציידים סמויה, וממגפת דבר קטלנית והרסנית.",
  "91_4": "באברות כנפיו יסוכך עליך, ותחת כנפיו תמצא מחסה; אמיתו ונאמנותו הן לך מגן ושריון מגן (סוחרה).",
  "91_5": "לא תפחד מאימת הלילה, ולא מחץ הפוגע והעף ביום;",
  "91_6": "לא ממגפת דבר המתהלכת בחשכה, ולא מחורבן ומשחית הפוגע בצהרי היום.",
  "91_7": "ייפול אלף אויבים לצידך ורבבה מימינך – אך אליך הסכנה לא תיגש.",
  "91_8": "רק בעיניך תביט מן הצד, ותראה את גמול ועונש הרשעים.",
  "91_9": "כי אמרת: 'אתה, ה', הוא מחסי!'; את האל העליון שמת למעונך ולמשגבך.",
  "91_10": "לא תארע לך שום רעה, ושום נגע ואסון לא יקרבו אל אוהלך.",
  "91_11": "כי יצווה את מלאכיו עליך, לשמור ולהגן עליך בכל דרכיך.",
  "91_12": "על כפיהם יישאו אותך, פן תינגף ותיפצע רגלך באבן.",
  "91_13": "על שחל (אריה) ופתן ארסי תדרוך ללא חשש, ותרמוס כפיר ותנין.",
  "91_14": "כי אמר ה': 'מכיוון שחשק בי ואהב אותי – אמלט ואציל אותו; ארומם ואבצר אותו כי ידע והכיר את שמי.",
  "91_15": "יקרא אליי ואני אענה לו; עימו אנוכי בכל צרה ומצוקה, אחלץ אותו ואכבד אותו.",
  "91_16": "אורך ימים ושנות חיים אשביע אותו, ואראה לו את ישועתי השלמה!'.",
  "92_1": "מזמור שיר מיוחד ליום השבת:",
  "92_2": "טוב ונעים להודות לה', ולזמר לשמך הנשגב, עליון!",
  "92_3": "להגיד ולספר בבוקר את חסדך, ואת נאמנותך בלילות,",
  "92_4": "בליווי נבל עשור, נבל ורננת כינור נעימה.",
  "92_5": "כי שימחת אותי, ה', במעשי בריאתך; במעשי ידיך ארנן ואשיר בשמחה.",
  "92_6": "מה גדלו ונשגבו מעשיך, ה', ועמוקות מאוד מחשבותיך ותוכניותיך!",
  "92_7": "אדם בַּעַר וחסר דעת אינו יודע זאת, וכסיל אינו מבין את עומק הדבר:",
  "92_8": "כאשר פורחים הרשעים במהירות כמו עשב, ומציצים כל עושי עוול – אין זה אלא כדי שיושמדו וייכרתו לעולמי עד!",
  "92_9": "ואילו אתה, ה', מרומם ונעלה לעד במרומים.",
  "92_10": "כי הנה אויביך, ה', כי הנה אויביך יאבדו; יתפזרו ויתפרקו כל עושי עוול.",
  "92_11": "ותרם כראם גאה את קרני וכוחי; נמשחתי ונתבשמתי בשמן רענן ומחייה.",
  "92_12": "ועיני חזתה במפלת האורבים לי; בשומעי על הקמים עליי מרעים – נפלו פחדיהם.",
  "92_13": "צדיק כתמר יפרח ויישא פרי, כארז הלבנון האדיר ישגשג ויצמח.",
  "92_14": "שתולים ומעורים בבית ה', בחצרות אלוהינו יפריחו וילבלבו.",
  "92_15": "עוד יניבו פרי גם בעת זקנה; דשנים, חזקים ורעננים יהיו,",
  "92_16": "כדי להגיד ולהעיד כי ישר הוא ה' צורי, ואין שום עוול ומשוא פנים בו!",
  "93_1": "ה' מלך על כל היקום, גאות והוד לבש; לבש ה' עוז והתחזר בגבורה, ואף כונן את תבל ביציבות כך שלא תתמוטט.",
  "93_2": "נכון ויציב כיסא מלכותך מעז ומקדם, מעולם ולנצח אתה קיים.",
  "93_3": "הרימו נהרות אדירים, ה', הרימו נהרות את קולם ושאונם; ישאו נהרות את גליהם המתנפצים.",
  "93_4": "אך יותר מקולות מים רבים, יותר ממשברי ים אדירים – אדיר ונשגב ה' במרומים!",
  "93_5": "עדותיך ומצוותיך נאמנות מאוד; לבית מקדשך יאה ונאה קדושה, ה', לאורך ימים ולנצח.",
  "94_1": "אל נקמות ומשפט צדק, ה', אל נקמות הופע והתגלה!",
  "94_2": "התרומם והתנשא, שופט הארץ, והשב גמול ראוי לגאוותנים!",
  "94_3": "עד מתי רשעים, ה', עד מתי רשעים יעלוזו וישמחו בהצלחתם?",
  "94_4": "יביביעו וידברו דברי עתק וחוצפה, יתפארו ויתייהרו כל עושי עוול?",
  "94_5": "את עמך, ה', הם מדכאים ורומסים, ואת נחלתך הם מענים.",
  "94_6": "אלמנה וגר חסרי מגן הם הורגים, ואת היתומים הם רוצחים.",
  "94_7": "ואמרו בליבם: 'לא יראה זאת יה, ולא יבין ויבחין בכך אלוהי יעקב!'.",
  "94_8": "הבינו והתעוררו, אתם הבוערים וחסרי הדעת שבעם; וכסילים – מתי תבינו ותשכילו?",
  "94_9": "האם הנוטע את האוזן לא ישמע? האם היוצר את העין לא יביט ויראה?",
  "94_10": "האם המחנך ומוכיח עמים שלמים לא יוכיח? הרי הוא זה המלמד את האדם דעת וחוכמה!",
  "94_11": "ה' יודע ומכיר את כל מחשבות האדם, כי הבל ושווא הן.",
  "94_12": "אשרי הגבר אשר תייסר ותחנך אותו, יה, ומתוך תורתך תלמד אותו,",
  "94_13": "כדי להעניק לו שלווה ושקט מימי רע, עד אשר ייכרה וייחפר בור מפלתו של הרשע.",
  "94_14": "כי לא ייטוש ה' את עמו, ואת נחלתו לא יעזוב לעולם.",
  "94_15": "כי המשפט ישוב להנהיג בצדק, ואחריו יימשכו וילכו כל ישרי הלב.",
  "94_16": "מי יקום ויעמוד לצידי כנגד עושי רע? מי יתייצב לעזרתי כנגד פועלי עוול?",
  "94_17": "לולא עזרת ה' שהייתה משענת לי – כמעט שכנה נפשי בדומיית הקבר והמוות.",
  "94_18": "כאשר אמרתי בליבי: 'מעדה רגלי ואני נופל' – חסדך ואהבתך, ה', סמכו ותמכו בי.",
  "94_19": "כאשר רבו מחשבותיי המדאיגות וסערות ליבי בקרבי – תנחומיך ורחמיך שעשעו והרגיעו את נפשי.",
  "94_20": "האם יתחבר אליך כיסא שלטון מושחת (הוות), היוצר וגוזר עושק תחת מעטה של חוק?",
  "94_21": "הם מתגודדים ומתנכלים לנפש הצדיק, ודם נקיים מרשיעים למוות.",
  "94_22": "אך ה' היה לי למשגב ולמבצר, ואלוהיי לצור מחסי.",
  "94_23": "והוא ישיב עליהם את עוונם, וברשעותם שלהם ישמיד אותם; ישמידם ויכריתם ה' אלוהינו!",
  "95_1": "לכו ונרננה לה', נריעה בשמחה לצור ישועתנו!",
  "95_2": "נקדים ונקבל את פניו בשיר תודה, ובמזמורים ונגינות נריע לו.",
  "95_3": "כי אל גדול ונשגב הוא ה', ומלך רם מעל כל האלים והמלאכים.",
  "95_4": "אשר בידו מצויים מעמקי תחתיות הארץ, ותועפות ופסגות ההרים שייכות לו.",
  "95_5": "אשר לו שייך הים והוא עשאו, ואת היבשה ידיו יצרו ועיצבו.",
  "95_6": "בואו ונשתחווה ונכרע ברך, נברך ונעבוד לפני ה' עושנו!",
  "95_7": "כי הוא אלוהינו, ואנחנו עם מרעיתו וצאן הנהגתו; הלוואי שהיום בקולו תשמעו!",
  "95_8": "אל תקשו את לבבכם כפי שעשו במריבה, כביום הניסיון במדבר בַּמַּסָּה,",
  "95_9": "שם ניסו ובחנו אותי אבותיכם; בחנו אותי אף על פי שראו את מעשיי ונפלאותיי.",
  "95_10": "ארבעים שנה מאסתי וקצתי בדור ההוא, ואמרתי: 'עם תועי לבב הם, והם לא למדו להכיר את דרכיי'.",
  "95_11": "אשר נשבעתי בכעסי עליהם: אם יבואו ויזכו להיכנס אל מנוחתי (ארץ ישראל)!.",
  "96_1": "שירו לה' שיר חדש, שירו לה' כל יושבי הארץ!",
  "96_2": "שירו לה', ברכו את שמו הקדוש, בשרו מיום ליום את ישועתו.",
  "96_3": "ספרו בקרב הגויים את כבודו, ובכל העמים את מעשי נפלאותיו.",
  "96_4": "כי גדול ה' ומהולל מאוד, נורא ומטיל מורא הוא על כל האלים.",
  "96_5": "כי כל אלוהי העמים הם אלילי שווא ופסלים חסרי ערך, ואילו ה' – הוא שברא את השמיים!",
  "96_6": "הוד והדר מאירים לפניו, עוז ותפארת שוכנים במקדשו.",
  "96_7": "הבו לה', משפחות עמים, הבו לה' כבוד ועוז!",
  "96_8": "הבו לה' את כבוד שמו הראוי לו, שאו מנחה ובואו אל חצרות קודשו.",
  "96_9": "השתחוו לה' בהדרת קודש ובאימה, חילו ורעדו מפניו כל הארץ.",
  "96_10": "אמרו בגויים: 'ה' מלך!'; אף כונן את תבל לבל תמוט, ישפוט עמים בהגינות ובמישור.",
  "96_11": "ישמחו השמיים ותגל הארץ, ירעם הים ומלוא גליו בשאון שבח.",
  "96_12": "יעלוז השדה וכל אשר בו, אז ירננו וישירו כל עצי היער,",
  "96_13": "לפני ה' כי בא, כי בא לשפוט את הארץ; ישפוט תבל בצדק, ועמים באמונתו ובנאמנותו.",
  "97_1": "ה' מלך – תגל ותשמח הארץ, ישמחו איים רבים מסביב!",
  "97_2": "ענן וערפל סובבים אותו, צדק ומשפט הם יסוד ומכון כיסאו.",
  "97_3": "אש הולכת לפניו, ומלהטת ומכלה סביב את אויביו.",
  "97_4": "האירו ברקיו את כל תבל; ראתה הארץ ותרעד.",
  "97_5": "הרים נמסו כמו דונג שעווה מלפני ה', מלפני אדון כל הארץ.",
  "97_6": "הגידו והכריזו השמיים את צדקו, וראו כל העמים את כבודו הנשגב.",
  "97_7": "יבושו כל עובדי פסילים המתהללים באלילי שווא; השתחוו לו כל כוחות המרום (אלוהים).",
  "97_8": "שמעה ציון ותשמח, ותגלנה בנות יהודה למשמע משפטיך הצודקים, ה'.",
  "97_9": "כי אתה, ה', עליון ונשגב על כל הארץ; נעלית מאוד מעל כל האלים.",
  "97_10": "אוהבי ה', שנאו את הרע! הוא שומר את נפשות חסידיו, ומיד רשעים יציל אותם.",
  "97_11": "אור זרוע וצומח לצדיק, וליישרי לב נטועה שמחה עמוקה.",
  "97_12": "שמחו, צדיקים, בה', והודו לזכר קודשו הנצחי!",
  "98_1": "מזמור שיר: שירו לה' שיר חדש, כי נפלאות וניסים עשה; הושיעה לו יד ימינו וזרוע קודשו האדירה.",
  "98_2": "הודיע ה' את ישועתו; לעיני הגויים כולם גילה את צדקתו.",
  "98_3": "זכר את חסדו ואת אמונתו הנאמנת לבית ישראל; ראו כל אפסי הארץ את ישועת אלוהינו.",
  "98_4": "הריעו לה' כל הארץ, פצחו בשיר, רננו וזמרו!",
  "98_5": "זמרו לה' בכינור, בכינור ובקול זמרה נעימה.",
  "98_6": "בחצוצרות ובקול שופר הריעו לפני המלך ה'!",
  "98_7": "ירעם הים ומלואו הגועש, תבל וכל יושביה.",
  "98_8": "נהרות ימחאו כף יחד, והרים ירננו וישירו בשמחה,",
  "98_9": "לפני ה' כי בא לשפוט את הארץ; ישפוט תבל בצדק ויושר, ועמים במישור ובהגינות.",
  "99_1": "ה' מלך – ירגזו ויחרדו עמים; יושב על כרובים – תנוע ותרעד הארץ.",
  "99_2": "ה' בציון גדול ונשגב, ורם הוא מעל כל העמים.",
  "99_3": "יודו וישבחו את שמך הגדול והנורא – קדוש הוא!",
  "99_4": "ועוז וכוח המלך אוהב משפט וצדק; אתה כוננת מישרים, משפט וצדקה ביעקב אתה עשית.",
  "99_5": "רוממו את ה' אלוהינו והשתחוו להדום רגליו – קדוש הוא!",
  "99_6": "משה ואהרון בכוהניו, ושמואל בקוראי שמו – קוראים היו אל ה', והוא ענה להם.",
  "99_7": "בעמוד ענן דיבר אליהם; שמרו את עדותיו ואת החוק אשר נתן להם.",
  "99_8": "ה' אלוהינו, אתה ענית להם; אל סולח ומוחל היית להם, אף שפרעת וגבית על עלילותיהם הרעות.",
  "99_9": "רוממו את ה' אלוהינו והשתחוו להר קודשו, כי קדוש הוא ה' אלוהינו!",
  "100_1": "מזמור של הודיה: הריעו בשמחה לה', כל יושבי הארץ!",
  "100_2": "עבדו את ה' בשמחה ובלב טוב, בואו לפניו ברינה ובשירי הלל.",
  "100_3": "דעו והפנימו כי ה' הוא האלוהים; הוא עשׂנו ולו אנו שייכים, עמו וצאן מרעיתו.",
  "100_4": "בואו בשעריו בתודה ובחצרותיו בתהילה; הודו לו, ברכו את שמו הקדוש!",
  "100_5": "כי טוב ה', לעולם קיים חסדו, ועד דור ודור נמשכת אמונתו ונאמנותו.",
  "101_1": "לדוד מזמור: חסד ומשפט ישר אשירה; לך, ה', אזמרה.",
  "101_2": "אשכיל ואתבונן בדרך תמימה וישרה – מתי תבוא אליי לעזרני? אתנהל בתום ליבי בתוך ביתי.",
  "101_3": "לא אציב לנגד עיניי שום דבר בליעל ומעשה שחיתות; שנאתי את מעשי הסוטים מן הדרך, דבר מזה לא יידבק בי.",
  "101_4": "לב עקש ומעוות יסור ממני; אדם רע ומעשה רע לא אכיר ולא אקבל.",
  "101_5": "את מי שמלשין בסתר על חברו – אכרית ואשתיק; אדם גבה עיניים ובעל לב רחב וגאוותן – אותו לא אוכל לשאת.",
  "101_6": "עיני נשואות בחיבה אל נאמני הארץ כדי שיישבו עימדי; ההולך בדרך תמימה וישרה – הוא ישרת אותי.",
  "101_7": "לא יישב בתוך ביתי עושה רמייה ומרמה; דובר שקרים לא יכון ולא יישאר מול עיניי.",
  "101_8": "מדי בוקר אשמיד ואכרית את כל רשעי הארץ, כדי לכרות מעיר ה' את כל פועלי עוול.",
  "102_1": "תפילה לעני ומדוכא כאשר נפשו מתעטפת ביגון, ולפני ה' הוא שופך את שיחו וצערו:",
  "102_2": "ה', שמעה נא תפילתי, ושוועתי וזעקתי תבוא אליך.",
  "102_3": "אל תסתיר את פניך ממני ביום צרתי; הטה אליי את אוזנך, ביום שבו אקרא – מהר וענה לי!",
  "102_4": "כי כלו ונעלמו כעשן ימיי, ועצמותיי נחרכו ויבשו כמו מוקד אש.",
  "102_5": "הוכה כמו עשב ויבש ליבי, עד ששכחתי אפילו לאכול את לחמי מרוב צער.",
  "102_6": "מקול אנחתי הכבדה, נדבקה עצמי לבשרי מרזון ומחולשה.",
  "102_7": "דמיתי לקאת עוף המדבר השומם, הייתי כמו כוס חורבות השוכן במקומות חרבים.",
  "102_8": "שקדתי והייתי ער ללא שינה, והייתי כמו ציפור בודדה על גג הבית.",
  "102_9": "כל היום חירפו אותי אויביי; המתהוללים והלועגים לי נשבעים בשמי לקללה.",
  "102_10": "כי אפר במקום לחם אכלתי, ואת משקאותיי מסכתי ועירבתי בדמעותיי,",
  "102_11": "בגלל זעמך וקצפך, כי הרמת אותי מעלה ואז השלכת אותי מטה בעוצמה.",
  "102_12": "ימיי דומים לצל הנטוי לעת ערב, ואני עצמי מתייבש כמו עשב.",
  "102_13": "ואתה, ה', לעולם תשב ותמלוך, וזכרך קיים לדור ודור.",
  "102_14": "אתה תקום ותרחם על ציון, כי הגיעה השעה לחוננה, כי בא המועד שנקבע!",
  "102_15": "כי עבדיך רצו ואהבו את אבניה של ציון, ואת עפרה הם מחוננים ומנשקים בחיבה.",
  "102_16": "וייראו הגויים את שם ה', וכל מלכי הארץ את כבודך הנשגב,",
  "102_17": "כאשר יבנה ה' את ציון מחדש, וייראה בהוד כבודו ותפארתו.",
  "102_18": "פנה אל תפילת הערער והגלמוד, ולא ביזה והשפיל את תפילתם.",
  "102_19": "ייכתב הדבר ויירשם למען הדור האחרון, ועם שעתיד להיברא יהלל וישבח את יה:",
  "102_20": "כי השקיף ה' ממרום קודשו, משמיים הביט אל הארץ,",
  "102_21": "לשמוע את אנקת האסיר והשבוי, לשחרר ולהתיר את בני התמותה הנידונים למוות,",
  "102_22": "כדי לספר בציון את שם ה', ואת תהילתו ושבחו בירושלים,",
  "102_23": "בהתקבץ עמים וממלכות יחדיו, כדי לעבוד את ה'.",
  "102_24": "התיש בדרך את כוחי, קיצר את ימי חיי.",
  "102_25": "אמרתי: 'אלוהיי, אל תיקח אותי בחצי ימיי! שנותיך הרי נמשכות לדור דורים'.",
  "102_26": "לפנים ייסדת וכוננת את הארץ, ומעשה ידיך הם השמיים.",
  "102_27": "הם יאבדו ויכלו ואתה תעמוד ותישאר; וכולם כבגד ישנים ומתבלים, כלבוש תחליף אותם והם יחלפו,",
  "102_28": "ואתה הוא אותו אל נצחי תמיד, ושנותיך לא ייתמו לעולם!",
  "102_29": "בני עבדיך ישכנו לבטח, וזרעם לפניך יכון ויתקיים לעד.",
  "103_1": "לדוד: ברכי, נפשי, את ה', וכל איבריי הפנימיים – ברכו את שם קודשו!",
  "103_2": "ברכי, נפשי, את ה', ואל תשכחי שום חסד מכל גמוליו וטובותיו;",
  "103_3": "הסולח לכל עוונותייך, הרופא את כל תחלואייך ומחלותייך;",
  "103_4": "הגואל מבור שחת ואבדון את חייך, המעטר אותך בחסד וברחמים רבים;",
  "103_5": "המשביע בטוב את נפשך וזקנתך (עֶדְיֵךְ), ומתחדשת כנשר נעורייך.",
  "103_6": "עושה צדקות ה' ומשפטים צודקים לכל העשוקים והנדכאים.",
  "103_7": "הודיע את דרכיו למשה, לבני ישראל את מעשי עלילותיו ונפלאותיו.",
  "103_8": "רחום וחנון ה', מאריך אפו ורב חסד ואהבה.",
  "103_9": "לא לנצח יריב ויוכיח, ולא לעולם ייטור וישמור כעסו.",
  "103_10": "לא לפי חטאינו עשה לנו, ולא כפי גמול עוונותינו שילם לנו.",
  "103_11": "כי כגובה השמיים מעל הארץ – כך גבר ונעלה חסדו על יראיו.",
  "103_12": "כרחוק מזרח ממערב – כך הרחיק מאיתנו את פשעינו.",
  "103_13": "כרחם אב אוהב על בניו – כך ריחם ה' על יראיו הנאמנים.",
  "103_14": "כי הוא יודע ומכיר את יצרנו ומבנה גופנו, זכור כי עפר אנחנו.",
  "103_15": "האדם – כעשב ימיו, כפרח השדה הפורח לרגע כך יציץ;",
  "103_16": "כי רוח סערה עוברת בו והוא איננו, ומקומו לא יכירנו עוד.",
  "103_17": "אך חסד ה' מעולם ועד עולם על יראיו, וצדקתו עומדת לבני בנים,",
  "103_18": "לשומרי בריתו הנאמנים, ולזוכרי מצוותיו ופקודיו כדי לקיימם.",
  "103_19": "ה' בשמיים הכין וביסס את כיסא כבודו, ומלכותו מושלת בכל הבריאה כולה.",
  "103_20": "ברכו את ה', מלאכיו גיבורי הכוח עושי דברו, הנשמעים לקול דברו!",
  "103_21": "ברכו את ה', כל צבאות מרומיו, משרתיו העושים את רצונו הטוב!",
  "103_22": "ברכו את ה', כל מעשיו ויצוריו בכל מקומות ממשלתו; ברכי, נפשי, את ה'!",
  "104_1": "ברכי, נפשי, את ה'! ה' אלוהיי, גדלת מאוד; הוד והדר לבשת!",
  "104_2": "עוטה אור בהיר כשללמה וכבגד, נוטה את שמי המרום כיריעת אוהל רחבה.",
  "104_3": "הבונה במים העליונים את עליותיו, שם עננים כמרכבתו, מהלך על כנפי רוח סערה.",
  "104_4": "עושה רוחות להיות שליחיו ומלאכיו, אש לוהטת למשרתיו הנאמנים.",
  "104_5": "ייסד את הארץ על בסיסיה ומכוניה היציבים, שלא תתמוטט לעולמי עד.",
  "104_6": "תהום עמוקה כבגד כיסיתָה, מעל להרים עמדו מים רבים.",
  "104_7": "מגערתך ברחו ונסוגו המים, מקול רעמך נחפזו ונסו במהירות.",
  "104_8": "עלו הרים ושקעו בקעות, אל המקום אשר ייסדת וקבעת להם.",
  "104_9": "גבול שמת למים שלא יעברו אותו, ולא ישובו לכסות ולהציף את הארץ.",
  "104_10": "המשלח מעיינות מפכים בנחלים, בין ההרים הם זורמים ומהלכים.",
  "104_11": "משקים כל חיית השדה, ישברו ערודים (חמורי בר) את צימאונם.",
  "104_12": "עליהם ישכנו עופות השמיים, מבין ענפי העצים ישמיעו קולם בשיר.",
  "104_13": "משקה הרים מעליותיו שבשמיים; מפרי מעשיך תשבע ותרבה הארץ.",
  "104_14": "מצמיח עשב וחציר לבהמה, וצמחים ועשבים לתועלת ולעבודת האדם, כדי להוציא לחם ומזון מן הארץ;",
  "104_15": "ויין המשמח את לב האדם, להצהיל ולהאיר פנים יותר משמן, ולחם המזין וסועד את לב האנוש.",
  "104_16": "ישבעו וירוו עצי ה', ארזי הלבנון אשר נטע לתפארת,",
  "104_17": "אשר שם ציפורים יקננו; החסידה – עצי ברוש הם ביתה ומשכנה.",
  "104_18": "הרים גבוהים הם מעון ליעלים, והסלעים הם מחסה לשפני הסלע.",
  "104_19": "עשה את הירח לקבוע מועדים וזמנים; השמש יודעת את שעת מבואה ושקיעתה.",
  "104_20": "תשת חושך ויהי לילה, שבו רוחשות ומשוטטות כל חיות היער.",
  "104_21": "הכפירים שואגים לטרף, ולבקש מאל את מזונם.",
  "104_22": "תזרח השמש – הם נאספים ונחבאים, ואל מאורותיהם ירבצו.",
  "104_23": "יוצא האדם לפועלו ולעבודתו, ולעמלו עד בוא הערב.",
  "104_24": "מה רבו ועצמו מעשיך, ה'! כולם בחוכמה עילאית עשית; מלאה הארץ כולה ביציריך ובקניינך!",
  "104_25": "זה הים הגדול ורחב הידיים – שם שורצים יצורים לאין מספר, חיות קטנות עם גדולות.",
  "104_26": "שם אוניות מהלכות, ולווייתן זה אשר יצרת לשחק בו במרחביו.",
  "104_27": "כולם אליך ישברו ומייחלים, שתיתן את אוכלם ומזונם בעתו.",
  "104_28": "תיתן להם – הם מלקטים ואוספים; תפתח את ידך – ישבעו כל טוב.",
  "104_29": "תסתיר פניך – ייבהלו ויחרדו; תאסוף את רוח חייהם – יגוועו ואל עפרם ישובו.",
  "104_30": "תשלח רוחך – ייבראו מחדש, ותחדש את פני האדמה ברעננות.",
  "104_31": "יהי כבוד ה' לעולם! ישמח ה' במעשיו ובברואיו!",
  "104_32": "המביט אל הארץ ותרעד, ייגע בהרים ויעשנו עשן.",
  "104_33": "אשירה לה' בכל ימי חיי, אזמרה לאלוהיי בעודי קיים.",
  "104_34": "יהי ערב ונעים לו שיחי ומחשבותיי; אנוכי אשמח ואגל בה'.",
  "104_35": "ייתמו וייעלמו החטאים מן הארץ, ורשעים עוד לא יהיו; ברכי, נפשי, את ה' – הללויה!",
  "105_1": "הודו לה', קראו בשמו, פרסמו בעמים את מעלליו ונפלאותיו!",
  "105_2": "שירו לו, זמרו לו, שוחחו בכל נפלאותיו הגדולות.",
  "105_3": "התפארו בשם קודשו; ישמח לב מבקשי ה'!",
  "105_4": "דרשו את ה' ואת עוזו, בקשו את פניו תמיד.",
  "105_5": "זכרו את נפלאותיו אשר עשה, מופתיו ומשפטי פיו הצודקים,",
  "105_6": "זרע אברהם עבדו הנאמן, בני יעקב בחיריו!",
  "105_7": "הוא ה' אלוהינו; בכל הארץ כולה תקפים משפטיו.",
  "105_8": "זכר לעולם את בריתו הנצחית, דבר אשר ציווה לאלף דור,",
  "105_9": "אשר כרת וקבע עם אברהם, ושבועתו ליצחק,",
  "105_10": "ויעמידה ליעקב לחוק וקביעות, לישראל לברית עולם,",
  "105_11": "לאמור: 'לך אתן את ארץ כנען, חבל נחלתכם',",
  "105_12": "בהיותם אנשי מספר מועטים, כמעט בודדים וגרים זרים בתוכה.",
  "105_13": "והתהלכו מגוי אל גוי, מממלכה אחת אל עם אחר.",
  "105_14": "לא הניח לאיש לעשוק אותם, והוכיח מלכים רבי כוח למענם:",
  "105_15": "'אל תיגעו במשיחיי ובבחירי, ולנביאיי אל תרעו!'.",
  "105_16": "וקרא רעב על הארץ, כל מטה לחם ומשען שבר וחיסל.",
  "105_17": "שלח לפניהם איש להכין הצלה – לעבד נמכר יוסף.",
  "105_18": "עינו בכבלים את רגלו, בברזל נכנסה נפשו,",
  "105_19": "עד בוא העת שהתגשם דברו וחלומו; אמרת ה' צרפה וביררה אותו.",
  "105_20": "שלח מלך מצרים ויתיר אותו, מושל עמים ושחרר אותו ממאסרו.",
  "105_21": "שם אותו לאדון על ביתו, ולמושל על כל קניינו ונכסיו,",
  "105_22": "לאסור ולהדריך את שריו כרצונו, ואת זקניו ויועציו ללמד חוכמה.",
  "105_23": "ויבוא ישראל למצרים, ויעקב התגורר כגר בארץ חם.",
  "105_24": "והפרה והרבה את עמו מאוד, ועשה אותו חזק ועצום יותר מאויביו ומצורריו.",
  "105_25": "הפך את לב המצרים לשנוא את עמו, להתנכל ולהערים על עבדיו.",
  "105_26": "שלח את משה עבדו הנאמן, ואת אהרון אשר בחר בו.",
  "105_27": "שמו בקרבם את דברי אותותיו, ומופתים ופלאים בארץ חם.",
  "105_28": "שלח חושך והחשיך, ולא המרו את דבריו.",
  "105_29": "הפך את מימיהם לדם, והמית את דגתם.",
  "105_30": "שרצה ארצם צפרדעים בהמוניהן, אפילו בחדרי מלכיהם.",
  "105_31": "אמר ובא ערוב חיות רעות, וכינים בכל גבולותיהם.",
  "105_32": "נתן גשמיהם לברד כבד, ואש להבות בארצם.",
  "105_33": "והיכה גפנם ותאנתם, ושיבר את עצי גבולם.",
  "105_34": "אמר ובא ארבה רב, וילק חסר מספר,",
  "105_35": "ויאכל כל עשב בארצם, ויאכל את פרי אדמתם.",
  "105_36": "והיכה כל בכור בארצם, ראשית כל אונם וכוחם.",
  "105_37": "ויוציא אותם בכסף ובזהב, ולא היה בשבטיו אדם כושל ונחשל.",
  "105_38": "שמח מצרים בצאתם, כי נפל פחדם ואימתם עליהם.",
  "105_39": "פרש ענן למסך ולהצללה, ואש להאיר בלילה.",
  "105_40": "שאל העם והביא שלווים, ולחם שמיים (מן) השביע אותם.",
  "105_41": "פתח צור סלע ויזובו מים, הלכו בציה כנהר שוטף.",
  "105_42": "כי זכר את דבר קודשו והבטחתו, את אברהם עבדו הנאמן.",
  "105_43": "ויוציא את עמו בששון ושמחה, ברינה את בחיריו.",
  "105_44": "וייתן להם ארצות גויים, ועמל ורכוש לאומים ירשו,",
  "105_45": "וזאת בעבור שישמרו את חוקיו, ואת תורותיו ומצוותיו ינצרו – הללויה!",
  "106_1": "הללויה! הודו לה' כי טוב, כי לעולם חסדו!",
  "106_2": "מי ימלל ויביע את גבורות ה'? מי ישמיע את כל תהילתו ושבחו?",
  "106_3": "אשרי שומרי משפט וצדק, עושי צדקה בכל עת.",
  "106_4": "זכרני, ה', ברצון ובחיבה שאתה נוטה לעמך; פקוד אותי בישועתך,",
  "106_5": "כדי לראות בטובת בחיריך, לשמוח בשמחת אומתך, ולהתפאר עם נחלתך.",
  "106_6": "חטאנו עם אבותינו, העווינו והרשענו מעשינו.",
  "106_7": "אבותינו במצרים לא השכילו ולא התבוננו בנפלאותיך, לא זכרו את רוב חסדיך, והמרו ומרדו על הים – בים סוף.",
  "106_8": "ויושיעם למען שמו הנשגב, כדי להודיע ולפרסם את גבורתו.",
  "106_9": "ויגער בים סוף וייחרב, ויוליכם במעמקי התהומות כאילו הלכו במדבר יבש.",
  "106_10": "ויושיעם מיד השונא המצרי, ויגאלם מיד האויב הרודף.",
  "106_11": "ויכסו מים שוצפים את צורריהם; אחד מהם לא נותר חי.",
  "106_12": "ואז האמינו בדבריו ובהבטחותיו, ושרו את שיר תהילתו.",
  "106_13": "אך מהרו שכחו את מעשיו וניסיו, ולא חיכו לעצתו ולהדרכתו.",
  "106_14": "ויתאוו תאווה יתרה במדבר, וינסו ויבחנו את האל בארץ ציה ושממה.",
  "106_15": "וייתן להם את שאלתם ותאוותם, אך שילח רזון ומגפה בנפשם.",
  "106_16": "ויקנאו במשה במחנה, ובאהרון קדוש ה'.",
  "106_17": "נפתחה הארץ ותבלע את דתן, ותכס ותקבור את עדת אבירם.",
  "106_18": "ותבער אש בעדתם, להבה לוהטת ליחכה ושרפה רשעים.",
  "106_19": "יעשו עגל מסכה בחורב, וישתחוו לפסל יצוק.",
  "106_20": "וימירו את כבודם ואלוהיהם בתבנית שור אוכל עשב.",
  "106_21": "שכחו את האל המושיע אותם, שעשה מעשים גדולים במצרים,",
  "106_22": "נפלאות בארץ חם, ונוראות על ים סוף.",
  "106_23": "ויאמר להשמידם, לולא משה בחירו עמד בפרץ לפניו, להשיב את חמתו מהשחיתם כליל.",
  "106_24": "וימאסו בארץ חמדה וטובה (ארץ כנען), לא האמינו לדברו ולהבטחתו.",
  "106_25": "וירגנו והתלוננו באוהליהם, לא שמעו בקול ה'.",
  "106_26": "ויישא ידו בשבועה עליהם, להפיל אותם ולכלותם במדבר,",
  "106_27": "ולהפיל את זרעם בגויים, ולזרותם בארצות.",
  "106_28": "וייצמדו ונתחברו לבעל פעור בעבודה זרה, ויאכלו מזבחי מתים ואלילים.",
  "106_29": "ויכעיסו במעלליהם הרעים, ותפרוץ בהם מגפה קטלנית.",
  "106_30": "ויעמוד פינחס ויעשה פלילות ודין בקנאותו, ותיעצר המגפה.",
  "106_31": "ותיחשב לו המעשה הזה לצדקה ולזכות, לדור ודור עד עולם.",
  "106_32": "ויקציפו והכעיסו אותו על מי מריבה, וירע למשה בעבורם,",
  "106_33": "כי המרו את רוחו וסבלנותו, ויבטא ודיבר בחוסר זהירות בשפתיו.",
  "106_34": "לא השמידו את העמים הכנעניים, אשר אמר וציווה ה' להם,",
  "106_35": "ויתערבו בגויים אלה, וילמדו ממעשיהם המקולקלים.",
  "106_36": "ויעבדו את עצביהם ואליליהם, והיו להם למלכודת ולמוקש.",
  "106_37": "ויזבחו את בניהם ואת בנותיהם לשדים ולעבודה זרה.",
  "106_38": "וישפכו דם נקיים, דם בניהם ובנותיהם אשר זבחו לפסילי כנען, ותחנף ותטמא הארץ בדמים.",
  "106_39": "ויטמאו במעשיהם הרעים, ויזנו וסטו במעלליהם.",
  "106_40": "וייחר אף ה' בעמו, ויתעב וימאס את נחלתו.",
  "106_41": "וייתנם ביד גויים עוינים, וימשלו בהם שונאיהם.",
  "106_42": "וילחצו אותם אויביהם, ויוכנעו תחת ידם המעיקה.",
  "106_43": "פעמים רבות הציל וחילץ אותם, והמה ימרו בעצתם הרעה, ויימקו וירדו בעוונם.",
  "106_44": "וירא בצר להם ברחמיו, בשומעו את רינתם וצעקתם.",
  "106_45": "ויזכור להם את בריתו, ויינחם וריחם כרוב חסדיו ואהבתו.",
  "106_46": "וייתן אותם לרחמים, לפני כל שוביהם ומעניהם.",
  "106_47": "הושיענו, ה' אלוהינו, וקבצנו מן הגויים, להודות לשם קודשך, ולהשתבח ולהתפאר בתהילתך!",
  "106_48": "ברוך ה' אלוהי ישראל, מן העולם ועד העולם! ואמר כל העם: אמן! הללויה!",
  "107_1": "הודו לה' כי הוא טוב, כי לעולם ועד עומד חסדו הנאמן!",
  "107_2": "יאמרו זאת גאולי ה', אשר פדה והציל אותם מיד האויב והמצוקה,",
  "107_3": "ומארצות שונות אסף וקיבץ אותם: ממזרח וממערב, מצפון ומים הדרומי.",
  "107_4": "תעו במדבר בדרך שממה וישימון, עיר יישוב ומגורים לא מצאו.",
  "107_5": "היו רעבים וגם צמאים, עד שנפשם עטפה בהם מחולשה ומצער.",
  "107_6": "ויצעקו אל ה' במצוקתם, ומכל מצוקותיהם הציל וחילץ אותם.",
  "107_7": "וידריך אותם בדרך ישרה ובטוחה, ללכת אל עיר יישוב וחיים.",
  "107_8": "יודו לה' על חסדו הגדול, ועל נפלאותיו ומעשיו המופלאים לבני אדם!",
  "107_9": "כי השביע נפש שוקקת וצמאה, ונפש רעבה מילא בטוב.",
  "107_10": "יושבים בחושך ובצלמוות, כבולים בעוני ובכבלי ברזל,",
  "107_11": "מפני שהמרו את אמרי אל, ואת עצת אל עליון ביזו וזלזלו.",
  "107_12": "ויכנע בעמל ובייסורים את ליבם; כשלו ונפלו ואין איש עוזר.",
  "107_13": "ויזעקו אל ה' בצר להם, וממצוקותיהם הושיע אותם.",
  "107_14": "יוציאם מחושך ומצלמוות, ואת כבליהם ומוסרותיהם ניתק ושבר.",
  "107_15": "יודו לה' על חסדו, ועל נפלאותיו לבני אדם!",
  "107_16": "כי שיבר דלתות נחושת כבדות, ובריחי ברזל גדע ושיבר.",
  "107_17": "אוילים וסוררים מדרכי פשעם, ומעוונותיהם סובלים ייסורים ומחלות.",
  "107_18": "כל מאכל ומוזן תתעב נפשם מרוב חולי, והגיעו עד שערי מוות.",
  "107_19": "ויזעקו אל ה' בצר להם, וממצוקותיהם הושיע אותם.",
  "107_20": "ישלח דברו וירפאם מכל חוליים, וימלט אותם מבורות שחת ואבדון.",
  "107_21": "יודו לה' על חסדו, ועל נפלאותיו לבני אדם!",
  "107_22": "ויזבחו זבחי תודה, ויספרו את מעשיו ברינה ובשיר.",
  "107_23": "יורדי הים באוניות מסע, עושי מלאכה ומסחר במים רבים ואדירים,",
  "107_24": "המה ראו את מעשי ה', ואת נפלאותיו במעמקי מצולות.",
  "107_25": "ויאמר ויעמד רוח סערה, ותרמם את גלי הים מעלה.",
  "107_26": "יעלו שמימה וירדו תהומות, נפשם ברעה ופחד תתמוגג ותימס.",
  "107_27": "יחוגו ויתנועעו כשיכור מאובדן שליטה, וכל חוכמת הספנות שלהם אובדת ונבלעת.",
  "107_28": "ויצעקו אל ה' בצר להם, וממצוקותיהם יוציא אותם.",
  "107_29": "יקם וישקיט סערה לדממה, ויחשו ויירגעו גלי הים.",
  "107_30": "וישמחו כי שתקו ונרגעו הגלים, וינחה אותם אל מחוז חפצם בשלום.",
  "107_31": "יודו לה' על חסדו, ועל נפלאותיו לבני אדם!",
  "107_32": "וירוממוהו בקהל עם מתכנס, ובמושב זקנים וראשי העדה יהללוהו.",
  "107_33": "שם נהרות שופעים למדבר יבש, ומוצאי מים למקום צמאון וחול;",
  "107_34": "ארץ פרי ושפע לשממת מלחה, בגלל רעת האנשים היושבים בה.",
  "107_35": "שם מדבר ציה לאגם מים, וארץ יבשה למוצאי מעיינות;",
  "107_36": "ויושב שם רעבים ומחוסרי כל, ויכוננו ויבנו עיר מושב מיושבת,",
  "107_37": "ויזרעו שדות וייטעו כרמים, ויעשו פרי תבואה בשפע רב.",
  "107_38": "ויברכם וירבו מאוד, ואת בהמתם לא ימעיט.",
  "107_39": "ואף אם יתמעטו ויושפלו מעוצר, מרעה ומיגון –",
  "107_40": "שופך בוז על נדיבים ורוזנים, ומתעה אותם בתוהו ושממה ללא דרך מוצא;",
  "107_41": "ומשגב ומרומם עני ומדוכא ממצוקתו, ושם את משפחותיו מרובות כעדר צאן.",
  "107_42": "יראו ישרים וישמחו, וכל עוולה ורשעה תקפוץ ותסגור את פיה.",
  "107_43": "מי חכם וישמור ויתבונן באלה – ויבינו את מעשי חסדי ה'!",
  "108_1": "שיר מזמור שחיבר דוד:",
  "108_2": "נכון ויציב ליבי, אלוהים; אשיר ואזמר בכל כבודי ונשמתי.",
  "108_3": "התעוררו, נבל וכינור! אעיר ואקדים את עלות השחר בשיריי.",
  "108_4": "אודה לך בין העמים, ה', ואזמר לך בין הלאומים.",
  "108_5": "כי גדול מעל שמיים חסדך, ועד ענני השחקים מגיעה אמתך ונאמנותך.",
  "108_6": "התרומם מעל השמיים, אלוהים, ועל כל הארץ כולה יזרח כבודך!",
  "108_7": "כדי שייחלצו וישמחו ידידיך האהובים – הושע ביד ימינך וענני!",
  "108_8": "אלוהים דיבר בקודשו: אעלוזה ואשמח, אחלק את שכם ואת עמק סוכות אמדוד לחלוקה;",
  "108_9": "לי שייך הגלעד ולי מנשה, ואפרים הוא מבצר ראשי, ויהודה הוא מקור מחוקקיי והנהגתי;",
  "108_10": "מואב היא סיר רחצתי הכנוע, על אדום אשליך את נעלי לאות כיבוש, ועל פלשת אריע בניצחון!",
  "108_11": "מי יוביל אותי אל עיר מבצר בצורה? מי ינחני ויביאני עד אדום?",
  "108_12": "האם לא אתה, אלוהים, אשר זנחתנו, ולא יצאת עם צבאותינו למערכה?",
  "108_13": "הענק לנו עזרה מול האויב והצר, כי שווא והבל היא תשועת אדם בשר ודם.",
  "108_14": "באלוהים נעשה חיל וגבורה, והוא יבוס וירמוס את צוררינו!",
  "109_1": "למנצח, לדוד מזמור: אלוהי תהילתי ושבחי, אל תחריש ואל תשתוק!",
  "109_2": "כי פי רשע ופי מרמה פתחו עליי, דיברו איתי בלשון של שקר והשמצה.",
  "109_3": "ודברי שנאה הקיפו אותי סביב, ונלחמו בי ללא שום סיבה ועילה.",
  "109_4": "תחת אהבתי הם משטנים ומאשימים אותי, ואילו אני – כולי תפילה ותחינה.",
  "109_5": "וישימו עליי רעה תחת טובה, ושנאה תחת אהבה שרחשתי להם.",
  "109_6": "הפקד עליו שופט רשע שיחמיר בדינו, ומקטרג יעמוד לימינו להאשימו.",
  "109_7": "בהישפטו ייצא חייב ורשע בדין, ותפילתו תיחשב לחטא ולעוון.",
  "109_8": "יהיו ימיו מעטים וקצרים, ואת תפקידו ומשרתו ייקח אדם אחר.",
  "109_9": "יהיו בניו יתומים, ואשתו אלמנה גלמודה.",
  "109_10": "ונדוד ינודו בניו ויקבצו נדבות, וידרשו לחם מתוך חורבותיהם החרבות.",
  "109_11": "ינקוף וייטול המלווה בריבית את כל אשר לו, ויבוזו זרים את פרי יגיעו ועמלו.",
  "109_12": "אל יהי לו אדם המושך לו חסד, ואל יהי חונן ומרחם על יתומיו.",
  "109_13": "תהי אחריתו וזרעו להכרת, בדור הבא יימחה שמם כליל.",
  "109_14": "ייזכר עוון אבותיו לפני ה', וחטאת אמו אל תימחה.",
  "109_15": "יהיו נגד עיני ה' תמיד, ויכרות מן הארץ את זכרם.",
  "109_16": "מפני אשר לא זכר לעשות חסד ורחמים, ורדף איש עני ואביון ונדכא לבב כדי להמיתו.",
  "109_17": "ואהב קללה – ותבוא עליו; לא חפץ בברכה – ותרחק ממנו.",
  "109_18": "וילבש קללה כלבושו, ותבוא כמים לקרביו וכשמן החודר לעצמותיו.",
  "109_19": "תהי לו כבגד שבו הוא מתעטף, ולחגורה שבה הוא נחגר תמיד.",
  "109_20": "זוהי פעולת וגמול שוטניי מאת ה', והדוברים רע על נפשי.",
  "109_21": "ואתה, אלוהים ה', עשה עימי חסד למען שמך; כי טוב חסדך, הצילני!",
  "109_22": "כי עני ואביון אנוכי, וליבי פצוע וחלל בקרבי.",
  "109_23": "כצל הנטוי לעת ערב נהלכתי ונעלמתי, ננערתי וטולטלתי כמו ארבה ברוח.",
  "109_24": "ברכיי כשלו מרוב צום, ובשרי כחש ורזה מאין שומן.",
  "109_25": "ואני הייתי חרפה ומושא ללעג להם; יראו אותי ויניעו את ראשם בבוז.",
  "109_26": "עזרני, ה' אלוהיי; הושיעני כפי מידת חסדך ואהבתך!",
  "109_27": "ויידעו כי ידך וגבורתך היא זאת; אתה, ה', עשית זאת!",
  "109_28": "הם יקללו – ואתה תברך! קמו עליי וייבושו, ועבדך ישמח וירנן.",
  "109_29": "ילבשו שוטניי כלימה ובושה, ויתעטפו כמעיל בבושתם שלהם.",
  "109_30": "אודה לה' מאוד בפי, ובתוך המון רב אהללנו,",
  "109_31": "כי יעמוד לימין אביון וחסר מגן, להושיעו מאלה השופטים ודנים את נפשו למוות.",
  "110_1": "לדוד מזמור: אמר ה' לאדוני המלך: שב לימיני, עד אשר אשית ואכניע את אויביך להיות הדום לרגליך.",
  "110_2": "מטה עוזך ושלטונך ישלח ה' מציון; רדה ומשול בקרב אויביך!",
  "110_3": "עמך יתנדב בהתלהבות ביום גיוס חילך, בהדרי קודש; מרחם השחר לך טל ילדותך ונעוריך.",
  "110_4": "נשבע ה' ולא יתחרט: אתה כהן ומנהיג לעולם, על פי סדר ומעלת מלכי-צדק.",
  "110_5": "אדוני על יד ימינך מחזקך; מחץ והביס מלכים רבי כוח ביום זעמו.",
  "110_6": "ידין וישפוט בגויים, ימלא את שדה הקרב גוויות חללים, מחץ ראשי שליטים על ארץ רבה.",
  "110_7": "מנחל מים בדרך ישתה כדי להרוות צמאונו, על כן ירים ראש בניצחון ובגאון.",
  "111_1": "הללויה! אודה לה' בכל לבב, בסוד אנשים ישרים ובקהל ועדה.",
  "111_2": "גדולים ועצומים מעשי ה', דרושים ונחקרים לכל החפצים בהם.",
  "111_3": "הוד והדר הוא פועלו, וצדקתו עומדת וקיימת לעד.",
  "111_4": "זיכרון עשה לנפלאותיו וניסיו; חנון ורחום הוא ה'.",
  "111_5": "טרף ומזון נתן ליראיו, יזכור לעולם את בריתו.",
  "111_6": "כוח וגבורת מעשיו הגיד לעמו, בתתו להם את נחלת הגויים.",
  "111_7": "מעשי ידיו אמת ומשפט צדק, נאמנים וקבועים כל פקודיו ומצוותיו.",
  "111_8": "סמוכים ומוצקים לעד ולעולמי עולמים, עשויים באמת וביושר לב.",
  "111_9": "פדות וישועה שלח לעמו, ציווה לעולם את בריתו; קדוש ונורא שמו!",
  "111_10": "ראשית החוכמה היא יראת ה', שכל טוב והצלחה לכל עושיהם; תהילתו ושבחו עומדים לעד.",
  "112_1": "הללויה! אשרי האיש הירא את ה', במצוותיו חפץ ומשתוקק מאוד.",
  "112_2": "גיבור וחזק בארץ יהיה זרעו, דור ישרים יבורך בטוב.",
  "112_3": "הון ועושר יהיו בביתו, וצדקתו עומדת וקיימת לעד.",
  "112_4": "זרח בחושך אור ורווחה לישרים; הוא חנון, רחום וצדיק במעשיו.",
  "112_5": "טוב לאיש החונן ומלווה לאחרים ברוחב לב, ומכלכל ומנהל את ענייניו במשפט וביושר.",
  "112_6": "כי לעולם לא ימעד ולא ימוט; לזיכרון עולם יהיה הצדיק.",
  "112_7": "משמועה רעה ומפחידה לא יירא; נכון ויציב ליבו, בטוח בה'.",
  "112_8": "סמוך ומחוזק ליבו ולא יפחד, עד אשר יראה במפלת צורריו.",
  "112_9": "פיזר וחילק נדבות לאביונים, צדקתו עומדת לעד; קרנו וכבודו ירומו בתפארת.",
  "112_10": "רשע יראה זאת ויכעס, שיניו יחרוק ויימס מקנאה ומזעם; תאוות רשעים תאבד ותתבטל.",
  "113_1": "הללויה! הללו, עבדי ה', הללו ושבחו את שם ה'!",
  "113_2": "יהי שם ה' מבורך, מעתה ועד עולם!",
  "113_3": "ממזרח שמש ועד מקום מבואו ושקיעתו – מהולל ומפואר שם ה'.",
  "113_4": "רם מעל כל הגויים ה', מעל השמיים כבודו.",
  "113_5": "מי כה' אלוהינו, המגביה לשבת במרומים,",
  "113_6": "המשפיל להביט ולהשגיח בשמיים ובארץ?",
  "113_7": "מקים מעפר את הדל והשפל, מאשפות ופסולת מרים את האביון,",
  "113_8": "להושיבו עם נדיבים ורוזנים, עם נדיבי עמו ומנהיגיו.",
  "113_9": "מושיב את עקרת הבית העצובה כאם בנים שמחה – הללויה!",
  "114_1": "בצאת ישראל ממצרים, בית יעקב מעם המדבר בלשון זרה,",
  "114_2": "הייתה יהודה למקדשו ומשכנו, ישראל לממשלתו וממלכתו.",
  "114_3": "הים ראה את נוכחות ה' וינוס, נהר הירדן נסוג לאחור.",
  "114_4": "ההרים רקדו כאלים, גבעות קיפצו כבני צאן רכים.",
  "114_5": "מה לך, הים, כי תנוס? הירדן, כי תיסוג לאחור?",
  "114_6": "ההרים, תרקדו כאלים? גבעות, כבני צאן?",
  "114_7": "מלפני אדון חולי ורעדי, ארץ, מלפני אלוהי יעקב,",
  "114_8": "ההופך את הצור והסלע לאגם מים, חלמיש קשה למעיין מים נובעים!",
  "115_1": "לא לנו, ה', לא לכבודנו, כי אם לשמך תן כבוד, למען חסדך ואמיתך!",
  "115_2": "למה יאמרו הגויים בלעג: 'איה נא אלוהיהם?'.",
  "115_3": "והרי אלוהינו בשמיים שוכן; כל אשר חפץ ורצה – עשה!",
  "115_4": "עצביהם ואליליהם הם רק כסף וזהב, מעשה ידי אדם בשר ודם:",
  "115_5": "פה יש להם – ולא ידברו; עיניים יש להם – ולא יראו;",
  "115_6": "אוזניים יש להם – ולא ישמעו; אף יש להם – ולא יריחו;",
  "115_7": "ידיהם – ולא ימששו; רגליהם – ולא יהלכו; לא יהגו ולא ישמיעו הגה בגרונם.",
  "115_8": "כמוהם, חסרי אונים ומתים, יהיו כל עושיהם, וכל מי שבוטח בהם!",
  "115_9": "ישראל, בטח בה'! הוא עזרם ומגינם.",
  "115_10": "בית אהרון, בטחו בה'! הוא עזרם ומגינם.",
  "115_11": "יראי ה', בטחו בה'! הוא עזרם ומגינם.",
  "115_12": "ה' זכרנו לטובה ויברך; יברך את בית ישראל, יברך את בית אהרון,",
  "115_13": "יברך את יראי ה', את הקטנים עם הגדולים.",
  "115_14": "יוסף ה' עליכם ברכה ושגשוג, עליכם ועל בניכם!",
  "115_15": "ברוכים אתם לה', עושה שמיים וארץ.",
  "115_16": "השמיים שמיים הם לה', ואילו את הארץ נתן לבני אדם.",
  "115_17": "לא המתים יהללו יה, ולא כל היורדים לדומיית הקבר והשאול;",
  "115_18": "ואנחנו, החיים, נברך יה מעתה ועד עולם – הללויה!",
  "116_1": "אהבתי והתרגשתי, כי שומע ה' את קולי ואת תחנוניי.",
  "116_2": "כי הטה את אוזנו אליי, ובכל ימי חיי אקרא אליו בתפילה.",
  "116_3": "אפפו והקיפו אותי חבלי מוות, ומצרי שאול מצאוני; צרה ויגון מצאתי.",
  "116_4": "ובשם ה' קראתי: 'אנא, ה', מלט והצל את נפשי!'.",
  "116_5": "חנון ה' וצדיק, ואלוהינו מרחם.",
  "116_6": "שומר פתאים ותמימים ה'; דלותי ושקעתי בעוני ובצרה – ולי הושיע.",
  "116_7": "שובי, נפשי, אל מנוחתך ושלוותך, כי ה' גמל ועשה עמך טוב.",
  "116_8": "כי חילצת את נפשי ממוות, את עיני מדמעה, את רגלי ממעידה ומנפילה.",
  "116_9": "אתהלך לפני ה' בארצות החיים בעולם הזה.",
  "116_10": "האמנתי בה' גם כאשר דיברתי מתוך כאב: 'אני עונה ומיוסר מאוד'.",
  "116_11": "אני אמרתי בחפזי ובבהלתי: 'כל אדם כוזב ואינו נאמן'.",
  "116_12": "מה אשיב לה' על כל גמוליו וטובותיו שהעניק לי?",
  "116_13": "כוס ישועות אשא לכבודו, ובשם ה' אקרא בהודיה.",
  "116_14": "נדריי לה' אשלם, עתה בפני כל עמו.",
  "116_15": "יקר וקשה בעיני ה' המוות הפוקד את חסידיו.",
  "116_16": "אנא ה', כי אני עבדך; אני עבדך בן אמתך, פתחת והתרת את כבליי ומוסרותיי.",
  "116_17": "לך אזבח זבח תודה, ובשם ה' אקרא.",
  "116_18": "נדריי לה' אשלם, עתה לנגד כל עמו,",
  "116_19": "בחצרות בית ה', בתוכך ירושלים – הללויה!",
  "117_1": "הללו את ה', כל גויים; שבחוהו, כל האומות והלאומים!",
  "117_2": "כי גבר ונעלה עלינו חסדו, ואמת ה' ונאמנותו עומדת לעולם – הללויה!",
  "118_1": "הודו לה' כי טוב, כי לעולם חסדו!",
  "118_2": "יאמר נא ישראל, כי לעולם חסדו!",
  "118_3": "יאמרו נא בית אהרון, כי לעולם חסדו!",
  "118_4": "יאמרו נא יראי ה', כי לעולם חסדו!",
  "118_5": "מן המצר והמצוקה קראתי יה, ענני במרחב וברווחה גדולה יה.",
  "118_6": "ה' לי בעזרי, לא אירא ולא אפחד – מה כבר יעשה לי אדם?",
  "118_7": "ה' לי בעוזרי ותומכיי, ואני אראה במפלת שונאיי.",
  "118_8": "טוב לחסות בה' מאשר לבטוח באדם בשר ודם.",
  "118_9": "טוב לחסות בה' מאשר לבטוח בנדיבים ורוזנים.",
  "118_10": "כל הגויים סבבו אותי, אך בשם ה' השמדתי והכנעתי אותם.",
  "118_11": "סבוני גם סבבוני מכל עבר, אך בשם ה' הכנעתים.",
  "118_12": "סבוני כדבורים רבות, דעכו וכבו במהירות כאש בקוצים; בשם ה' הכנעתים.",
  "118_13": "דחֹה דחיתני האויב בעוצמה כדי שאפול, אך ה' עזר וסמך אותי.",
  "118_14": "עוזי וזמרתי הוא יה, והוא היה לי לישועה.",
  "118_15": "קול רינה וישועה נשמע באוהלי צדיקים: יד ימין ה' עושה חיל וגבורה!",
  "118_16": "ימין ה' רוממה ונעלית, ימין ה' עושה חיל!",
  "118_17": "לא אמות כי אחיה, ואספר את מעשי ונפלאות יה.",
  "118_18": "יסר יסרני יה בייסורים ומוסר, אך למוות לא מסר אותי.",
  "118_19": "פתחו לי שערי צדק וקודש, אבוא בם ואודה ליה.",
  "118_20": "זה השער לה', צדיקים יבואו בו.",
  "118_21": "אודך כי ענית לי בתפילתי, ותהי לי לישועה.",
  "118_22": "אבן אשר מאסו ופסלו הבונים – הייתה לאבן פינה ראשית ומרכזית!",
  "118_23": "מאת ה' הייתה זאת, היא נפלאה ומופלאה בעינינו.",
  "118_24": "זה היום עשה ה', נגילה ונשמחה בו!",
  "118_25": "אנא ה' הושיעה נא! אנא ה' הצליחה נא!",
  "118_26": "ברוך הבא בשם ה', ברכנוכם מבית ה'.",
  "118_27": "אל ה' ויאר לנו; אסרו וקשרו את קורבן החג בעבותות עד קרנות המזבח.",
  "118_28": "אלי אתה ואודך, אלוהיי – ארוממך!",
  "118_29": "הודו לה' כי טוב, כי לעולם חסדו!",
  "119_1": "אשרי תמימי ושלמי דרך, ההולכים בתורת ה' ביושר ובשלמות.",
  "119_2": "אשרי נוצרי עדותיו, בכל לב דורשים ומבקשים אותו.",
  "119_3": "אף לא פעלו עוול ושקר, בדרכיו של ה' הלכו.",
  "119_4": "אתה ציווית את פקודיך, לשמור ולקיימם במאוד ובדקדוק.",
  "119_5": "הלוואי וייכונו דרכיי, לשמור את חוקיך תמיד.",
  "119_6": "אז לא אבוש ולא איכלם, בהביטי אל כל מצוותיך.",
  "119_7": "אודך ביושר לבב, בלומדי את משפטי צדקך.",
  "119_8": "את חוקיך אשמור; אל תעזבני עד מאוד.",
  "119_9": "במה יזכה ויטהר נער וצעיר את אורח חייו? בשמרו על פי דבריך.",
  "119_10": "בכל ליבי דרשתיך; אל תשגני ואל תניח לי לסטות ממצוותיך.",
  "119_11": "בליבי צפנתי ושמרתי את אמרתך, למען לא אחטא לך.",
  "119_12": "ברוך אתה ה', למדני והורני את חוקיך.",
  "119_13": "בשפתיי סיפרתי ושיננתי, את כל משפטי פיך.",
  "119_14": "בדרך עדותיך שמחתי ועלזתי, כמו על כל הון ועושר רב.",
  "119_15": "בפקודיך אשוחח ואהגה, ואביט באורחותיך ובדרכיך.",
  "119_16": "בחוקותיך אשתעשע בשמחה, לא אשכח את דבריך.",
  "119_17": "גמול והענק חסד על עבדך ואחיה, ואשמרה את דבריך.",
  "119_18": "גל ופקח את עיניי, ואביט בנפלאות וסודות עמוקים מתוך תורתך.",
  "119_19": "גר וזר אנוכי בארץ; אל תסתר ממני את מצוותיך.",
  "119_20": "גרסה ונשברה נפשי מרוב תשוקה וגעגוע אל משפטיך בכל עת.",
  "119_21": "גערת בזדים ארורים, התועים והסוטים ממצוותיך.",
  "119_22": "גל והסר מעליי חרפה ובוז, כי את עדותיך נצרתי ושמרתי.",
  "119_23": "גם ישבו שרים ודיברו בי לרעה, אך עבדך ישוחח ויהגה בחוקיך.",
  "119_24": "גם עדותיך הן שעשועיי, אנשי עצתי המדריכים אותי.",
  "119_25": "דבקה לעפר נפשי מרוב יגון; חייני והקם אותי כפי הבטחת דבריך.",
  "119_26": "דרכיי סיפרתי לפניך וענית לי; למדני את חוקיך.",
  "119_27": "דרך פקודיך הבינני, ואשיחה ואהגה בנפלאותיך.",
  "119_28": "דלפה ודמעה נפשי מרוב תוגה; קיימני וחזקני כדברך.",
  "119_29": "דרך שקר וכזב הסר ממני, ואת תורתך חנני והענק לי בחסד.",
  "119_30": "דרך אמונה ואמת בחרתי, משפטיך שיוויתי והצבתי לנגדי.",
  "119_31": "דבקתי בעדותיך; ה', אל תבישני!",
  "119_32": "דרך מצוותיך ארוץ בשמחה, כי תרחיב את ליבי בהבנה ובשלווה.",
  "119_33": "הורני, ה', דרך חוקיך, ואנצרנה ואשמרנה עד עקב וסוף.",
  "119_34": "הבינני ואצרה תורתך, ואשמרנה בכל ליבי.",
  "119_35": "הדריכני בנתיב מצוותיך, כי בו חפצתי וחשקתי.",
  "119_36": "הט ליבי אל עדותיך, ולא אל תאוות בצע ורווח חומרי.",
  "119_37": "העבר עיניי מראות שווא והבל; בדרכך חייני והחזקני.",
  "119_38": "הקם וקיים לעבדך את אמרתך והבטחתך, אשר ניתנה ליראיך.",
  "119_39": "העבר חרפתי אשר יגורתי ופחדתי ממנה, כי משפטיך טובים וצודקים.",
  "119_40": "הנה תאבתי ונכספתי לפקודיך; בצדקתך חייני!",
  "119_41": "ויבואוני חסדיך, ה', תשועתך כפי הבטחת אמרתך.",
  "119_42": "ואענה למי שמחרף ומבייש אותי דבר תשובה, כי בטחתי בדברך.",
  "119_43": "ואל תצל ותסיר מפי דבר אמת עד מאוד, כי למשפטיך ייחלתי וקיוויתי.",
  "119_44": "ואשמרה תורתך תמיד, לעולם ועד.",
  "119_45": "ואתהלכה במרחב ובחופש פנימי, כי פקודיך דרשתי וחקרתי.",
  "119_46": "ואדברה בעדותיך נגד מלכים רבי כוח, ולא אבוש.",
  "119_47": "ואשתעשע במצוותיך אשר אהבתי מאוד.",
  "119_48": "ואשא כפיי באהבה אל מצוותיך אשר אהבתי, ואשיחה בחוקיך.",
  "119_49": "זכור דבר והבטחה לעבדך, על אשר ייחלתני ונטעת בי תקווה.",
  "119_50": "זאת נחמתי בעוניי ובצערי: כי אמרתך והבטחתך היא שחייָתני.",
  "119_51": "זדים הליצוני ולעגו לי עד מאוד, אך מתורתך לא נטיתי ולא סרתי.",
  "119_52": "זכרתי משפטיך מעולם, ה', ואתנחם בם.",
  "119_53": "זלעפה וזעזוע עז אחזוני מרשעים, עוזבי תורתך.",
  "119_54": "זמירות ושירים היו לי חוקיך, בבית מגוריי ונדודיי.",
  "119_55": "זכרתי בלילה שמך, ה', ואשמרה תורתך.",
  "119_56": "זאת הייתה לי ולזכותי, כי פקודיך נצרתי.",
  "119_57": "חלקי ונחלתי אתה ה', אמרתי לשמור דבריך.",
  "119_58": "חיליתי וחליתי פניך בכל לב; חונני כפי אמרתך.",
  "119_59": "חישבתי ובחנתי את דרכיי, ואשיבה רגליי אל עדותיך.",
  "119_60": "חשתי ומיהרתי ולא התמהמהתי, לשמור מצוותיך.",
  "119_61": "חבלי רשעים כרכוני והקיפוני, אך תורתך לא שכחתי.",
  "119_62": "בחצות לילה אקום להודות לך, על משפטי צדקך.",
  "119_63": "חבר ושותף אני לכל אשר יראוך, ולשומרי פקודיך.",
  "119_64": "חסדך, ה', מילא את כל הארץ; חוקיך למדני!",
  "119_65": "טוב עשית עם עבדך, ה', כפי דבריך.",
  "119_66": "טוב טעם, הבנה חדה ודעת למדני, כי במצוותיך האמנתי.",
  "119_67": "טרם שעוניתי וסבלתי שגגתי ותעיתי, ועתה אמרתך שמרתי.",
  "119_68": "טוב אתה ומטיב לכל; למדני חוקיך.",
  "119_69": "טפלו והעלילו עליי שקר זדים, אך אני בכל לבב אנצור פקודיך.",
  "119_70": "טפש ואטום כחלב ליבם מלהרגיש, אך אני בתורתך השתעשעתי.",
  "119_71": "טוב לי כי עוניתי וסבלתי, למען אלמד חוקיך מתוך ענווה.",
  "119_72": "טוב לי תורת פיך, מאלפי חתיכות זהב וכסף.",
  "119_73": "ידיך עשוני ויכוננוני; הבינני ואלמדה מצוותיך.",
  "119_74": "יראיך יראוני וישמחו, כי לדברך ייחלתי וקיוויתי.",
  "119_75": "ידעתי, ה', כי צדק משפטיך, ובאמונה ונאמנות עיניתני לטובתי.",
  "119_76": "יהי נא חסדך לנחמני, כפי אמרתך והבטחתך לעבדך.",
  "119_77": "יבואוני רחמיך ואחיה, כי תורתך שעשועיי.",
  "119_78": "יבושו זדים כי בשקר עיוותוני, אך אני אשיח בפקודיך.",
  "119_79": "ישובו אליי יראיך, ויודעי עדותיך.",
  "119_80": "יהי ליבי תמים ושלם בחוקיך, למען לא אבוש.",
  "119_81": "כלתה ונכספה לתשועתך נפשי, לדברך ייחלתי.",
  "119_82": "כלו עיניי בציפייה לאמרתך, לאמור: מתי תנחמני?",
  "119_83": "כי הייתי יבש ומקומט כנאד עור בעשן, אך חוקיך לא שכחתי.",
  "119_84": "כמה הם ימי עבדך הקצרים? מתי תעשה ברודפיי משפט ודין?",
  "119_85": "כרו וחפרו לי זדים שוחיות ומלכודות, אשר אינם הולכים כתורתך.",
  "119_86": "כל מצוותיך אמונה ואמת; בשקר ובחינם רדפוני – עזרני!",
  "119_87": "כמעט כילוני והשמידוני בארץ, ואני לא עזבתי פקודיך.",
  "119_88": "כחסדך חייני וחזקני, ואשמרה עדות פיך.",
  "119_89": "לעולם, ה', דברך נצב וקיים לעד בשמיים.",
  "119_90": "לדור ודור אמונתך ונאמנותך; כוננת ארץ ותעמוד.",
  "119_91": "למשפטיך ולחוקיך עמדו היום, כי הכל עבדיך ונשמעים לרצונך.",
  "119_92": "לולא תורתך שעשועיי, אז אבדתי בעוניי ובצערי.",
  "119_93": "לעולם לא אשכח פקודיך, כי בם חייָתני.",
  "119_94": "לך אני, הושיעני, כי פקודיך דרשתי וחקרתי.",
  "119_95": "לי קיוו וארבו רשעים לאבדני, אך עדותיך אתבונן.",
  "119_96": "לכל תכלה ושלמות ראיתי קץ וגבול, אך מצוותך רחבה מאוד לאין קץ.",
  "119_97": "מה אהבתי תורתך! כל היום היא שיחתי והגיוני.",
  "119_98": "מאויביי תחכמני מצוותיך, כי לעולם היא עימדי.",
  "119_99": "מכל מלמדיי השכלתי, כי עדותיך שיחה הן לי.",
  "119_100": "מזקנים ובעלי ניסיון אתבונן, כי פקודיך נצרתי.",
  "119_101": "מכל אורח ודרך רעה כלאתי ומנעתי רגליי, למען אשמור דברך.",
  "119_102": "ממשפטיך לא סרתי, כי אתה הוריתני והדרכתני.",
  "119_103": "מה נמלצו ומתוקים לחכי אמרתך, מדבש לפי!",
  "119_104": "מפקודיך אתבונן ואקנה בינה, על כן שנאתי כל אורח שקר.",
  "119_105": "נר לרגליי דברך, ואור מנחה לנתיבתי.",
  "119_106": "נשבעתי ואקיימה, לשמור משפטי צדקך.",
  "119_107": "נעניתי וסבלתי עד מאוד; ה', חייני כדברך.",
  "119_108": "נדבות פי רצה נא ה', ומשפטיך למדני.",
  "119_109": "נפשי בסכנה בכפי תמיד, ותורתך לא שכחתי.",
  "119_110": "נתנו רשעים פח ומלכודת לי, ומפקודיך לא תעיתי.",
  "119_111": "נחלתי עדותיך לעולם, כי ששון ליבי המה.",
  "119_112": "נטיתי ליבי לעשות חוקיך, לעולם עד עקב וסוף.",
  "119_113": "סעפים והפכפכי מחשבות שנאתי, ותורתך אהבתי.",
  "119_114": "סתרי ומגיני אתה, לדברך ייחלתי.",
  "119_115": "סורו ממני, מרעים ועושי עוול, ואצרה את מצוות אלוהיי.",
  "119_116": "סמכני כאמרתך ואחיה, ואל תבישני משברי ותקוותי.",
  "119_117": "סעדני ותמוך בי ואיבשע, ואשעה ואהגה בחוקיך תמיד.",
  "119_118": "סלית ורמסת כל תועים מחוקיך, כי שקר ותרמית היא מחשבתם.",
  "119_119": "סגים ופסולת השבתת את כל רשעי ארץ, לכן אהבתי עדותיך.",
  "119_120": "סמר מפחדך בשרי, וממשפטיך יראתי.",
  "119_121": "עשיתי משפט וצדק; בל תניחני לעושקיי.",
  "119_122": "ערוב והיה ערב לעבדך לטובה, אל יעשקוני זדים.",
  "119_123": "עיניי כלו לישועתך, ולאמרת צדקך.",
  "119_124": "עשה עם עבדך כחסדך, וחוקיך למדני.",
  "119_125": "עבדך אני – הבינני, ואדעה עדותיך.",
  "119_126": "עת לעשות ולפעול למען ה' – הפרו והפרו את תורתך!",
  "119_127": "על כן אהבתי מצוותיך, מזהב ומפז יקר.",
  "119_128": "על כן כל פקודי כל ישרתי, כל אורח שקר שנאתי.",
  "119_129": "פלאות ונעלות עדותיך, על כן נצרתן נפשי.",
  "119_130": "פתח וגילוי דבריך יאיר, מבין ומשכיל פתאים ותמימים.",
  "119_131": "פי פערתי ואשאפה רוח בתשוקה, כי למצוותיך יאבתי ונכספתי.",
  "119_132": "פנה אליי וחנני, כמשפט וכמנהג הראוי לאוהבי שמך.",
  "119_133": "פעמיי הכן והצב באמרתך, ואל תשלט בי כל און ועוול.",
  "119_134": "פדני מעושק אדם בשר ודם, ואשמרה פקודיך.",
  "119_135": "פניך האר בעבדך, ולמדני את חוקיך.",
  "119_136": "פלגי מים ותרעומות זרמו מעיניי, על אשר לא שמרו תורתך.",
  "119_137": "צדיק אתה, ה', וישרים וצודקים משפטיך.",
  "119_138": "ציווית צדק עדותיך, ואמונה ונאמנות רבה מאוד.",
  "119_139": "צמתתני וכילתה אותי קנאתי, כי שכחו דבריך צריי.",
  "119_140": "צרופה ומזוקקת אמרתך מאוד, ועבדך אהבה.",
  "119_141": "צעיר אנוכי ונבזה בעיני רואים, אך פקודיך לא שכחתי.",
  "119_142": "צדקתך צדק עולם, ותורתך אמת.",
  "119_143": "צר ומצוק מצאוני, אך מצוותיך שעשועיי.",
  "119_144": "צדק עדותיך לעולם; הבינני ואחיה!",
  "119_145": "קראתי בכל לב – ענני ה', חוקיך אצורה.",
  "119_146": "קראתיך הושיעני, ואשמרה עדותיך.",
  "119_147": "קידמתי בנשף ובטרם שחר ואשוועה, לדבריך ייחלתי.",
  "119_148": "קידמו עיניי אשמורות לילה, לשוח ולהגות באמרתך.",
  "119_149": "קולי שמעה כחסדך, ה', כמשפטך חייני.",
  "119_150": "קרבו רודפי זמה ומזימה רעה, מתורתך התרחקו.",
  "119_151": "קרוב אתה, ה', וכל מצוותיך אמת.",
  "119_152": "קדם ומאז ידעתי מעדותיך, כי לעולם ייסדתן.",
  "119_153": "ראה עוניי וחלצני, כי תורתך לא שכחתי.",
  "119_154": "ריבה ריבי וגאלני, לאמרתך חייני.",
  "119_155": "רחוק מרשעים ישועה, כי חוקיך לא דרשו.",
  "119_156": "רחמיך רבים, ה', כמשפטיך חייני.",
  "119_157": "רבים רודפיי וצריי, אך מעדותיך לא נטיתי.",
  "119_158": "ראיתי בוגדים ואתקוטטה עמם, אשר אמרתך לא שמרו.",
  "119_159": "ראה כי פקודיך אהבתי; ה', כחסדך חייני.",
  "119_160": "ראש ועיקר דברך אמת, ולעולם כל משפט צדקך.",
  "119_161": "שרים רדפוני חינם ללא סיבה, ומדברך פחד וחרד ליבי.",
  "119_162": "שש ושמח אנוכי על אמרתך, כמוצא שלל רב ועצום.",
  "119_163": "שקר שנאתי ואתעבה, תורתך אהבתי.",
  "119_164": "שבע פעמים ביום היללתיך, על משפטי צדקך.",
  "119_165": "שלום רב לאוהבי תורתך, ואין למו מכשול ומכשלה.",
  "119_166": "שיברתי וקיוויתי לישועתך, ה', ומצוותיך עשיתי.",
  "119_167": "שמרה נפשי עדותיך, ואוהבם מאוד.",
  "119_168": "שמרתי פקודיך ועדותיך, כי כל דרכיי גלויים נגדך.",
  "119_169": "תקרב רינתי לפניך, ה', כדברך הבינני.",
  "119_170": "תבוא תחינתי לפניך, כאמרתך הצילני.",
  "119_171": "תבענה שפתיי תהילה ושבח, כי תלמדני חוקיך.",
  "119_172": "תען לשוני אמרתך, כי כל מצוותיך צדק.",
  "119_173": "תהי ידך לעזרני, כי פקודיך בחרתי.",
  "119_174": "תאבתי ונכספתי לישועתך, ה', ותורתך שעשועיי.",
  "119_175": "תחי נפשי ותהללך, ומשפטיך יעזרוני.",
  "119_176": "תעיתי כשה אובד – בקש עבדך, כי מצוותיך לא שכחתי!",
  "120_1": "שיר המעלות: אל ה' במצוקתי וצרתי קראתי, והוא ענה לי.",
  "120_2": "ה', הצל נא את נפשי משפת שקר ומלשון מרמה.",
  "120_3": "מה ייתן לך ומה יוסיף לך עונש, לשון רמייה?",
  "120_4": "חיצי גיבור שנונים ומחודדים, יחד עם גחלי עצי רותם הבוערים זמן רב!",
  "120_5": "אוי לי כי גרתי והתגוררתי במשך, ושכנתי עם אוהלי קדר האלימים.",
  "120_6": "זמן רב מדי שכנה נפשי עם שונאי השלום.",
  "120_7": "אני כולו שלום, וכאשר אני מדבר ומציע שלום – המה פונים למלחמה.",
  "121_1": "שיר למעלות: אשא את עיניי אל ההרים – מאין יבוא עזרי?",
  "121_2": "עזרי בא מאת ה', עושה שמיים וארץ.",
  "121_3": "אל ייתן למוט ולמעוד רגלך; אל יירדם שומרך ומגנך.",
  "121_4": "הנה, לא ינום ולא יישן שומר ישראל!",
  "121_5": "ה' הוא שומרך; ה' הוא צילך ומחפסתך על יד ימינך.",
  "121_6": "יומם השמש לא תכה בך בחום כבד, וירח לא יזיק לך בלילה.",
  "121_7": "ה' ישמור אותך מכל רע; ישמור וינצור את נפשך.",
  "121_8": "ה' ישמור את צאתך לדרך ואת בואך לביתך, מעתה ועד עולם!",
  "122_1": "שיר המעלות, שחיבר דוד: שמחתי באומרים לי: 'אל בית ה' נלך!'.",
  "122_2": "עומדות היו רגלינו בשעריך המפוארים, ירושלים.",
  "122_3": "ירושלים הבנויה כעיר שחוברה לה יחדיו באחדות ובשלימות,",
  "122_4": "ששם עלו שבטים, שבטי יה, כעדות ומצווה לישראל, להודות ולשבח את שם ה'.",
  "122_5": "כי שם ישבו כיסאות משפט וצדק, כיסאות לבית מלכות דוד.",
  "122_6": "שאלו והתפללו לשלום ירושלים; ישלוו וישקטו אוהבייך!",
  "122_7": "יהי שלום בחילך ובחומותייך, שלווה ושקט בארמונותייך.",
  "122_8": "למען אחיי ורעיי האהובים, אדברה נא שלום בך.",
  "122_9": "למען בית ה' אלוהינו, אבקש ואדרוש כל טוב עבורך.",
  "123_1": "שיר המעלות: אליך נשאתי את עיניי, היושב והמושל בשמיים.",
  "123_2": "הנה כעיני עבדים הנשואות אל יד אדוניהם, כעיני שפחה אל יד גבירתה – כן עינינו נשואות אל ה' אלוהינו, עד שיחוננו וירחם עלינו.",
  "123_3": "חוננו ה', חוננו ברחמיך, כי שבענו והתמלאנו בוז ולעג עד מאוד.",
  "123_4": "רבת שבעה לה נפשנו את לעג השאננים והבוטחים בעושרם, ואת הבוז של הגאוותנים הזדים.",
  "124_1": "שיר המעלות, שחיבר דוד: לולא ה' שהיה בעזרתנו – יאמר נא ישראל,",
  "124_2": "לולא ה' שהיה לנו כאשר קמו עלינו בני אדם אויבים להילחם בנו,",
  "124_3": "אזי חיים היו בולעים אותנו, כאשר בער כעסם וחמתם בנו.",
  "124_4": "אזי המים הזדוניים היו שוטפים אותנו, נחל זועף היה עובר על נפשנו.",
  "124_5": "אזי עברו על נפשנו המים הזידונים המאיימים.",
  "124_6": "ברוך ה', שלא נתן אותנו לטרף לשיניהם האכזריות!",
  "124_7": "נפשנו כציפור נמלטה מפח ציידים; הפח נשבר ונקרע – ואנחנו נמלטנו!",
  "124_8": "עזרתנו היא בשם ה', עושה שמיים וארץ.",
  "125_1": "שיר המעלות: הבוטחים בה' הם כהר ציון – לא ימוט ויישב לעולם ביציבות.",
  "125_2": "ירושלים – הרים סביב לה, וה' שומר וסובב את עמו מעתה ועד עולם.",
  "125_3": "כי לא ינוח שבט שלטון הרשע על נחלת הצדיקים, למען לא ישלחו הצדיקים את ידיהם בעוול ובחטא.",
  "125_4": "היטיבה, ה', לטובים ולישרי לבב במחשבותיהם.",
  "125_5": "ואילו את המטים עקלקלותם וסוטים מן הדרך – יוליכם ה' לאבדון עם פועלי עוול; שלום על ישראל!",
  "126_1": "שיר המעלות: בשוב ה' את שבות ציון והחזרת הגולים, היינו כמו חולמים מרוב גודל הפלא והאושר.",
  "126_2": "אז יימלא שחוק פינו ולשוננו רינה ושמחה; אז יאמרו בגויים בהשתאות: 'הגדיל ה' לעשות עם אלה!'.",
  "126_3": "הגדיל ה' לעשות עימנו – היינו שמחים ומאושרים!",
  "126_4": "שובה, ה', את שבותנו והחזר את שארית עמנו, כמו אפיקי מים השוטפים ומרווים את הנגב היבש.",
  "126_5": "הזורעים בדמעה ובקושי – ברינה ובשמחה יקצרו!",
  "126_6": "הלוך יילך ובכה כשהוא נושא שק זרע, אך בוא יבוא ברינה ובשמחה כשהוא נושא אלומותיו המלאות ברכה.",
  "127_1": "שיר המעלות, לשלמה: אם ה' לא יבנה בית – שווא וריק עמלו בוניו בו; אם ה' לא ישמור עיר – שווא שקד והיה ער השומר.",
  "127_2": "שווא והבל לכם המשכימים לקום מוקדם והמאחרים לשבת עד מאוחר, אוכלי לחם העצבים והדאגות; הרי כך ייתן ה' לידידו מתוך שינה ושלווה.",
  "127_3": "הנה נחלת ה' ומתנתו היא בנים, שכר וברכה הוא פרי הבטן.",
  "127_4": "כחיצים ביד גיבור מיומן – כן הם בני הנעורים המגנים על אביהם.",
  "127_5": "אשרי הגבר אשר מילא את אשפתו מהם; לא יבושו כאשר ידברו ויתדיינו עם אויבים בשער העיר.",
  "128_1": "שיר המעלות: אשרי כל מי שירא את ה', ההולך בדרכיו הישרות.",
  "128_2": "יגיע כפיך ופרי עמלך כי תאכל – אשריך וטוב ומוצלח יהיה לך!",
  "128_3": "אשתך תהיה כגפן פורייה ומשובחת בירכתי ביתך; בניך יהיו כשתילֵי זיתים רעננים סביב שולחנך.",
  "128_4": "הנה כי כן יבורך גבר ירא ה'.",
  "128_5": "יברכך ה' מציון, וראה בטוב ירושלים בכל ימי חייך;",
  "128_6": "וראה בנים לבניך – שלום על ישראל!",
  "129_1": "שיר המעלות: רבות צררו והציקו לי מנעוריי – יאמר נא ישראל,",
  "129_2": "רבות צררוני מנעוריי, אך לא יכלו לי ולא הכניעוני.",
  "129_3": "על גבי חרשו חורשים מכות עמוקות, האריכו את מעניתם וחרפוצי סבלם.",
  "129_4": "ה' הוא צדיק; קיצץ וניתק את חבלי הרשעים.",
  "129_5": "יבושו וייסוגו לאחור כל שונאי ציון.",
  "129_6": "יהיו כחציר הגדל על גגות, אשר עוד לפני שנשלף ונקרע הוא מתייבש,",
  "129_7": "שלא מילא כפו הקוצר ממנו, ולא חיקו המעמר האוסף אלומות;",
  "129_8": "ולא אמרו עוברי הדרך: 'ברכת ה' אליכם, ברכנו אתכם בשם ה'!'.",
  "130_1": "שיר המעלות: ממעמקי המצוקה והכאב קראתיך, ה'.",
  "130_2": "אדוני, שמעה בקולי; תהיינה אוזניך קשובות לקול תחנוניי.",
  "130_3": "אם עוונות תשמור ותזכור לחומרה, יה – אדוני, מי יוכל לעמוד בדין?",
  "130_4": "כי עימך הסליחה והמחילה, למען תיוורע ותיראה מתוך יראת כבוד.",
  "130_5": "קיוויתי לה', קיוותה נפשי, ולדברו ולישועתו ייחלתי.",
  "130_6": "נפשי מייחלת לאדוני יותר משומרים המצפים לבוקר, שומרים לבוקר.",
  "130_7": "ייחל, ישראל, אל ה', כי עם ה' החסד, והרבה עימו פדות וישועה.",
  "130_8": "והוא יפדה ויגאל את ישראל מכל עוונותיו וחטאיו.",
  "131_1": "שיר המעלות, שחיבר דוד: ה', לא גבה ליבי ולא רמו עיניי בגאווה, ולא הלכתי בגדולות ובנפלאות הנשגבות ממני.",
  "131_2": "אם לא שיוויתי והשקטתי את נפשי כגמול ויונק על אמו, כגמול שקט עליי נפשי.",
  "131_3": "ייחל, ישראל, אל ה', מעתה ועד עולם!",
  "132_1": "שיר המעלות: זכור, ה', לדוד את כל עמלו, יגיעתו וטרחתו למען המקדש,",
  "132_2": "אשר נשבע לה', נדר נדר לאביר יעקב:",
  "132_3": "'אם אבוא באוהל ביתי, אם אעלה על ערש יצועי ומראשותיי,",
  "132_4": "אם אתן שנת שינה לעיניי, לעפעפיי תנומה,",
  "132_5": "עד אשר אמצא מקום משכן לה', משכנות קבע לאביר יעקב!'.",
  "132_6": "הנה שמענו עליו באפרתה, מצאנוהו בשדות יער (קריית יערים).",
  "132_7": "נבואה אל משכנותיו, נשתחווה להדום רגליו.",
  "132_8": "קומה, ה', למנוחתך ומשכנך, אתה וארון עוזך!",
  "132_9": "כוהניך ילבשו צדק, וחסידיך ירננו וישירו בשמחה.",
  "132_10": "בעבור דוד עבדך הנאמן, אל תשב ותדחה את פני משיחך.",
  "132_11": "נשבע ה' לדוד שבועת אמת שלא יסור ממנה: 'מפרי בטנך אשית על כיסאך.",
  "132_12": "אם ישמרו בניך בריתי ועדותי זו אשר אלמדם – גם בניהם עד עולם יישבו על כיסאך!'.",
  "132_13": "כי בחר ה' בציון, איווה וחשק בה למושב לו:",
  "132_14": "'זאת מנוחתי לעדי עד; פה אשב כי איוויתיה.",
  "132_15": "צידה ומזונה ברך אברך, אביוניה אשביע לחם.",
  "132_16": "וכוהניה אלביש ישע, וחסידיה רנן ירננו.",
  "132_17": "שם אצמיח קרן וכוח לדוד, ערכתי והכנתי נר ומאור למשיחי.",
  "132_18": "אויביו אלביש בושת, ועליו יציץ ויזרח נזרו וכתרו!'.",
  "133_1": "שיר המעלות, שחיבר דוד: הנה מה טוב ומה נעים שבת אחים גם יחד באהבה ובשלום!",
  "133_2": "כשמן הטוב והריחני על הראש, היורד על הזקן – זקן אהרון, היורד על פי מידותיו ובגדיו;",
  "133_3": "כטל חרמון הרענן היורד על הרי ציון, כי שם ציווה ה' את הברכה, חיים עד העולם!",
  "134_1": "שיר המעלות: הנה ברכו את ה', כל עבדי ה', העומדים ומשרתים בבית ה' בלילות!",
  "134_2": "שאו ידיכם בקודש וברכו את ה'!",
  "134_3": "יברכך ה' מציון, עושה שמיים וארץ!",
  "135_1": "הללויה! הללו את שם ה', שבחו, עבדי ה',",
  "135_2": "העומדים בבית ה', בחצרות בית אלוהינו!",
  "135_3": "הללו יה כי טוב ה', זמרו לשמו כי נעים הוא.",
  "135_4": "כי את יעקב בחר לו יה, את ישראל לסגולתו ואוצרו היקר.",
  "135_5": "כי אני ידעתי כי גדול ה', ואדוננו מכל האלים.",
  "135_6": "כל אשר חפץ ה' עשה בשמיים ובארץ, בימים ובכל מעמקי תהומות.",
  "135_7": "מעלה נשיאים ועננים מקצה הארץ, ברקים לגשם עשה, מוציא רוח מאוצרותיו.",
  "135_8": "הוא שהיכה בכורי מצרים, מאדם ועד בהמה.",
  "135_9": "שלח אותות ומופתים בקרבך מצרים, בפרעה ובכל עבדיו.",
  "135_10": "שהיכה גויים רבים, והרג מלכים עצומים:",
  "135_11": "לסיחון מלך האמורי, ולעוג מלך הבשן, ולכל ממלכות כנען;",
  "135_12": "ונתַן ארצם נחלה, נחלה לישראל עמו.",
  "135_13": "ה', שמך קיים לעולם; ה', זכרך לדור ודור.",
  "135_14": "כי ידין וישפוט ה' את עמו ברחמים, ועל עבדיו יתנחם.",
  "135_15": "עצבי הגויים הם כסף וזהב, מעשה ידי אדם:",
  "135_16": "פה להם ולא ידברו; עיניים להם ולא יראו;",
  "135_17": "אוזניים להם ולא יאזינו; אף אין שום נשימת רוח חיים בפיהם.",
  "135_18": "כמוהם יהיו כל עושיהם, כל אשר בוטח בהם.",
  "135_19": "בית ישראל, ברכו את ה'! בית אהרון, ברכו את ה'!",
  "135_20": "בית הלוי, ברכו את ה'! יראי ה', ברכו את ה'!",
  "135_21": "ברוך ה' מציון, שוכן ירושלים – הללויה!",
  "136_1": "הודו לה' כי טוב, כי לעולם חסדו!",
  "136_2": "הודו לאלוהי האלוהים, כי לעולם חסדו!",
  "136_3": "הודו לאדוני האדונים, כי לעולם חסדו!",
  "136_4": "לעושה נפלאות גדולות לבדו, כי לעולם חסדו!",
  "136_5": "לעושה השמיים בתבונה, כי לעולם חסדו!",
  "136_6": "לרוקע ופורש הארץ על המים, כי לעולם חסדו!",
  "136_7": "לעושה מאורות גדולים, כי לעולם חסדו!",
  "136_8": "את השמש לממשלת היום, כי לעולם חסדו!",
  "136_9": "את הירח וכוכבים לממשלות בלילה, כי לעולם חסדו!",
  "136_10": "למכה מצרים בבכוריהם, כי לעולם חסדו!",
  "136_11": "ויוצא ישראל מתוכם, כי לעולם חסדו!",
  "136_12": "ביד חזקה ובזרוע נטויה, כי לעולם חסדו!",
  "136_13": "לגוזר ים סוף לגזרים ונתיבים, כי לעולם חסדו!",
  "136_14": "והעביר ישראל בתוכו, כי לעולם חסדו!",
  "136_15": "וניער והשליך פרעה וחילו בים סוף, כי לעולם חסדו!",
  "136_16": "למוליך עמו במדבר, כי לעולם חסדו!",
  "136_17": "למכה מלכים גדולים, כי לעולם חסדו!",
  "136_18": "ויהרוג מלכים אדירים, כי לעולם חסדו!",
  "136_19": "לסיחון מלך האמורי, כי לעולם חסדו!",
  "136_20": "ולעוג מלך הבשן, כי לעולם חסדו!",
  "136_21": "ונתַן ארצם לנחלה, כי לעולם חסדו!",
  "136_22": "נחלה לישראל עבדו, כי לעולם חסדו!",
  "136_23": "שבשפלותנו ומצוקתנו זכר לנו, כי לעולם חסדו!",
  "136_24": "ויפרקנו ויחלצנו מצוררינו, כי לעולם חסדו!",
  "136_25": "נותן לחם ומזון לכל בשר, כי לעולם חסדו!",
  "136_26": "הודו לאל השמיים, כי לעולם חסדו!",
  "137_1": "על נהרות בבל, שם ישבנו וגם בכינו, בזכרנו את ציון.",
  "137_2": "על עצי הערבות שבתוכה, תלינו את כינורותינו הדוממים.",
  "137_3": "כי שם שאלונו שובינו דברי שיר, ומענינו שאלונו שמחה: 'שירו לנו משיר ציון!'.",
  "137_4": "איך נשיר את שיר ה' הקדוש על אדמת נכר זרה?",
  "137_5": "אם אשכחך, ירושלים – תשכח ימיני את כוחה ונגינתה!",
  "137_6": "תדבק לשוני לחיכי אם לא אזכרך, אם לא אעלה את ירושלים על ראש שמחתי!",
  "137_7": "זכור, ה', לבני אדום את יום חורבן ירושלים, האומרים בזדון: 'ערו והחריבו אותה עד היסוד בה!'.",
  "137_8": "בת בבל השדודה והעתידה להיהרס, אשרי מי שישלם לך את גמולך הרע שגמלת לנו!",
  "137_9": "אשרי שיאחז וירסק את עולליך אל הסלע!",
  "138_1": "לדוד: אודך בכל ליבי; נגד שרים ומלאכים אזמר לך.",
  "138_2": "אשתחווה אל היכל קודשך ואודה את שמך על חסדך ועל אמיתך, כי הגדלת על כל שמך את אמרתך והבטחתך.",
  "138_3": "ביום קראתי עניתני; הרחבת וחיזקת בנפשי עוז וגבורה.",
  "138_4": "יודוך, ה', כל מלכי הארץ, כי שמעו את אמרי פיך.",
  "138_5": "וישירו בדרכי ה', כי גדול כבוד ה'.",
  "138_6": "כי רם ה' ואת השפל והעני יראה, ואת הגאוותן ממרחק יידע וישפיל.",
  "138_7": "אם אלך בקרב צרה – תחייני; על אף אויביי תשלח ידך, ותושיעני ימינך.",
  "138_8": "ה' יגמור וישלים את טובו בעדי; ה', חסדך לעולם – מעשי ידיך אל תרף ואל תעזוב!",
  "139_1": "למנצח, לדוד מזמור: ה', חקרת אותי ובדקתני, ואתה מכיר אותי היטב.",
  "139_2": "אתה ידעת את שבתי ואת קומי; הבנת מחשבותיי וכוונותיי עוד ממרחק.",
  "139_3": "את נתיב הילוכי ואת מנוחתי זרית וביררת, וכל דרכיי גלויות ומוכרות לך.",
  "139_4": "כי אין עדיין מילה על לשוני, והנה, ה', כבר ידעת אותה במלואה.",
  "139_5": "מאחור ומלפנים צרת וסגרת עליי, ותשת עליי את כפך המגוננת.",
  "139_6": "פלאית ונעלית ממני דעת עמוקה כזו; נשגבה היא, לא אוכל להשיגה.",
  "139_7": "לאן אלך מרוחך? ולאן מפניך אברח?",
  "139_8": "אם אעלה שמימה – שם אתה; ואם אציע יצועי בשאול תחתית – הנה הנך!",
  "139_9": "אשא כנפי שחר ואעוף במהירות, אשכנה בקצה ים מערבי רחוק –",
  "139_10": "גם שם ידך תנחני, ותאחז בי יד ימינך.",
  "139_11": "ואומר: 'אך חושך ואפלה יכסוני, ולילה יהיה האור סביבי' –",
  "139_12": "גם החושך לא יחשיך ממך, ולילה כיום יאיר לפניך; כחשיכה כאורה שווים בעיניך.",
  "139_13": "כי אתה יצרת וקנית כליותיי, סוככת וארגת אותי בבטן אמי.",
  "139_14": "אודך על כי באופן נורא ומופלא נפליתי בבריאתי; נפלאים מעשיך, ונפשי יודעת זאת היטב.",
  "139_15": "לא נעלם עצמי וגופי ממך אשר נעשיתי בסתר, נרקמתי כמו במעמקי תחתיות ארץ.",
  "139_16": "את גולמי בטרם נברא ראו עיניך, ועל ספרך כולם ייכתבו ימים שיוצרו עוד בטרם היה אחד בהם.",
  "139_17": "וכמה יקרות ונכבדות בעיניי מחשבותיך, אל! מה עצום וכבד סכומן!",
  "139_18": "אספרם – מחול הים ירבון; הקיצותי משנתי – ועודי עימך.",
  "139_19": "הלוואי ותהרוג, אלוהים, את הרשע! ואנשי דמים – סורו ממני!",
  "139_20": "אשר ימרוך וידברו עליך במזימות מרמה, נשאו לשווא שמך עריציך.",
  "139_21": "הלא את משנאיך, ה', אשנא, ובקמים עליך אתקוטט ואמאס?",
  "139_22": "שנאה שלמה ותכליתית שנאתים; לאויבים היו לי.",
  "139_23": "חקרני, אל, ודע את ליבי; בחנני ודע את שרעפיי ומחשבותיי,",
  "139_24": "וראה אם יש בי דרך עצב וחטא, ונחני בדרך עולם הישרה והנצחית.",
  "140_1": "למנצח, מזמור לדוד:",
  "140_2": "חלצני והצל אותי, ה', מאדם רע; מאיש חמסים ואלים נצור אותי,",
  "140_3": "אשר חשבו רעות בליבם, כל יום הם מתאספים ומתגרים למלחמות.",
  "140_4": "שננו לשונם כנחש ארסי, חמת עכשוב מסוכנת תחת שפתותיהם סלה.",
  "140_5": "שמרני, ה', מידי רשע; מאיש חמסים נצרני, אשר חשבו לדחות ולהכשיל את צעדיי.",
  "140_6": "טמנו גאים פח ומלכודת לי וחבלים, פרשו רשת לצד נתיב דרכי; מוקשים שמו לי סלה.",
  "140_7": "אמרתי לה': 'אלי אתה! האזינה, ה', לקול תחנוניי!'.",
  "140_8": "ה' אלוהים, עוז ישועתי, סוככת והגנת על ראשי ביום קרב ומערכה.",
  "140_9": "אל תיתן, ה', את משאלות ותאוות הרשע; מזימתו אל תוציא לפועל פן יתרוממו סלה.",
  "140_10": "ראש המסובבים אותי – עמל ועוול שפתותיהם שלהם יכסם!",
  "140_11": "יימוטו וייפלו עליהם גחלי אש, באש יפילם ובורות מים שלא יוכלו לקום מהם.",
  "140_12": "איש לשון ורכילות לא ייכון בארץ; איש חמס – רע יצודו וירדפו עד מפלתו.",
  "140_13": "ידעתי כי יעשה ה' דין עני ומשפט אביונים.",
  "140_14": "אך צדיקים יודו לשמך, יישבו ישרים את פניך בהשגחתך.",
  "141_1": "מזמור לדוד: ה', קראתיך חושה ועזור לי! האזינה קולי בקוראי אליך.",
  "141_2": "תיכון תפילתי כקטורת סמים לפניך, משאת והנפת כפיי כמנחת ערב.",
  "141_3": "שיתה, ה', שמירה לפי, נצרה את דלת שפתותיי שלא אחטא בדיבור.",
  "141_4": "אל תט ליבי לדבר רע, להתעולל עלילות ברשע עם אנשים פועלי אוון, ובל אלחם במטעמיהם ובסעודותיהם.",
  "141_5": "יהלמני ויוכיחני צדיק – חסד הוא, ויוכיחני כשמן ראש שלא יסרב ראשי לקבלו; כי עוד תפילתי כנגד רעותיהם.",
  "141_6": "נשמטו בידי סלע שופטיהם, ושמעו דבריי כי נעימים וטובים הם.",
  "141_7": "כמו חורש ובוקע רגבי עפר בארץ – כך נזרעו ופוזרו עצמותינו לפי השאול.",
  "141_8": "כי אליך, ה' אלוהים, נשואות עיניי; בך חסיתי, אל תער ואל תשפוך את נפשי.",
  "141_9": "שמרני מידי פח ומלכודת שיקשו לי, וממוקשי פועלי אוון.",
  "141_10": "ייפלו במכמורותיהם וברשתותיהם רשעים יחד, בעוד אנוכי אעבור ואמלט ללא פגע.",
  "142_1": "משכיל לדוד, בהיותו מסתתר במערה, תפילה:",
  "142_2": "קולי אל ה' אזעק; קולי אל ה' אתחנן.",
  "142_3": "אשפוך לפניו את שיחי וצערי, צרתי לפניו אגיד.",
  "142_4": "בהתעטף עליי רוחי מרוב מועקה – ואתה ידעת נתיבתי; באורח שבו אני מהלך טמנו פח לי.",
  "142_5": "הבט ימין וראה ואין לי מכיר ותומך; אבד מנוס ממני, אין אדם הדורש ודואג לנפשי.",
  "142_6": "זעקתי אליך, ה', אמרתי: 'אתה מחסי, חלקי בארץ החיים!'.",
  "142_7": "הקשיבה אל רינתי ושוועתי כי דלותי מאוד; הצילני מרודפיי כי אמצו וחזקו ממני.",
  "142_8": "הוציאה ממסגר וממאסר את נפשי להודות את שמך; בי יכתירו ויתאספו צדיקים, כי תגמול עליי בטוב.",
  "143_1": "מזמור לדוד: ה', שמעה תפילתי, האזינה אל תחנוניי באמונתך, ענני בצדקתך.",
  "143_2": "ואל תבוא במשפט קפדני עם עבדך, כי לא ייצדק לפניך שום אדם חי.",
  "143_3": "כי רדף אויב את נפשי, דיכא ורמס לארץ את חיי; הושיבני במחשכים כמתֵי עולם שנשכחו.",
  "143_4": "ותתעטף עליי רוחי ביגון; בתוכי ישתומם ויכאב ליבי.",
  "143_5": "זכרתי ימים מקדם, הגיתי בכל פועלך המפואר, במעשה ידיך אשוחח.",
  "143_6": "פרשׂתי ידיי בתחינה אליך; נפשי כארץ עיפה וצמאה למים אליך סלה.",
  "143_7": "מהר ענני, ה', כלתה ודועכת רוחי; אל תסתר פניך ממני ונמשלתי עם יורדי בור קבר.",
  "143_8": "השמיעני בבוקר חסדך כי בך בטחתי; הודיעני דרך זו אלך בה, כי אליך נשאתי נפשי.",
  "143_9": "הצילני מאויביי, ה', כי אצלך כיסיתי ומצאתי מחסה.",
  "143_10": "למדני לעשות רצונך כי אתה אלוהיי; רוחך הטובה תנחני בארץ מישור.",
  "143_11": "למען שמך, ה', תחייני; בצדקתך תוציא מצרה את נפשי.",
  "143_12": "ובחסדך תצמית ותשמיד אויביי, והאבדת כל צוררי נפשי, כי אני עבדך.",
  "144_1": "לדוד: ברוך ה' צורי ומחזקי, המלמד ידיי לקרב, אצבעותיי למלחמה;",
  "144_2": "חסדי ומבצרי, משגבי ומפלטי לי, מגיני ובו חסיתי; הרודד ומכניע עמי תחתי.",
  "144_3": "ה', מה הוא אדם כי תדעהו ותשגיח בו, בן אנוש כי תחשבהו?",
  "144_4": "אדם להבל דמה, ימיו כצל עובר וחולף.",
  "144_5": "ה', הטה שמיך ותרד, גע בהרים ויעשנו עשן.",
  "144_6": "ברוק ברק והפץ אותם, שלח חיציך והומם והרעד אותם.",
  "144_7": "שלח ידיך ממרום; פדני והצילני ממים רבים, מיד בני נכר עוינים,",
  "144_8": "אשר פיהם דיבר שווא ושקר, וימינם ימין שקר ושבועת כזב.",
  "144_9": "אלוהים, שיר חדש אשירה לך, בנבל עשור אזמרה לך,",
  "144_10": "הנותן תשועה למלכים, הפוצה ומציל את דוד עבדו מחרב רעה.",
  "144_11": "פדני והצילני מיד בני נכר, אשר פיהם דיבר שווא, וימינם ימין שקר.",
  "144_12": "אשר בנינו כנטיעים מגודלים בנעוריהם, בנותינו כעמודי זוויות מחוטבות בתבנית ארמון מפואר;",
  "144_13": "מזווינו ואסמינו מלאים, מפיקים ומספקים מזון מזן אל זן; צאוננו מאליפות ומרובות ברבבות בחוצותינו;",
  "144_14": "אלופינו ושורינו מסובלים וטעונים היטב; אין שום פרצה בחומות ואין יוצאת לשבי, ואין שום צווחת אבל ברחובותינו.",
  "144_15": "אשרי העם שככה לו! אשרי העם שה' הוא אלוהיו!",
  "145_1": "תהילה שחיבר דוד: ארוממך, אלוהיי המלך, ואברכה שמך לעולם ועד!",
  "145_2": "בכל יום אברכך, ואהללה שמך לעולם ועד.",
  "145_3": "גדול ה' ומהולל מאוד, ולגדולתו אין חקר וגבול.",
  "145_4": "דור לדור ישבח מעשיך, וגבורותיך יגידו ויספרו.",
  "145_5": "הדר כבוד הודך, ודברי נפלאותיך אשיחה ואהגה.",
  "145_6": "ועזוז אימותיך ונוראותיך יאמרו, וגדולתך אספרנה.",
  "145_7": "זכר רב טובך יביעו בשפע, וצדקתך ירננו בשמחה.",
  "145_8": "חנון ורחום ה', ארך אפיים וגדול חסד.",
  "145_9": "טוב ה' לכל ברואיו, ורחמיו על כל מעשיו ויצוריו.",
  "145_10": "יודוך, ה', כל מעשיך, וחסידיך יברכוכה.",
  "145_11": "כבוד מלכותך יאמרו, וגבורתך ידברו,",
  "145_12": "להודיע לבני האדם גבורותיו, וכבוד הדר מלכותו.",
  "145_13": "מלכותך מלכות כל עולמים, וממשלתך בכל דור ודור.",
  "145_14": "סומך ה' לכל הנופלים, וזוקף ומקים לכל הכפופים והנדכאים.",
  "145_15": "עיני כל אליך ישברו ומצפות, ואתה נותן להם את אוכלם בעתו.",
  "145_16": "פותח את ידך הרחבה, ומשביע לכל חי רצון ומזון ברווח.",
  "145_17": "צדיק ה' בכל דרכיו, וחסיד וגומל חסד בכל מעשיו.",
  "145_18": "קרוב ה' לכל קוראיו, לכל אשר יקראוהו באמת ובלב תמים.",
  "145_19": "רצון יראיו יעשה, ואת שוועתם ישמע ויושיעם.",
  "145_20": "שומר ה' את כל אוהביו, ואת כל הרשעים ישמיד ויכרית.",
  "145_21": "תהילת ה' ידבר פי, ויברך כל בשר שם קודשו לעולם ועד!",
  "146_1": "הללויה! הללי, נפשי, את ה'!",
  "146_2": "אהללה ה' בחיי, אזמרה לאלוהיי בעודי קיים.",
  "146_3": "אל תבטחו בנדיבים ורוזנים, בבן אדם בשר ודם שאין לו כוח להושיע.",
  "146_4": "תצא רוחו – ישוב לאדמתו ולעפרו; ביום ההוא אבדו כל תוכניותיו ומחשבותיו.",
  "146_5": "אשרי שאל יעקב בעזרו, ששברו ותקוותו על ה' אלוהיו,",
  "146_6": "עושה שמיים וארץ, את הים ואת כל אשר בם, השומר אמת ונאמנות לעולם,",
  "146_7": "עושה משפט לעשוקים, נותן לחם ומזון לרעבים; ה' מתיר אסורים!",
  "146_8": "ה' פוקח עיני עיוורים, ה' זוקף כפופים, ה' אוהב צדיקים.",
  "146_9": "ה' שומר גרים, יתום ואלמנה יעודד ויחזק, ודרך רשעים יעוות ויכשיל.",
  "146_10": "ימלוך ה' לעולם, אלוהייך ציון לדור ודור – הללויה!",
  "147_1": "הללויה! כי טוב לזמר לאלוהינו, כי נעים ונאה לו שיר תהילה.",
  "147_2": "בונה ירושלים ה', נדחי ישראל יכנס ויקבץ.",
  "147_3": "הרופא לשבורי לב, ומחבש ומאחה לעצבותם ולפצעיהם.",
  "147_4": "מונה מספר לכוכבים הרבים, לכולם שמות יקרא.",
  "147_5": "גדול אדוננו ורב כוח, לתבונתו אין מספר וגבול.",
  "147_6": "מעודד ומרומם ענווים ה', משפיל רשעים עד עפר הארץ.",
  "147_7": "ענו לה' בתודה, זמרו לאלוהינו בכינור,",
  "147_8": "המכסה שמיים בעבים ועננים, המכין לארץ גשם, המצמיח הרים חציר ועשב,",
  "147_9": "נותן לבהמה את לחמה ומזונה, לבני עורב אשר יקראו ויזעקו.",
  "147_10": "לא בגבורת הסוס יחפץ, לא בשוקי האיש והלוחם ירצה.",
  "147_11": "רוצה ה' את יראיו, את המייחלים לחסדו ולאהבתו.",
  "147_12": "שבחי, ירושלים, את ה'; הללי אלוהייך, ציון!",
  "147_13": "כי חיזק בריחי שערייך, ברך בנייך בקרבך.",
  "147_14": "השם גבולך שלום, חלב חיטים מובחר ישביעך.",
  "147_15": "השולח אמרתו וציוויו לארץ; עד מהרה ירוץ דברו.",
  "147_16": "הנותן שלג לבן כצמר, כפור ואפר יפזר.",
  "147_17": "משליך קרחו כפתיתים; לפני קרתו וקורו – מי יעמוד?",
  "147_18": "ישלח דברו וימיסם; ישב רוחו – ייזלו מים שוצפים.",
  "147_19": "מגיד דבריו ליעקב, חוקיו ומשפטיו לישראל.",
  "147_20": "לא עשה כן לכל גוי, ומשפטים בל ידעום – הללויה!",
  "148_1": "הללויה! הללו את ה' מן השמיים, הללוהו במרומים!",
  "148_2": "הללוהו, כל מלאכיו; הללוהו, כל צבאותיו!",
  "148_3": "הללוהו, שמש וירח; הללוהו, כל כוכבי אור!",
  "148_4": "הללוהו, שמי השמיים, והמים אשר מעל השמיים!",
  "148_5": "יהללו את שם ה', כי הוא ציווה ונבראו!",
  "148_6": "ויעמידם לעד ולעולמי עולמים, חוק נתן ולא יעבור.",
  "148_7": "הללו את ה' מן הארץ, תנינים וכל תהומות מעמקים,",
  "148_8": "אש וברד, שלג וקיטור עשן, רוח סערה העושה דברו,",
  "148_9": "ההרים וכל הגבעות, עץ פרי וכל ארזים,",
  "148_10": "החיה וכל בהמה, רמש וציפור כנף,",
  "148_11": "מלכי ארץ וכל לאומים, שרים וכל שופטי ארץ,",
  "148_12": "בחורים וגם בתולות, זקנים עם נערים –",
  "148_13": "יהללו את שם ה', כי נשגב שמו לבדו, הודו על ארץ ושמיים!",
  "148_14": "וירם קרן וכוח לעמו, תהילה לכל חסידיו – לבני ישראל, עם קרובו אליו – הללויה!",
  "149_1": "הללויה! שירו לה' שיר חדש, תהילתו בקהל חסידים!",
  "149_2": "ישמח ישראל בעושיו, בני ציון יגילו במלכם!",
  "149_3": "יהללו שמו במחול, בתוף ובכינור יזמרו לו.",
  "149_4": "כי רוצה ה' בעמו, יפאר ענווים בישועה.",
  "149_5": "יעלזו חסידים בכבוד, ירננו וישירו על משכבותם.",
  "149_6": "רוממות אל בגרונם, וחרב פיפיות חדה בידם,",
  "149_7": "לעשות נקמה מוצדקת בגויים, תוכחות ועונשים בלאומים,",
  "149_8": "לאסור מלכיהם בזיקים, ונכבדיהם בכבלי ברזל,",
  "149_9": "לעשות בהם משפט כתוב כפי שנפסק; הדר וכבוד הוא לכל חסידיו – הללויה!",
  "150_1": "הללויה! הללו אל במקדשו, הללוהו ברקיע עוזו האדיר!",
  "150_2": "הללוהו בגבורותיו ומעשיו הנשגבים, הללוהו כפי רוב גודלו ועוצמתו!",
  "150_3": "הללוהו בתקיעת שופר, הללוהו בנבל ובכינור!",
  "150_4": "הללוהו בתוף ובמחול, הללוהו במיני מיתרים ועוגב!",
  "150_5": "הללוהו במצלצלי שמע, הללוהו במצלצלי תרועה!",
  "150_6": "כל הנשמה תהלל יה – הללויה!"
};
